function renderBacktickGlowContent(text){
  const raw=String(text||"");
  return escapeHtml(raw).replace(/`([^`]+)`/g,'<span class="inline-glow">$1</span>');
}

function renderBacktickGlow(text){
  const raw=String(text||"");
  if(!raw.trim())return '<div class="host-meta">Nothing pasted yet.</div>';
  return renderBacktickGlowContent(raw).replace(/\n/g,"<br>");
}

