const BINARY_CONTEXT_ALIASES={
  suid:new Set(["suid","setuid"]),
  sudo:new Set(["sudo"]),
  capabilities:new Set(["capabilities","capability","caps","cap"])
};

function normalizeBinaryContextType(value){
  const raw=String(value||"").trim().toLowerCase().replace(/[_\s-]+/g,"-");
  if(!raw)return "";
  if(["suid","setuid"].includes(raw))return "suid";
  if(raw==="sudo")return "sudo";
  if(["capabilities","capability","caps","cap"].includes(raw))return "capabilities";
  return raw;
}

function normalizeBinaryContextExecutable(value){
  let raw=String(value||"").trim();
  if(!raw)return "";
  raw=raw.split(/[\s|;&]+/)[0]||raw;
  raw=raw.replace(/^['"]|['"]$/g,"");
  raw=raw.split(/[\\/]/).pop()||raw;
  return raw.trim().toLowerCase();
}

function normalizeBinaryContextRecords(data){
  const records=[];
  const add=(binary,contexts)=>{
    const name=normalizeBinaryContextExecutable(binary);
    if(!name)return;
    const ctx=uniqueCasePreserving([].concat(contexts||[]).map(normalizeBinaryContextType).filter(Boolean));
    if(ctx.length)records.push({binary:name,contexts:ctx});
  };
  const addFromExecutableMap=(map)=>{
    if(!map||typeof map!=="object"||Array.isArray(map))return;
    Object.entries(map).forEach(([binary,val])=>{
      if(Array.isArray(val)){
        add(binary,val);
      }else if(typeof val==="string"){
        add(binary,[val]);
      }else if(val&&typeof val==="object"){
        let contexts=val.contexts||val.functions||val.tags||val.methods;
        if(!contexts){
          contexts=Object.keys(val).filter(k=>contextLikeKey(k)&&val[k]);
        }
        add(val.binary||val.executable||val.name||binary,Array.isArray(contexts)?contexts:[contexts]);
      }
    });
  };
  const contextLikeKey=(k)=>Object.values(BINARY_CONTEXT_ALIASES).some(set=>set.has(normalizeBinaryContextType(k)));
  if(Array.isArray(data)){
    data.forEach(item=>{
      if(!item||typeof item!=="object")return;
      const binary=item.binary||item.executable||item.name||item.command||item.program||item.file;
      let contexts=item.contexts||item.functions||item.tags||item.methods||item.capabilities;
      if(!contexts){
        contexts=Object.keys(item).filter(k=>contextLikeKey(k)&&item[k]);
      }
      add(binary,Array.isArray(contexts)?contexts:[contexts]);
    });
  }else if(data&&typeof data==="object"){
    // The bundled Binary Contexts JSON uses this format:
    // { metadata: {...}, executables: { "find": ["sudo", "suid"], ... } }
    // Parse it first so nested metadata does not get mistaken for a binary.
    addFromExecutableMap(data.executables);
    addFromExecutableMap(data.binaries);
    addFromExecutableMap(data.commands);

    Object.entries(data).forEach(([key,val])=>{
      if(["metadata","executables","binaries","commands","aliases"].includes(String(key).toLowerCase()))return;
      if(contextLikeKey(key)&&Array.isArray(val)){
        val.forEach(binary=>add(binary,[key]));
        return;
      }
      if(Array.isArray(val)){
        add(key,val);
      }else if(val&&typeof val==="object"){
        const binary=val.binary||val.executable||val.name||key;
        let contexts=val.contexts||val.functions||val.tags||val.methods;
        if(!contexts)contexts=Object.keys(val).filter(k=>contextLikeKey(k)&&val[k]);
        add(binary,Array.isArray(contexts)?contexts:[contexts]);
      }else if(typeof val==="string"){
        add(key,[val]);
      }
    });
  }
  const merged=new Map();
  records.forEach(r=>{
    if(!merged.has(r.binary))merged.set(r.binary,new Set());
    r.contexts.forEach(c=>merged.get(r.binary).add(c));
  });
  return Array.from(merged.entries()).map(([binary,set])=>({binary,contexts:Array.from(set)}));
}


function collectIgnoreValues(data,keys){
  const out=[];
  const add=(v)=>{
    if(Array.isArray(v))v.forEach(add);
    else if(v&&typeof v==="object"){
      Object.values(v).forEach(add);
    }else if(v!==undefined&&v!==null){
      const text=String(v).trim();
      if(text)out.push(text);
    }
  };
  keys.forEach(k=>{
    if(data&&Object.prototype.hasOwnProperty.call(data,k))add(data[k]);
  });
  return out;
}

function normalizeIgnorePath(value){
  return String(value||"").trim().replace(/^['"`]+|['"`,;:]+$/g,"").replace(/\\/g,"/").toLowerCase();
}

function normalizeSgidIgnoreConfig(data){
  const basenames=new Set();
  const paths=new Set();
  const groups=new Set();
  const root=(data&&typeof data==="object")?data:{};

  collectIgnoreValues(root,[
    "ignore_basenames","ignoreBasenames","basenames","binaries","binary_names",
    "binaryNames","executables","commands","ignore_commands","ignoreCommands"
  ]).forEach(v=>{
    const name=normalizeBinaryContextExecutable(v);
    if(name)basenames.add(name);
  });

  collectIgnoreValues(root,[
    "ignore_paths","ignorePaths","paths","full_paths","fullPaths"
  ]).forEach(v=>{
    const path=normalizeIgnorePath(v);
    if(path)paths.add(path);
    const name=normalizeBinaryContextExecutable(v);
    if(name)basenames.add(name);
  });

  collectIgnoreValues(root,[
    "ignore_groups","ignoreGroups","groups","group_names","groupNames"
  ]).forEach(v=>{
    const group=String(v||"").trim().toLowerCase();
    if(group)groups.add(group);
  });

  // Allow a short array-only file: ["ssh-agent", "wall"]
  if(Array.isArray(data)){
    data.forEach(v=>{
      const name=normalizeBinaryContextExecutable(v);
      if(name)basenames.add(name);
    });
  }

  const count=basenames.size+paths.size+groups.size;
  return {basenames,paths,groups,loaded:true,count};
}


function emptyKnownPrivilegedRuleSet(){
  return {basenames:new Set(),paths:new Set(),groups:new Set(),capabilities:new Set(),count:0};
}

function addKnownPrivilegedValues(ruleSet,values,type){
  const add=(v)=>{
    if(Array.isArray(v)){v.forEach(add);return;}
    if(v&&typeof v==="object"){Object.values(v).forEach(add);return;}
    if(v===undefined||v===null)return;
    const text=String(v).trim();
    if(!text)return;
    if(type==="path"){
      const path=normalizeIgnorePath(text);
      if(path)ruleSet.paths.add(path);
      const base=normalizeBinaryContextExecutable(text);
      if(base)ruleSet.basenames.add(base);
    }else if(type==="group"){
      ruleSet.groups.add(text.toLowerCase());
    }else if(type==="capability"){
      ruleSet.capabilities.add(text.toLowerCase());
    }else{
      const base=normalizeBinaryContextExecutable(text);
      if(base)ruleSet.basenames.add(base);
    }
  };
  add(values);
}

function normalizeKnownPrivilegedRuleSet(value){
  const ruleSet=emptyKnownPrivilegedRuleSet();
  if(Array.isArray(value)){
    addKnownPrivilegedValues(ruleSet,value,"basename");
  }else if(value&&typeof value==="object"){
    collectIgnoreValues(value,[
      "basenames","binaries","binary_names","binaryNames","executables",
      "commands","programs","names","common_basenames","commonBasenames"
    ]).forEach(v=>addKnownPrivilegedValues(ruleSet,v,"basename"));

    collectIgnoreValues(value,[
      "paths","full_paths","fullPaths","common_paths","commonPaths"
    ]).forEach(v=>addKnownPrivilegedValues(ruleSet,v,"path"));

    collectIgnoreValues(value,[
      "groups","group_names","groupNames","common_groups","commonGroups"
    ]).forEach(v=>addKnownPrivilegedValues(ruleSet,v,"group"));

    collectIgnoreValues(value,[
      "capabilities","caps","capability_names","capabilityNames","common_capabilities","commonCapabilities"
    ]).forEach(v=>addKnownPrivilegedValues(ruleSet,v,"capability"));
  }else if(value!==undefined&&value!==null){
    addKnownPrivilegedValues(ruleSet,value,"basename");
  }
  ruleSet.count=ruleSet.basenames.size+ruleSet.paths.size+ruleSet.groups.size+ruleSet.capabilities.size;
  return ruleSet;
}

function mergeKnownPrivilegedRuleSets(...sets){
  const merged=emptyKnownPrivilegedRuleSet();
  sets.filter(Boolean).forEach(set=>{
    (set.basenames||new Set()).forEach(v=>merged.basenames.add(v));
    (set.paths||new Set()).forEach(v=>merged.paths.add(v));
    (set.groups||new Set()).forEach(v=>merged.groups.add(v));
    (set.capabilities||new Set()).forEach(v=>merged.capabilities.add(v));
  });
  merged.count=merged.basenames.size+merged.paths.size+merged.groups.size+merged.capabilities.size;
  return merged;
}

function normalizeKnownPrivilegedConfig(data,source="privileged-known-normal.json"){
  const cfg={
    loaded:true,
    source,
    all:emptyKnownPrivilegedRuleSet(),
    suid:emptyKnownPrivilegedRuleSet(),
    sgid:emptyKnownPrivilegedRuleSet(),
    capabilities:emptyKnownPrivilegedRuleSet(),
    count:0
  };

  if(Array.isArray(data)){
    cfg.all=normalizeKnownPrivilegedRuleSet(data);
  }else if(data&&typeof data==="object"){
    cfg.all=mergeKnownPrivilegedRuleSets(
      normalizeKnownPrivilegedRuleSet(data.all),
      normalizeKnownPrivilegedRuleSet(data.common),
      normalizeKnownPrivilegedRuleSet({
        basenames:data.basenames||data.binaries||data.executables||data.commands,
        paths:data.paths||data.full_paths||data.fullPaths
      })
    );
    cfg.suid=mergeKnownPrivilegedRuleSets(
      normalizeKnownPrivilegedRuleSet(data.suid),
      normalizeKnownPrivilegedRuleSet(data.setuid),
      normalizeKnownPrivilegedRuleSet(data.suid_binaries),
      normalizeKnownPrivilegedRuleSet(data.suidBinaries)
    );
    cfg.sgid=mergeKnownPrivilegedRuleSets(
      normalizeKnownPrivilegedRuleSet(data.sgid),
      normalizeKnownPrivilegedRuleSet(data.setgid),
      normalizeKnownPrivilegedRuleSet(data.sgid_binaries),
      normalizeKnownPrivilegedRuleSet(data.sgidBinaries)
    );
    cfg.capabilities=mergeKnownPrivilegedRuleSets(
      normalizeKnownPrivilegedRuleSet(data.capabilities),
      normalizeKnownPrivilegedRuleSet(data.caps),
      normalizeKnownPrivilegedRuleSet(data.file_capabilities),
      normalizeKnownPrivilegedRuleSet(data.fileCapabilities)
    );
  }

  cfg.count=cfg.all.count+cfg.suid.count+cfg.sgid.count+cfg.capabilities.count;
  return cfg;
}

async function loadKnownPrivilegedConfig(silent=true){
  try{
    const res=await fetch("privileged-known-normal.json",{cache:"no-store"});
    if(!res.ok)throw new Error("privileged-known-normal.json not found");
    const data=await res.json();
    knownPrivilegedConfig=normalizeKnownPrivilegedConfig(data,"privileged-known-normal.json");
    return knownPrivilegedConfig;
  }catch(e){
    // Keep a small built-in fallback so common privileged noise is still muted
    // even when the new JSON file was not copied beside app.js yet.
    knownPrivilegedConfig=normalizeKnownPrivilegedConfig(DEFAULT_KNOWN_PRIVILEGED_NORMAL,"built-in defaults");
    knownPrivilegedConfig.warning=e.message;
    if(!silent)alert(`Known-normal privileged file was not loaded: ${e.message}\n\nUsing built-in defaults instead.`);
    return knownPrivilegedConfig;
  }
}

function knownPrivilegedRuleSetForContext(context){
  const key=normalizeBinaryContextType(context);
  const specific=knownPrivilegedConfig&&knownPrivilegedConfig[key]?knownPrivilegedConfig[key]:null;
  return mergeKnownPrivilegedRuleSets(knownPrivilegedConfig&&knownPrivilegedConfig.all,specific);
}

function lineHasKnownCapability(line,ruleSet){
  if(!ruleSet||!ruleSet.capabilities||!ruleSet.capabilities.size)return false;
  const raw=String(line||"").toLowerCase();
  for(const cap of ruleSet.capabilities){
    if(cap&&raw.includes(cap))return true;
  }
  return false;
}

function isKnownPrivilegedNormal(line,context,knownCandidates=null){
  const cfg=knownPrivilegedConfig;
  if(!cfg||!cfg.loaded||!cfg.count)return false;
  const ruleSet=knownPrivilegedRuleSetForContext(context);
  if(!ruleSet||!ruleSet.count)return false;

  const candidates=Array.isArray(knownCandidates)
    ?knownCandidates
    :extractBinaryContextCandidates(line,{allowBareCommands:normalizeBinaryContextType(context)==="sudo"});
  for(const candidate of candidates){
    const cleanPath=normalizeIgnorePath(candidate);
    const base=normalizeBinaryContextExecutable(candidate);
    if(cleanPath&&ruleSet.paths.has(cleanPath))return true;
    for(const knownBase of ruleSet.basenames){
      if(binaryContextBasenameMatches(candidate,knownBase))return true;
      if(base&&base===knownBase)return true;
    }
  }

  if(String(context||"").toLowerCase()==="sgid"){
    const group=getFindLsGroupFromLine(line);
    if(group&&ruleSet.groups.has(group))return true;
  }

  if(normalizeBinaryContextType(context)==="capabilities"&&lineHasKnownCapability(line,ruleSet))return true;
  return false;
}

