  ["accessLeadId","accessLeadTitle","accessLeadPort","accessLeadService","accessLeadProduct","accessLeadVersion","accessLeadCvss","accessLeadCve","accessLeadCwe","accessLeadIdentifier","accessLeadUrl","accessLeadPath","accessLeadHttpMethod","accessLeadParameter","accessLeadSourceUrl","accessLeadDescription","accessLeadNotes"].forEach(clearFormValue);
  setFormValue("accessLeadType","other");setFormValue("accessLeadOrigin","manual-research");setFormValue("accessLeadStatus","lead");setFormValue("accessLeadProtocol","");setFormValue("accessLeadEndpoint","");setFormValue("accessLeadWebTarget","");
  $("accessLeadError")?.classList.add("hidden");if($("saveAccessLeadBtn"))$("saveAccessLeadBtn").textContent="Save Lead";if($("accessLeadModalTitle"))$("accessLeadModalTitle").textContent="Add Access Lead";
