  editingAccessLeadId=lead?.id||null;if(lead){setFormValue("accessLeadId",lead.id);setAccessLeadFormValues(lead);if($("accessLeadModalTitle"))$("accessLeadModalTitle").textContent="Edit Access Lead";if($("saveAccessLeadBtn"))$("saveAccessLeadBtn").textContent="Update Lead";}else setAccessLeadFormValues(prefill);
  $("accessLeadModal")?.classList.remove("hidden");setTimeout(()=>$("accessLeadTitle")?.focus(),0);
