  meta.textContent=`Showing ${page.rows.length.toLocaleString()} of ${page.matchingLines.toLocaleString()} matching source lines from ${page.totalLines.toLocaleString()} total lines${scanEvidenceReviewState.query?" · filtered":""}. No retained source content is discarded; use Load more or Download Exact Original.`;
  output.innerHTML=page.rows.map(row=>`<span class="scan-raw-line" data-source-line="${row.lineNumber}"><span class="scan-raw-line-number">${row.lineNumber}</span><span class="scan-raw-line-content">${escapeHtml(row.text)}</span></span>`).join("");
