function openOscpNavigatorFullCoverage(objectiveId=""){
  if(!isOscpEngagement())return false;
  const host=activeHost(),core=navigatorCore(),navigation=ensureNavigatorState();
  if(!host||!core||!navigation){showToast("Select one exact host before opening Navigator Full Coverage.","warning");return true;}
  if(!selectCanonicalHost(host.id,{persistNow:false,renderNow:false,visibleFailure:false,focusKey:"full-coverage"})){
    navigatorRouteFailure("The exact host could not be selected for Navigator Full Coverage.");return true;
  }
  state.navigation.navigator={
    ...ensureNavigatorState(),selectedHostId:host.id,showFullCoverage:true,
    activeRoute:core.normalizeRoute({destination:"navigator"}).route,routeError:"",
    focusKey:objectiveId?`coverage-${objectiveId}`:"full-coverage"
  };
  persist();setWorkspaceTab("oscp-navigator");renderOscpNavigator();
  requestAnimationFrame(()=>$("navigatorFullCoverageTitle")?.focus());
  return true;
}
function openGuidedVulnerabilityMethodology(){
  if(openOscpNavigatorFullCoverage("targeted-safe-vulnerability-enumeration"))return;
  const h=activeHost();if(h){ensureHostMethodologyContextState(h);h.focusStage="enumeration";persist();}
  if($("notesLibraryFilter"))$("notesLibraryFilter").value="relevant";
  if($("notesStageFilter"))$("notesStageFilter").value="guided";
  setWorkspaceTab("notes");renderRecommended(h);
  setTimeout(()=>document.querySelector('[data-methodology-task="targeted-safe-vulnerability-enumeration"]')?.scrollIntoView({behavior:"smooth",block:"center"}),80);
}

function ensureHostIntel(h){
  ensureProjectIntel();
  if(!h)return;
  hostProfileModel()?.ensureNetworkAddressState?.(h);
  ensureScanEvidenceState(h);
  hostProfileModel()?.ensureEndpointOwnership?.(h,engagementOwnershipId(),{linkedRecords:state.findings||[]});
  exploitAttemptsModel().ensureHostAttempts(h);
  if(!h.credentials)h.credentials=[];
  if(!h.accessContextSignals||typeof h.accessContextSignals!=="object"||Array.isArray(h.accessContextSignals))h.accessContextSignals={};
  if(typeof h.currentAccessContextId!=="string")h.currentAccessContextId="";
  if(!h.systemInfo)h.systemInfo=defaultSystemInfo();
  if(!h.systemInfo.users)h.systemInfo.users=[];
  if(!h.systemInfo.raw)h.systemInfo.raw={users:"",groups:"",groupMembers:""};
  if(!h.systemInfo.osnet)h.systemInfo.osnet={osName:"",version:"",arch:"",primaryIp:"",dns:"",gateway:"",hotfixes:"",adapters:"",routes:"",arp:"",listeningPorts:"",interestingConnections:""};
  if(!h.systemInfo.appsproc)h.systemInfo.appsproc={installedApps:"",installedAppsX64:"",installedAppsX86:"",interestingApps:"",processes:"",interestingProcesses:""};
  if(h.systemInfo.appsproc && h.systemInfo.appsproc.installedApps && !h.systemInfo.appsproc.installedAppsX64)h.systemInfo.appsproc.installedAppsX64=h.systemInfo.appsproc.installedApps;
  if(!h.systemInfo.boxes)h.systemInfo.boxes={};
  if(!h.systemInfo.linux)h.systemInfo.linux={};
  if(h.systemInfo.linux.suidSgid){
    const legacy=String(h.systemInfo.linux.suidSgid||"");
    if(!String(h.systemInfo.linux.suid||"").trim())h.systemInfo.linux.suid=`Migrated from older combined SUID / SGID box:\n\n${legacy}`;
    if(!String(h.systemInfo.linux.sgid||"").trim())h.systemInfo.linux.sgid="";
  }
  LINUX_SYSTEM_PASTE_BOXES.forEach(box=>{if(!Object.prototype.hasOwnProperty.call(h.systemInfo.linux,box.key))h.systemInfo.linux[box.key]="";});
  if(!h.systemInfo.ad)h.systemInfo.ad={};
  AD_SYSTEM_PASTE_BOXES.forEach(box=>{if(!Object.prototype.hasOwnProperty.call(h.systemInfo.ad,box.key))h.systemInfo.ad[box.key]="";});
  if(!h.systemInfo.dynamicBoxes)h.systemInfo.dynamicBoxes={};
  window.AEROSImportLifecycle?.ensureHostEnumerationState?.(h);
  if(!h.systemInfo.credentialFindings)h.systemInfo.credentialFindings=[];
  if(!h.systemInfo.huntTargets)h.systemInfo.huntTargets=[];
  if(!h.systemInfo.findings)h.systemInfo.findings=[];
  if(!h.postExploitation)h.postExploitation={imports:[],notes:""};
  if(!Array.isArray(h.postExploitation.imports))h.postExploitation.imports=[];
  if(!h.peas||typeof h.peas!=="object"||Array.isArray(h.peas))h.peas={imports:[],findings:[],lastImportSummary:{}};
  if(!Array.isArray(h.peas.imports))h.peas.imports=[];
  if(!Array.isArray(h.peas.findings))h.peas.findings=[];
  if(!h.peas.lastImportSummary||typeof h.peas.lastImportSummary!=="object")h.peas.lastImportSummary={};
  if(h.systemInfo.boxes && h.systemInfo.boxes.importantFindings && !h.systemInfo.importantFindingsMigrated){
    h.systemInfo.findings.push({
      id:newId("finding"),
      title:"Important Findings - Migrated",
      path:"",
      command:"",
      content:h.systemInfo.boxes.importantFindings,
      updatedAt:new Date().toISOString()
    });
    delete h.systemInfo.boxes.importantFindings;
    h.systemInfo.importantFindingsMigrated=true;
  }
  migrateSystemCredentialFindingsToCredentials(h);
  if(h.systemInfo.raw && Object.prototype.hasOwnProperty.call(h.systemInfo.raw,"privileges"))delete h.systemInfo.raw.privileges;
  if(h.systemInfo.boxes){
    ["commandHistory","transcriptFindings","filePasswordHunting","importantFindings"].forEach(k=>{if(Object.prototype.hasOwnProperty.call(h.systemInfo.boxes,k))delete h.systemInfo.boxes[k];});
  }
  syncHostOperatingSystemEvidence(h);
}
function hostLabel(h){return h?`${h.ip}${h.hostname?" - "+h.hostname:""}`:"Unknown Host";}
function hostNameIpLabel(h){return h?`${h.hostname||"Unknown Host"} - ${h.ip||"No IP"}`:"Unknown Host";}
function reportGroupValue(h){return String(h?.group||"independent").trim().toLowerCase()||"independent";}
function reportGroupLabel(value){
  const v=String(value||"independent").toLowerCase();
  if(v==="ad")return "Active Directory Set";
  if(v==="independent")return "Independent Challenge";
  return v.replace(/[-_]/g," ").replace(/\b\w/g,m=>m.toUpperCase());
}
function hostVisibleInReportGroup(candidate,currentHost){
  if(!candidate||!currentHost)return false;
  if(candidate.id===currentHost.id)return true;
  const cg=reportGroupValue(currentHost);
  const sg=reportGroupValue(candidate);
  if(cg==="independent"||sg==="independent")return false;
  return cg===sg;
}
function visibleReportGroupHosts(currentHost=activeHost()){
  return Object.values(state.hosts||{}).filter(h=>hostVisibleInReportGroup(h,currentHost));
}
function credentialVisibilityLabel(credential,sourceHost){
  const scope=String(credential?.scope||"host").toLowerCase();
  if(scope==="lab")return "Visible: entire engagement";
  if(scope==="group"){
    const group=reportGroupValue(sourceHost);
    return group==="independent"?"Visible: source host only (no group assigned)":`Visible: ${reportGroupLabel(group)}`;
  }
  if(scope==="report-group"){
    const group=reportGroupValue(sourceHost);
    return group==="independent"?"Visible: source host only":`Visible: ${reportGroupLabel(group)} (legacy scope)`;
  }
  return "Visible: source host only";
}
function credentialScopeValue(value){
  const scope=String(value||"host").toLowerCase();
  return ["host","group","lab"].includes(scope)?scope:(scope==="report-group"?"group":"host");
}
function credentialScopeAllows(credential,currentHost,sourceHost){
  const scope=credentialScopeValue(credential?.scope);
  if(!currentHost||!sourceHost)return false;
  if(sourceHost.id===currentHost.id)return true;
  if(scope==="lab")return true;
  if(scope==="group")return hostVisibleInReportGroup(sourceHost,currentHost);
  return false;
}
function newId(prefix){return `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}`;}
function findHostByIdentity(value){
  const v=String(value||"").trim().toLowerCase();
  if(!v)return null;
  return Object.values(state.hosts||{}).find(h=>String(h.id).toLowerCase()===v||String(h.ip).toLowerCase()===v||String(h.hostname||"").toLowerCase()===v)||null;
}
function credentialVisibleToHost(cred,currentHost,sourceHost){
  return credentialScopeAllows(cred,currentHost,sourceHost);
}
function allCredentialRecords(){
  const records=[];
  Object.values(state.hosts||{}).forEach(h=>{ensureHostIntel(h);(h.credentials||[]).forEach(c=>records.push({...c,sourceHostId:h.id,sourceIp:h.ip,sourceHostname:h.hostname||"",sourceGroup:h.group||"independent"}));});
  return records;
}
function clearSystemUserForm(){
  editingSystemUserId=null;
  ["sysUserName","sysUserDomain","sysUserGroups","sysUserPrivileges","sysUserLastLogon","sysUserNotes"].forEach(clearFormValue);
  setFormValue("sysUserEnabled","unknown");
  ["sysUserAdmin","sysUserRdp","sysUserWinrm","sysUserSsh","sysUserSudo","sysUserService","sysUserInteresting"].forEach(id=>{const el=$(id);if(el)el.checked=false;});
  const btn=$("saveSystemUserBtn");if(btn)btn.textContent="Add User Access";
}
function saveSystemUser(){
  const h=activeHost();if(!h)return alert("Select a host first.");ensureHostIntel(h);
  const username=formValue("sysUserName");if(!username)return alert("Username is required.");
  const existing=editingSystemUserId?h.systemInfo.users.find(u=>u.id===editingSystemUserId):null;
  const user={...(existing||{}),id:existing?.id||newId("user"),username,domain:formValue("sysUserDomain"),enabled:formValue("sysUserEnabled")||"unknown",groups:formValue("sysUserGroups"),privileges:formValue("sysUserPrivileges"),lastLogon:formValue("sysUserLastLogon"),access:{admin:!!$("sysUserAdmin")?.checked,rdp:!!$("sysUserRdp")?.checked,winrm:!!$("sysUserWinrm")?.checked,ssh:!!$("sysUserSsh")?.checked,sudo:!!$("sysUserSudo")?.checked,service:!!$("sysUserService")?.checked,interesting:!!$("sysUserInteresting")?.checked},notes:formValue("sysUserNotes"),updatedAt:new Date().toISOString()};
  if(existing)Object.assign(existing,user);else h.systemInfo.users.push(user);
  markAccessContextSignalKeys(h,"",["linuxUserInfo"]);
  save();clearSystemUserForm();renderSystemInfo(h);
}
function editSystemUser(id){
  const h=activeHost();if(!h)return;ensureHostIntel(h);const u=h.systemInfo.users.find(x=>x.id===id);if(!u)return;
  editingSystemUserId=id;setFormValue("sysUserName",u.username);setFormValue("sysUserDomain",u.domain);setFormValue("sysUserEnabled",u.enabled||"unknown");setFormValue("sysUserGroups",u.groups);setFormValue("sysUserPrivileges",u.privileges);setFormValue("sysUserLastLogon",u.lastLogon);setFormValue("sysUserNotes",u.notes);
  const flags=u.access||{};[["sysUserAdmin","admin"],["sysUserRdp","rdp"],["sysUserWinrm","winrm"],["sysUserSsh","ssh"],["sysUserSudo","sudo"],["sysUserService","service"],["sysUserInteresting","interesting"]].forEach(([id,k])=>{const el=$(id);if(el)el.checked=!!flags[k];});
  const btn=$("saveSystemUserBtn");if(btn)btn.textContent="Update User Access";
}
async function deleteSystemUser(id){const h=activeHost();if(!h)return;ensureHostIntel(h);if(!(await themedConfirm("Delete this user access entry?",{title:"Delete User Entry",confirmText:"Delete",danger:true})))return;h.systemInfo.users=h.systemInfo.users.filter(u=>u.id!==id);save();renderSystemInfo(h);}
function renderSystemUsers(h){
  const list=$("systemUserList");if(!list)return;list.innerHTML="";
  const users=h.systemInfo.users||[];
  if(!users.length){list.innerHTML='<div class="host-meta">No structured user access entries yet. Add users/groups/privileges above.</div>';return;}
  users.forEach(u=>{
    const flags=Object.entries(u.access||{}).filter(([,v])=>v).map(([k])=>k.toUpperCase());
    const card=document.createElement("div");card.className="intel-card";
    card.innerHTML=`<div class="intel-card-head"><div><strong>${escapeHtml([u.domain,u.username].filter(Boolean).join("\\")||u.username)}</strong><div class="host-meta">${escapeHtml(u.enabled||"unknown")} ${u.lastLogon?"· Last seen: "+escapeHtml(u.lastLogon):""}</div></div><div>${flags.map(f=>`<span class="tag">${escapeHtml(f)}</span>`).join("")}</div></div>${u.groups?`<div class="host-meta"><strong>Groups:</strong> ${escapeHtml(u.groups)}</div>`:""}${u.privileges?`<div class="host-meta"><strong>Privileges/Rights:</strong> ${escapeHtml(u.privileges)}</div>`:""}${u.notes?`<div class="host-meta"><strong>Notes:</strong> ${escapeHtml(u.notes)}</div>`:""}<div class="button-row compact-row"><button class="secondary-btn small" data-edit-sys-user="${escapeAttr(u.id)}">Edit</button><button class="danger-btn small" data-delete-sys-user="${escapeAttr(u.id)}">Delete</button></div>`;
    list.appendChild(card);
  });
  document.querySelectorAll("[data-edit-sys-user]").forEach(b=>b.onclick=()=>editSystemUser(b.dataset.editSysUser));
  document.querySelectorAll("[data-delete-sys-user]").forEach(b=>b.onclick=()=>deleteSystemUser(b.dataset.deleteSysUser));
}

const SYSTEM_PREVIEW_DEBOUNCE_MS=75;
const SYSTEM_DERIVED_DEBOUNCE_MS=100;
const INTERACTIVE_PERSIST_DEBOUNCE_MS=750;
const SYSTEM_DYNAMIC_SOURCE_IDS=new Set(SYSTEM_DYNAMIC_BOX_PROFILES.map(profile=>profile.sourceId));
const pendingSystemEdit={hostId:"",previewIds:new Set(),derivedIds:new Set(),derivedDynamicKeys:new Set()};
let systemPreviewTimer=null,systemDerivedTimer=null,interactivePersistTimer=null,interactivePersistenceDirty=false;

function systemInfoSignalKeyForField(field){
  if(!field)return "";
  const key=field.key,store=field.store;
  if(store==="osnet"&&["osName","version","arch","hotfixes","adapters","routes","listeningPorts"].includes(key))return "windowsSystemInfo";
  if(store==="linux"&&["osKernel","network","routes","firewall","listeningPorts"].includes(key))return "linuxSystemInfo";
  if(store==="linux"&&["users","groups","sudoers"].includes(key)||store==="raw"&&["users","groups","groupMembers"].includes(key))return "linuxUserInfo";
  if(store==="linux"&&key==="packages"||store==="appsproc"&&["installedAppsX64","installedAppsX86"].includes(key))return "linuxPackageInfo";
  if(store==="linux"&&key==="processes"||store==="appsproc"&&["processes","interestingProcesses"].includes(key))return "linuxProcessInfo";
  if(store==="linux"&&key==="services"||store==="appsproc"&&key==="runningServices")return "linuxServiceInfo";
  return "";
}

function updateSystemInfoFieldFromElement(h,el){
  if(!h||!el)return null;
  ensureHostIntel(h);
  if(el.classList?.contains("sys-dynamic-area")){
    const key=el.dataset.dynamicKey||"";
    if(!key)return null;
    if(!h.systemInfo.dynamicBoxes)h.systemInfo.dynamicBoxes={};
    h.systemInfo.dynamicBoxes[key]=el.value;
    return {id:el.id,store:"dynamicBoxes",key,dynamic:true};
  }
  const field=SYSTEM_FIELD_BY_ID.get(el.id);
  if(!field)return null;
  if(!h.systemInfo[field.store])h.systemInfo[field.store]={};
  h.systemInfo[field.store][field.key]=el.value;
  return field;
}

function clearInteractivePersistenceTimer(){
  if(interactivePersistTimer!==null)clearTimeout(interactivePersistTimer);
  interactivePersistTimer=null;
}

function acknowledgeInteractivePersistence(){
  clearInteractivePersistenceTimer();
  interactivePersistenceDirty=false;
}

function flushInteractiveBrowserPersistence(){
  clearInteractivePersistenceTimer();
  if(!interactivePersistenceDirty)return false;
  save();
  return true;
}

function scheduleInteractiveBrowserPersistence(){
  interactivePersistenceDirty=true;
  clearInteractivePersistenceTimer();
  interactivePersistTimer=setTimeout(()=>{
    interactivePersistTimer=null;
    flushInteractiveBrowserPersistence();
  },INTERACTIVE_PERSIST_DEBOUNCE_MS);
}

function flushPendingSystemPreview(){
  if(systemPreviewTimer!==null)clearTimeout(systemPreviewTimer);
  systemPreviewTimer=null;
  const hostId=pendingSystemEdit.hostId,ids=[...pendingSystemEdit.previewIds];
  pendingSystemEdit.previewIds.clear();
  const h=hostId&&state.hosts?.[hostId];
  if(!h||activeHost()?.id!==hostId||activeWorkspacePanelName()!=="systeminfo")return;
  ids.forEach(id=>renderSystemFieldPreview(h,id));
  updateHomeLootDiffButtons();
}

function flushPendingSystemDerived(){
  if(systemDerivedTimer!==null)clearTimeout(systemDerivedTimer);
  systemDerivedTimer=null;
  const hostId=pendingSystemEdit.hostId,ids=[...pendingSystemEdit.derivedIds];
  const dynamicKeys=[...pendingSystemEdit.derivedDynamicKeys];
  pendingSystemEdit.derivedIds.clear();
  pendingSystemEdit.derivedDynamicKeys.clear();
  if(!ids.length&&!dynamicKeys.length)return;
  const h=hostId&&state.hosts?.[hostId];
  if(!h)return;
  const fields=ids.map(id=>SYSTEM_FIELD_BY_ID.get(id)).filter(Boolean);
  const signalKeys=uniqueCasePreserving(fields.map(systemInfoSignalKeyForField).filter(Boolean));
  signalKeys.forEach(signalKey=>{
    const hasValue=fields.some(field=>systemInfoSignalKeyForField(field)===signalKey&&String(h.systemInfo?.[field.store]?.[field.key]||"").trim());
    if(hasValue)markAccessContextSignalKeys(h,"",[signalKey]);
  });
  const isCurrent=activeHost()?.id===hostId,activePanel=activeWorkspacePanelName();
  if(ids.includes("sysLinuxPackages")){
    syncLinuxSoftwareIntelligence(h);
    if(isCurrent&&activePanel==="systeminfo")renderLinuxSoftwareInsights(h);
  }
  const rebuildAllDynamic=ids.some(id=>SYSTEM_DYNAMIC_SOURCE_IDS.has(id));
  if(rebuildAllDynamic&&isCurrent&&activePanel==="systeminfo")renderDynamicSystemBoxes(h);
  else if(dynamicKeys.length&&isCurrent&&activePanel==="systeminfo")refreshLinuxHomeLootFileBoxes(h,dynamicKeys);
  if(ids.some(id=>["sysLinuxOsKernel","sysOSName","sysOSVersion","sysBoxOsVersionFull"].includes(id))){
    reconcileSystemInfoOsObservations(h);
    if(isCurrent&&(activePanel==="profile"||activePanel==="systeminfo")){renderHostOsResolution(h);renderPillsOnly(h);}
  }
}

function scheduleSystemInfoInput(event,{flush=false}={}){
  const el=event?.currentTarget||event?.target;
  const h=activeHost(),field=updateSystemInfoFieldFromElement(h,el);
  if(!h||!field)return;
  if(pendingSystemEdit.hostId&&pendingSystemEdit.hostId!==h.id){flushPendingSystemPreview();flushPendingSystemDerived();}
  pendingSystemEdit.hostId=h.id;
  pendingSystemEdit.previewIds.add(el.id);
  pendingSystemEdit.derivedIds.add(el.id);
  if(field.dynamic)pendingSystemEdit.derivedDynamicKeys.add(field.key);
  scheduleInteractiveBrowserPersistence();
  if(flush){flushPendingSystemPreview();flushPendingSystemDerived();flushInteractiveBrowserPersistence();return;}
  if(systemPreviewTimer!==null)clearTimeout(systemPreviewTimer);
  systemPreviewTimer=setTimeout(flushPendingSystemPreview,SYSTEM_PREVIEW_DEBOUNCE_MS);
  if(systemDerivedTimer!==null)clearTimeout(systemDerivedTimer);
  systemDerivedTimer=setTimeout(flushPendingSystemDerived,SYSTEM_DERIVED_DEBOUNCE_MS);
}

function saveSystemInfoFromInputs(rebuildDynamic=true,modeOverrides=null){
  const h=activeHost();if(!h)return;ensureHostIntel(h);const s=h.systemInfo;
  if(systemPreviewTimer!==null)clearTimeout(systemPreviewTimer);systemPreviewTimer=null;
  if(systemDerivedTimer!==null)clearTimeout(systemDerivedTimer);systemDerivedTimer=null;
  pendingSystemEdit.previewIds.clear();pendingSystemEdit.derivedIds.clear();pendingSystemEdit.derivedDynamicKeys.clear();pendingSystemEdit.hostId=h.id;
  const beforeSignals=systemInfoSignalFingerprints(h);
  const preferredModes=mergeSystemCardModeOverrides(captureSystemCardModes(),modeOverrides);

  // Legacy/simple fields if present.
  const mapRaw={sysRawUsers:"users",sysRawGroups:"groups",sysRawGroupMembers:"groupMembers"};
  Object.entries(mapRaw).forEach(([id,k])=>{if($(id))s.raw[k]=$(id).value;});

  const mapOs={sysOSName:"osName",sysOSVersion:"version",sysArch:"arch",sysPrimaryIp:"primaryIp",sysDns:"dns",sysGateway:"gateway",sysHotfixes:"hotfixes",sysAdapters:"adapters",sysRoutes:"routes",sysArp:"arp",sysListeningPorts:"listeningPorts",sysInterestingConnections:"interestingConnections"};
  Object.entries(mapOs).forEach(([id,k])=>{if($(id))s.osnet[k]=$(id).value;});

  const mapAp={sysInstalledAppsX64:"installedAppsX64",sysInstalledAppsX86:"installedAppsX86",sysInterestingApps:"interestingApps",sysProcesses:"processes",sysInterestingProcesses:"interestingProcesses"};
  Object.entries(mapAp).forEach(([id,k])=>{if($(id))s.appsproc[k]=$(id).value;});

  SYSTEM_PASTE_BOXES.forEach(box=>{
    const el=$(box.id);
    if(!el)return;
    if(!s[box.store])s[box.store]={};
    s[box.store][box.key]=el.value;
  });

  if(!s.linux)s.linux={};
  LINUX_SYSTEM_PASTE_BOXES.forEach(box=>{
    const el=$(box.id);
    if(el)s.linux[box.key]=el.value;
  });

  if(!s.ad)s.ad={};
  AD_SYSTEM_PASTE_BOXES.forEach(box=>{
    const el=$(box.id);
    if(el)s.ad[box.key]=el.value;
  });

  if(!s.dynamicBoxes)s.dynamicBoxes={};
  document.querySelectorAll(".sys-dynamic-area").forEach(el=>{
    const key=el.dataset.dynamicKey;
    if(key)s.dynamicBoxes[key]=el.value;
  });

  syncLinuxSoftwareIntelligence(h);
  if(rebuildDynamic)renderDynamicSystemBoxes(h);
  renderSystemBoxPreviews(h,preferredModes);
  renderLinuxSoftwareInsights(h);
  const afterSignals=systemInfoSignalFingerprints(h);
  const changedSignalKeys=Object.keys(afterSignals).filter(key=>afterSignals[key]&&afterSignals[key]!==beforeSignals[key]);
  if(changedSignalKeys.length)markAccessContextSignalsFromSystemInfo(h,"",changedSignalKeys);
  reconcileSystemInfoOsObservations(h);
  renderHostOsResolution(h);
  renderPillsOnly(h);
  save();
}
function setSystemInfoInputs(h){
  const s=h.systemInfo;
  const mapRaw={sysRawUsers:"users",sysRawGroups:"groups",sysRawGroupMembers:"groupMembers"};
  Object.entries(mapRaw).forEach(([id,k])=>setFormValue(id,s.raw[k]));

  const mapOs={sysOSName:"osName",sysOSVersion:"version",sysArch:"arch",sysPrimaryIp:"primaryIp",sysDns:"dns",sysGateway:"gateway",sysHotfixes:"hotfixes",sysAdapters:"adapters",sysRoutes:"routes",sysArp:"arp",sysListeningPorts:"listeningPorts",sysInterestingConnections:"interestingConnections"};
  Object.entries(mapOs).forEach(([id,k])=>setFormValue(id,s.osnet[k]));

  const mapAp={sysInstalledAppsX64:"installedAppsX64",sysInstalledAppsX86:"installedAppsX86",sysInterestingApps:"interestingApps",sysProcesses:"processes",sysInterestingProcesses:"interestingProcesses"};
  Object.entries(mapAp).forEach(([id,k])=>setFormValue(id,s.appsproc[k]));

  SYSTEM_PASTE_BOXES.forEach(box=>{
    const source=s[box.store]||{};
    setFormValue(box.id,source[box.key]||"");
  });

  LINUX_SYSTEM_PASTE_BOXES.forEach(box=>{
    const source=s.linux||{};
    setFormValue(box.id,source[box.key]||"");
  });

  AD_SYSTEM_PASTE_BOXES.forEach(box=>{
    const source=s.ad||{};
    setFormValue(box.id,source[box.key]||"");
  });
}
function showSysFindingForm(show=true){
  const form=$("sysFindingForm");
  if(form)form.classList.toggle("hidden",!show);
}
function clearSysFindingForm(){
  editingSysFindingId=null;
  ["sysFindingTitle","sysFindingPath","sysFindingCommand","sysFindingContent"].forEach(clearFormValue);
  const btn=$("saveSysFindingBtn");if(btn)btn.textContent="Save Important Finding";
  showSysFindingForm(false);
}
async function saveSysFinding(){
  const h=activeHost();if(!h)return alert("Select a host first.");ensureHostIntel(h);saveSystemInfoFromInputs(false);
  const title=formValue("sysFindingTitle");
  const path=formValue("sysFindingPath");
  const command=formValue("sysFindingCommand");
  const content=formValue("sysFindingContent");
  if(!title)return alert("Header / Name is required.");
  if(!content&&!command&&!path)return alert("Paste content, a command/source, or a file path.");
  const existing=editingSysFindingId?h.systemInfo.findings.find(f=>f.id===editingSysFindingId):null;
  const f={
    ...(existing||{}),
    id:existing?.id||newId("finding"),
    title,
    path,
    command,
    content,
    updatedAt:new Date().toISOString()
  };
  if(existing)Object.assign(existing,f);else h.systemInfo.findings.push(f);
  save();clearSysFindingForm();renderSystemInfo(h);
  if(state.serverAvailable && (state.projectName||formValue("projectName")||formValue("labSelect")))await saveLabState(true).catch(()=>{});
}
function editSysFinding(id){
  const h=activeHost();if(!h)return;ensureHostIntel(h);
  const f=h.systemInfo.findings.find(x=>x.id===id);if(!f)return;
  editingSysFindingId=id;
  setFormValue("sysFindingTitle",f.title||"");
  setFormValue("sysFindingPath",f.path||"");
  setFormValue("sysFindingCommand",f.command||"");
  setFormValue("sysFindingContent",f.content||f.notes||f.note||f.result||f.results||f.output||f.evidence||"");
  const btn=$("saveSysFindingBtn");if(btn)btn.textContent="Update Important Finding";
  showSysFindingForm(true);
}
async function deleteSysFinding(id){
  const h=activeHost();if(!h)return;ensureHostIntel(h);
  if(!(await themedConfirm("Delete this important finding?",{title:"Delete Finding",confirmText:"Delete",danger:true})))return;
  h.systemInfo.findings=h.systemInfo.findings.filter(f=>f.id!==id);
  save();renderSystemInfo(h);
  if(state.serverAvailable && (state.projectName||formValue("projectName")||formValue("labSelect")))await saveLabState(true).catch(()=>{});
}
function renderSysFindings(h){
  const list=$("sysFindingList");if(!list)return;ensureHostIntel(h);list.innerHTML="";
  const findings=h.systemInfo.findings||[];
  if(!findings.length){list.innerHTML='<div class="host-meta">No important findings yet. Click + Add to save named output/file notes like xampp ini files, xampp txt, interesting config, proof path, etc.</div>';return;}
  findings.forEach(f=>{
    const card=document.createElement("div");card.className="sys-entry-card";
    const command=String(f.command||f.source||"").trim();

    const contentParts=[];
    ["content","notes","note","result","results","output","evidence"].forEach(k=>{
      const v=String(f[k]||"").trim();
      if(v && !contentParts.includes(v))contentParts.push(v);
    });
    const why=String(f.why||"").trim();
    const next=String(f.next||"").trim();
    if(why)contentParts.push("Why It Matters:\n"+why);
    if(next)contentParts.push("Next Action:\n"+next);

    const content=contentParts.join("\n\n").trim();
    const detailId=`sysFindingDetails_${escapeAttr(f.id)}`;
    card.innerHTML=`<div class="entry-head"><strong>${escapeHtml(f.title||"Important Finding")}</strong><span>${escapeHtml(f.updatedAt?new Date(f.updatedAt).toLocaleString():"")}</span></div>
      ${f.path?`<div class="host-meta"><strong>Path / Location:</strong> ${escapeHtml(f.path)}</div>`:""}
      <div id="${detailId}" class="hidden">
        ${command?`<div class="cred-expanded-section"><strong>Command / Source</strong><div class="sys-note-block">${renderBacktickGlow(command)}</div></div>`:""}
        <div class="cred-expanded-section"><strong>Content / Notes</strong><div class="sys-note-block">${content?renderBacktickGlow(content):'<span class="host-meta">No content / notes saved for this entry yet.</span>'}</div></div>
      </div>
      <div class="row-actions">
        <button class="secondary-btn small" data-toggle-sys-finding="${detailId}">Expand Full Notes</button>
        <button class="secondary-btn small" data-edit-sys-finding="${escapeAttr(f.id)}">Edit</button>
        <button class="danger-btn small" data-delete-sys-finding="${escapeAttr(f.id)}">Delete</button>
      </div>`;
    list.appendChild(card);
  });
  document.querySelectorAll("[data-toggle-sys-finding]").forEach(b=>b.onclick=()=>{
    const target=$(b.dataset.toggleSysFinding);
    if(!target)return;
    target.classList.toggle("hidden");
    b.textContent=target.classList.contains("hidden")?"Expand Full Notes":"Collapse Full Notes";
  });
  document.querySelectorAll("[data-edit-sys-finding]").forEach(b=>b.onclick=()=>editSysFinding(b.dataset.editSysFinding));
  document.querySelectorAll("[data-delete-sys-finding]").forEach(b=>b.onclick=()=>deleteSysFinding(b.dataset.deleteSysFinding));
}

function isLinuxSystemInfoHost(h){return String(h?.os||"").toLowerCase()==="linux";}
function isWindowsSystemInfoHost(h){return String(h?.os||"").toLowerCase()==="windows";}
function adSystemInfoVisible(h){return isWindowsSystemInfoHost(h)&&reportGroupValue(h)==="ad";}
const SYS_PANEL_SUFFIX={users:"Users",osnet:"Osnet",appsproc:"Appsproc",linuxUsers:"LinuxUsers",linuxOsnet:"LinuxOsnet",linuxAppsproc:"LinuxAppsproc",ad:"Ad",findings:"Findings"};
function setSystemTabHidden(name,hidden){
  const tab=document.querySelector(`.sys-tab[data-sys="${name}"]`);
  if(tab)tab.classList.toggle("hidden",!!hidden);
}
function preferredSystemInfoTab(h){return isLinuxSystemInfoHost(h)?"linuxUsers":"users";}
function currentSystemInfoTab(){const active=document.querySelector(".sys-tab.active");return active?active.dataset.sys:"users";}
function syncSystemInfoTabs(h,requested){
  const linux=isLinuxSystemInfoHost(h);
  const linuxTabs=["linuxUsers","linuxOsnet","linuxAppsproc"];
  ["users","osnet","appsproc"].forEach(name=>setSystemTabHidden(name,linux));
  linuxTabs.forEach(name=>setSystemTabHidden(name,!linux));
  setSystemTabHidden("ad",!adSystemInfoVisible(h));

  let target=requested||currentSystemInfoTab()||preferredSystemInfoTab(h);
  if(target==="linux")target="linuxUsers";
  const targetTab=document.querySelector(`.sys-tab[data-sys="${target}"]`);
  if(!targetTab||targetTab.classList.contains("hidden"))target=preferredSystemInfoTab(h);

  document.querySelectorAll(".sys-tab").forEach(t=>t.classList.toggle("active",!t.classList.contains("hidden")&&t.dataset.sys===target));
  Object.entries(SYS_PANEL_SUFFIX).forEach(([name,suffix])=>{
    const panel=$("sysPanel"+suffix);
    if(panel)panel.classList.toggle("hidden",name!==target);
  });
}
function renderSystemInfo(h){ensureHostIntel(h);syncLinuxSoftwareIntelligence(h);setSystemInfoInputs(h);renderSystemUsers(h);renderSysFindings(h);renderDynamicSystemBoxes(h);renderSystemBoxPreviews(h);renderLinuxSoftwareInsights(h);syncSystemInfoTabs(h);}
function setSysTab(name){flushPendingInteractiveEdits();syncSystemInfoTabs(activeHost(),name);}
function normalizeUserKey(type,name){
  return `${String(type||"user").trim().toLowerCase()}:${String(name||"").trim().toLowerCase()}`;
}
function entityTypeLabel(type){
  return ({user:"User",group:"Group",credential:"Credential",host:"Host/IP",path:"Path/File",port:"Port",app:"App/Process",other:"Other"})[type]||type;
}
function ensureUser(graph,type,name){
  const clean=String(name||"").trim();
  if(!clean||!graph?.map)return null;
  const normalizedType=String(type||"user").trim().toLowerCase()||"user";
  const key=normalizeUserKey(normalizedType,clean);
  if(!graph.map.has(key)){
    graph.map.set(key,{key,type:normalizedType,name:clean,mentions:[],credentials:[],groups:new Set(),privileges:new Set(),related:new Set(),hosts:new Set(),hostIds:new Set(),seedHostIds:new Set(),sources:new Set()});
  }
  return graph.map.get(key);
}
function entityContextForTerm(text,term){
  const raw=String(text||"");
  if(!raw.trim())return "";
  const target=String(term||"").trim().toLowerCase();
  if(!target)return raw.length>420?raw.slice(0,420)+"...":raw;
  const lines=raw.split(/\r?\n/);
  const hits=[];
  lines.forEach((line,index)=>{
    if(String(line).toLowerCase().includes(target)){
      const start=Math.max(0,index-1);
      const end=Math.min(lines.length,index+2);
      hits.push(lines.slice(start,end).join("\n"));
    }
  });
  if(hits.length)return hits.slice(0,3).join("\n---\n");
  return raw.length>420?raw.slice(0,420)+"...":raw;
}
function addUserMention(graph,type,name,host,source,content,field=""){
  const ent=ensureUser(graph,type,name);
  if(!ent)return null;
  const hostName=hostLabel(host);
  ent.hosts.add(hostName);
  if(host?.id)ent.hostIds.add(host.id);
  ent.sources.add(source);
  const ctx=entityContextForTerm(content,name);
  ent.mentions.push({host:hostName,source,field,context:ctx,fullText:String(content||"")});
  return ent;
}
function systemSourceLabel(store,key){
  const labels={
    raw:{users:"Local Users",groups:"Local Groups",groupMembers:"Group Members",privileges:"Privileges / Rights"},
    osnet:{routes:"Routes",arp:"ARP / Neighbors",listeningPorts:"Listening Ports",interestingConnections:"Interesting Connections",hotfixes:"Hotfixes / Patches",adapters:"Network Adapters"},
    appsproc:{installedApps:"Installed Applications",installedAppsX64:"Installed Applications x64",installedAppsX86:"Installed Applications x86 / 32-bit",interestingApps:"Interesting Applications",processes:"Running Processes",interestingProcesses:"Interesting / Privileged Processes"},
    boxes:{interestingUsers:"Interesting / Disabled Users",userGroups:"User Group Memberships",interestingAccess:"Interesting Access Summary",osVersionFull:"Operating System / Build / Architecture",networkConfig:"Network Configuration",privilegedProcesses:"Privileged / Interesting Processes",services:"Services / Security Tools",importantFindings:"Important Findings"},
    linux:{users:"Linux Local Users",groups:"Linux Local Groups",sudoers:"Linux Sudoers / Privilege Policy",osKernel:"Linux Distro / Kernel / Architecture",network:"Linux Network Configuration",routes:"Linux Routes",firewall:"Linux Firewall State / Rules",listeningPorts:"Linux Listening Ports",packages:"Linux Packages / Installed Software",processes:"Linux Processes",services:"Linux Services",cron:"Linux System Cron Jobs",timers:"Linux Systemd Timers",suid:"Linux SUID Binaries",sgid:"Linux SGID Binaries",suidSgid:"Linux SUID / SGID (Legacy)",capabilities:"Linux Capabilities",mounts:"Linux Mounted Filesystems",fstab:"Linux fstab",blockDevices:"Linux Block Devices / lsblk",kernelModules:"Linux Kernel Modules",interestingFiles:"Linux Interesting Files / Credentials",takeaways:"Linux Takeaways / Next Actions"},
    ad:{domainInfo:"AD Domain Information",users:"AD Domain Users",groups:"AD Domain Groups",computers:"AD Computers / DCs",accessMapping:"AD Group Membership / Access Mapping",sharesGpo:"AD Shares / GPO / SYSVOL Loot",kerberos:"AD Kerberos / SPNs / Roasting",bloodHound:"AD BloodHound / Attack Path Notes",takeaways:"AD Takeaways / Next Actions"}
  };
  return labels[store]?.[key]||key;
}
function dynamicBoxLabel(key){
  const parsedHomeLoot=parseLinuxHomeLootFileDynamicKey(key);
  if(parsedHomeLoot)return `Home Loot File - ${parsedHomeLoot.path}`;
  if(String(key||"").includes("::")){
    const parts=String(key).split("::");
    const kind=parts.shift();
    const entity=parts.join("::");
    return kind.replace(/-/g," ").replace(/\b\w/g,m=>m.toUpperCase())+" - "+entity;
  }
  return key;
}

function textMentionsUser(text,name){
  const raw=String(text||"");
  const n=String(name||"").trim();
  if(!raw||!n)return false;
  if(raw.includes("`"+n+"`"))return true;
  const escaped=n.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");
  const re=new RegExp("(^|[^A-Za-z0-9_.-])"+escaped+"([^A-Za-z0-9_.-]|$)","i");
  return re.test(raw);
}
function collectUserSeedUsers(hosts=null){
  const seeds=new Map();
  (hosts||Object.values(state.hosts||{})).forEach(host=>{
    ensureHostIntel(host);
    const rawUsers=host.systemInfo?.raw?.users||"";
    extractBacktickTerms(rawUsers).forEach(user=>{
      const clean=String(user||"").trim();
      if(!clean)return;
      const key=normalizeUserKey("user",clean);
      if(!seeds.has(key))seeds.set(key,{name:clean,hosts:[]});
      seeds.get(key).hosts.push({host,source:"Local Users",text:rawUsers});
    });

    const linuxUsers=host.systemInfo?.linux?.users||"";
    const parsedLinuxUsers=parseLinuxPasswdUsers(linuxUsers);
    parsedLinuxUsers.forEach(info=>{
      const clean=String(info.username||"").trim();
      if(!clean)return;
      const key=normalizeUserKey("user",clean);
      if(!seeds.has(key))seeds.set(key,{name:clean,hosts:[]});
      seeds.get(key).hosts.push({host,source:`Linux Local Users (${info.reason})`,text:linuxUsers});
    });
    extractBacktickTerms(linuxUsers).forEach(user=>{
      const clean=String(user||"").trim();
      if(!clean || isIgnoredLinuxUsername(clean))return;
      const key=normalizeUserKey("user",clean);
      if(!seeds.has(key))seeds.set(key,{name:clean,hosts:[]});
      seeds.get(key).hosts.push({host,source:"Linux Local Users (backticked)",text:linuxUsers});
    });
  });
  return seeds;
}
function collectKnownGroupsFromLocalGroups(hosts=null){
  const groups=new Set();
  (hosts||Object.values(state.hosts||{})).forEach(host=>{
    ensureHostIntel(host);
    extractBacktickTerms(host.systemInfo?.raw?.groups||"").forEach(g=>{
      if(String(g||"").trim())groups.add(String(g).trim().toLowerCase());
    });
    extractBacktickTerms(host.systemInfo?.linux?.groups||"").forEach(g=>{
      if(String(g||"").trim())groups.add(String(g).trim().toLowerCase());
    });
  });
  return groups;
}
function groupTermsFromText(text,knownGroups){
  return extractBacktickTerms(text).filter(t=>knownGroups.has(String(t||"").trim().toLowerCase()));
}

function privilegeTermsFromText(text){
  const out=[];
  const seen=new Set();

  String(text||"").split(/\r?\n/).forEach(line=>{
    const raw=String(line||"").trim();
    if(!raw || /^Privilege Name\s+Description\s+State/i.test(raw) || /^=+\s+=+\s+=+/.test(raw))return;

    // whoami /priv table format:
    // SeImpersonatePrivilege    Impersonate a client after authentication    Enabled
    // SeBackupPrivilege         Back up files and directories              Disabled
    //
    // Disabled still means the privilege is present in the current token.
    // It is just not currently enabled.
    const m=raw.match(/^(Se[A-Za-z0-9]+Privilege)\s+.*\b(Enabled|Disabled)\s*$/i);
    if(!m)return;

    const priv=m[1];
    const state=m[2].toLowerCase()==="enabled"?"Enabled":"Disabled";
    const label=`${priv} ${state}`;
    const key=label.toLowerCase();

    if(!seen.has(key)){
      seen.add(key);
      out.push(label);
    }
  });

  return out;
}

function privilegeDisplayParts(value){
  const raw=String(value||"").trim();
  const m=raw.match(/^(Se[A-Za-z0-9]+Privilege)(?:\s+(Enabled|Disabled))?$/i);
  if(!m)return {name:raw,state:"unknown",label:""};
  const name=m[1];
  const state=m[2]?m[2].toLowerCase():"unknown";
  const label=state==="enabled"?"Enabled":state==="disabled"?"Disabled":"Present";
  return {name,state,label};
}

function ensurePrivilegeChipStyles(){
  if($("privilegeChipStateStyles"))return;

  const s=document.createElement("style");
  s.id="privilegeChipStateStyles";
  s.textContent=`
    .entity-priv-chip.priv-state-enabled {
      color: var(--accent);
      border-color: rgba(0, 191, 255, .70);
      background: rgba(0, 191, 255, .12);
      box-shadow:
        0 0 10px rgba(0, 191, 255, .32),
        0 0 22px rgba(0, 119, 255, .16),
        inset 0 0 14px rgba(0, 191, 255, .045);
      text-shadow: 0 0 10px rgba(0, 191, 255, .36);
    }

    .entity-priv-chip.priv-state-disabled {
      box-shadow: none;
      text-shadow: none;
    }
  `;
  document.head.appendChild(s);
}


function privilegeChipHtml(value){
  const parts=privilegeDisplayParts(value);
  const cls=`entity-priv-chip priv-state-${parts.state}`;
  const term=parts.name || value;
  return `<span class="tag ${cls}" data-entity-note-kind="privilege" data-entity-note-term="${escapeAttr(term)}" role="button" tabindex="0" title="Open matching note in app">${escapeHtml(parts.name||value)}</span>`;
}


function buildUserGraph(){
  const current=activeHost();
  const visibleHosts=visibleReportGroupHosts(current);
  const visibleHostIds=new Set(visibleHosts.map(h=>h.id));
  const graph={map:new Map(),hosts:visibleHosts,currentHost:current};

  const seedUsers=collectUserSeedUsers(visibleHosts);
  const knownGroups=collectKnownGroupsFromLocalGroups(visibleHosts);

  // Seed list comes from Windows backticked Local Users plus Linux root/UID >= 1000 Local Users,
  // and only from hosts visible to the active host's Report Group.
  seedUsers.forEach(seed=>{
    const ent=ensureUser(graph,"user",seed.name);
    seed.hosts.forEach(row=>{
      if(row.host?.id)ent.seedHostIds.add(row.host.id);
      addUserMention(graph,"user",seed.name,row.host,row.source,row.text,"systemInfo.raw.users");
    });
  });

  function userEnt(name){return graph.map.get(normalizeUserKey("user",name));}
  function addUserContext(user,host,source,text,field=""){
    const ent=userEnt(user);
    if(!ent||!String(text||"").trim())return;
    ent.hosts.add(hostLabel(host));
    if(host?.id)ent.hostIds.add(host.id);
    ent.sources.add(source);
    ent.mentions.push({host:hostLabel(host),hostId:host?.id||"",source,field,context:entityContextForTerm(text,user),fullText:String(text||"")});
    const groupsFromText=groupTermsFromText(text,knownGroups);
    if(/User Group Memberships/i.test(source)){
      extractBacktickTerms(text).forEach(g=>{
        if(String(g||"").trim().toLowerCase()!==String(user||"").trim().toLowerCase())groupsFromText.push(g);
      });
    }
    Array.from(new Set(groupsFromText.map(g=>String(g).trim()).filter(Boolean))).forEach(g=>ent.groups.add(g));

    if(/whoami \/priv|user privileges|privileges/i.test(source)){
      privilegeTermsFromText(text).forEach(p=>ent.privileges.add(p));
    }
  }

  visibleHosts.forEach(host=>{
    ensureHostIntel(host);
    const sys=host.systemInfo||{};

    seedUsers.forEach(seed=>{
      const user=seed.name;

      // Raw/boxed System Info: only attach context when the actual username is present.
      ["raw","osnet","appsproc","boxes","linux","ad"].forEach(store=>{
        const section=sys[store]||{};
        Object.entries(section).forEach(([key,value])=>{
          const text=String(value||"");
          if(textMentionsUser(text,user)){
            addUserContext(user,host,systemSourceLabel(store,key),text,store+"."+key);
          }
        });
      });

      // Generated follow-up boxes: attach exact user-specific boxes even if the output does not repeat the username.
      Object.entries(sys.dynamicBoxes||{}).forEach(([key,value])=>{
        const label=dynamicBoxLabel(key);
        const text=String(value||"");
        const lowerKey=String(key||"").toLowerCase();
        const userLower=String(user).toLowerCase();
        const isUserBox =
          lowerKey === `user-groups::${userLower}` ||
          lowerKey === `user-privileges::${userLower}` ||
          lowerKey.endsWith(`::${userLower}`) ||
          lowerKey.startsWith(`${LINUX_HOME_LOOT_FILE_KIND}::${userLower}::`) ||
          new RegExp(" - "+user.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")+"$","i").test(label);
        if(isUserBox || textMentionsUser(text,user)){
          addUserContext(user,host,label,text,`dynamicBoxes.${key}`);
        }
      });

      // Important Findings: attach if username appears in path/command/content/notes.
      (sys.findings||[]).forEach(f=>{
        const source=`Important Finding - ${f.title||"Untitled"}`;
        const combined=[f.title,f.path,f.command,f.content,f.notes,f.note,f.result,f.results,f.output,f.evidence,f.why,f.next].filter(Boolean).join("\n\n");
        if(textMentionsUser(combined,user))addUserContext(user,host,source,combined,"systemInfo.findings");
      });

      // Evidence: attach if username appears anywhere in the evidence details.
      (host.evidence||[]).forEach(ev=>{
        const source=`Evidence - ${ev.title||ev.type||"Untitled"}`;
        const combined=[ev.title,ev.proofValue,ev.lootPath,ev.sourceHost,ev.targetHost,ev.method,ev.credentialUsed,ev.credentials,ev.credentialContext,ev.explanation,ev.fix,ev.notes].filter(Boolean).join("\n\n");
        if(textMentionsUser(combined,user))addUserContext(user,host,source,combined,"evidence");
      });
    });

    // Credentials: only attach to users seeded from visible Local Users.
    (host.credentials||[]).forEach(c=>{
      const username=String(c.username||"").trim();
      if(!username)return;
      const ent=userEnt(username);
      if(!ent)return;
      ent.credentials.push({...c,sourceHost:host});
      ent.hosts.add(hostLabel(host));
      ent.hostIds.add(host.id);
      ent.sources.add("Credentials");
      const combined=[c.domain,c.username,c.services,c.sourcePath,c.foundAs,c.notes,c.sourceType].filter(Boolean).join("\n\n");
      if(combined.trim())addUserContext(username,host,`Credential - ${username}`,combined,"credentials");
    });
  });

  // Credentials visible to the active host by Report Group: still only attach when username already exists from visible Local Users.
  allCredentialRecords()
    .filter(c=>visibleHostIds.has(c.sourceHostId)&&credentialVisibleToHost(c,current,state.hosts[c.sourceHostId]))
    .forEach(c=>{
      const username=String(c.username||"").trim();
      const ent=userEnt(username);
      if(ent&&!ent.credentials.some(x=>x.id===c.id)){
        ent.credentials.push(c);
        const h=c.sourceHost||state.hosts[c.sourceHostId];
        if(h){
          ent.hosts.add(hostLabel(h));
          ent.hostIds.add(h.id);
        }
        ent.sources.add("Credentials");
      }
    });

  graph.items=[...graph.map.values()].filter(e=>e.type==="user").sort((a,b)=>a.name.localeCompare(b.name));
  return graph;
}
function entityMatchesFilter(ent,filter){
  const f=String(filter||"").trim().toLowerCase();
  if(!f)return true;
  return [ent.name,[...ent.hosts].join(" "),[...ent.sources].join(" "),[...ent.groups].join(" "),ent.credentials.map(c=>credDisplayPair(c)).join(" ")].join(" ").toLowerCase().includes(f);
}
function renderUserSummary(graph,items){
  const box=$("entitySummaryGrid");if(!box)return;
  const users=graph.items.length;
  const creds=graph.items.reduce((n,e)=>n+(e.credentials||[]).length,0);
  const groups=new Set();
  const privileges=new Set();
  graph.items.forEach(e=>{
    [...e.groups].forEach(g=>groups.add(g.toLowerCase()));
    [...(e.privileges||[])].forEach(p=>privileges.add(p.toLowerCase()));
  });
  const mentions=graph.items.reduce((n,e)=>n+(e.mentions||[]).length,0);
  box.innerHTML=[
    ["Users",users],
    ["Matching Creds",creds],
    ["Groups Found",groups.size],
    ["Privileges",privileges.size],
    ["Source Boxes",mentions]
  ].map(([label,count])=>`<div class="entity-stat"><strong>${count||0}</strong><span>${label}</span></div>`).join("");
}

function userHostGroupsForList(graph,items){
  const groups=[];
  const byHost=new Map();

  (graph.hosts||visibleReportGroupHosts(activeHost())).forEach(host=>{
    byHost.set(host.id,{host,items:[]});
  });

  items.forEach(ent=>{
    const ids=[...(ent.seedHostIds&&ent.seedHostIds.size?ent.seedHostIds:ent.hostIds||[])].filter(id=>byHost.has(id));
    if(!ids.length){
      const h=graph.currentHost;
      if(h&&byHost.has(h.id))ids.push(h.id);
    }
    ids.forEach(id=>{
      const g=byHost.get(id);
      if(g&&!g.items.some(x=>x.key===ent.key))g.items.push(ent);
    });
  });

  byHost.forEach(g=>{
    g.items.sort((a,b)=>a.name.localeCompare(b.name));
    if(g.items.length)groups.push(g);
  });

  return groups;
}

function renderEntities(){
  const list=$("entityList"),detail=$("entityDetail");
  if(!list||!detail)return;
  const graph=buildUserGraph();
  const filter=formValue("entitySearch");
  const items=graph.items.filter(e=>entityMatchesFilter(e,filter));
  renderUserSummary(graph,items);
  const current=activeHost();
  const groupText=current?`${reportGroupLabel(reportGroupValue(current))} · ${hostNameIpLabel(current)}`:"No active host";
  if(!items.length){
    list.innerHTML=`<div class="host-meta">No users found for ${escapeHtml(groupText)}. For Windows, wrap user names in \`backticks\` inside System Info > Local Users. For Linux, root and UID >= 1000 users from Linux > Local Users are added automatically; backticks still work for extra users.</div>`;
    detail.innerHTML='<div class="host-meta">No user selected.</div>';
    return;
  }
  if(!selectedUserKey||!graph.map.has(selectedUserKey)||!items.some(e=>e.key===selectedUserKey))selectedUserKey=items[0].key;
  list.innerHTML="";
  const hostGroups=userHostGroupsForList(graph,items);
  hostGroups.forEach(group=>{
    const box=document.createElement("div");
    box.className="entity-host-box";
    box.innerHTML=`<div class="entity-host-title">${escapeHtml(hostNameIpLabel(group.host))}<span>${group.items.length} user${group.items.length===1?"":"s"}</span></div><div class="entity-host-users"></div>`;
    const body=box.querySelector(".entity-host-users");
    group.items.forEach(ent=>{
      const btn=document.createElement("button");
      btn.type="button";
      btn.className="entity-list-item"+(ent.key===selectedUserKey?" active":"");
      btn.dataset.entityKey=ent.key;
      btn.innerHTML=`<span><strong>${escapeHtml(ent.name)}</strong><em>${escapeHtml(entityTypeLabel(ent.type))}</em></span><small>${ent.groups.size} groups · ${(ent.privileges||new Set()).size} privs · ${ent.credentials.length} creds · ${ent.mentions.length} boxes</small>`;
      body.appendChild(btn);
    });
    list.appendChild(box);
  });
  list.querySelectorAll("[data-entity-key]").forEach(b=>b.onclick=()=>{selectedUserKey=b.dataset.entityKey;renderEntities();});
  renderUserDetail(graph,graph.map.get(selectedUserKey));
}

function noteCueClean(value){
  return String(value||"")
    .replace(/^builtin\\/i,"")
    .replace(/^nt authority\\/i,"")
    .replace(/^\.\\/,"")
    .replace(/\s+\b(?:enabled|disabled)\b$/i,"")
    .trim();
}

function noteCueProfile(kind,term){
  const clean=noteCueClean(term);
  const t=clean.toLowerCase();
  const prefer=[];
  const also=[];
  const add=(arr,...vals)=>vals.forEach(v=>{v=String(v||"").trim();if(v&&!arr.includes(v.toLowerCase()))arr.push(v.toLowerCase());});

  if(kind==="group"){
    if(/remote desktop users|rdp/.test(t))add(prefer,"xfreerdp","remote desktop users","remote desktop","rdp");
    if(/remote management users|winrm|psremote/.test(t))add(prefer,"evil-winrm","winrm","remote management users","remote management","psremote");
    if(/administrators|local admin|admin/.test(t))add(prefer,"runas","uac","psexec","windows priv esc","administrator");
    if(/backup operators|backup/.test(t))add(prefer,"sebackupprivilege","backup operators");
    if(/event log readers/.test(t))add(prefer,"event log readers","windows credential","event logs");
    if(/iis_iusrs|iis/.test(t))add(prefer,"iis","webshell","windows web");
    if(/remote/i.test(clean))add(also,"windows remote access","remote access");
  }

  if(kind==="privilege"){
    if(/seimpersonateprivilege/i.test(clean))add(prefer,"sigmapotato","godpotato","printspoofer","juicypotato","roguepotato","seimpersonateprivilege","token impersonation");
    if(/seassignprimarytokenprivilege/i.test(clean))add(prefer,"juicypotato","roguepotato","seassignprimarytokenprivilege","token impersonation");
    if(/sebackupprivilege/i.test(clean))add(prefer,"sebackupprivilege","backup operators");
    if(/serestoreprivilege/i.test(clean))add(prefer,"serestoreprivilege");
    if(/sedebugprivilege/i.test(clean))add(prefer,"sedebugprivilege","mimikatz","credential dumping");
    if(/setakeownershipprivilege/i.test(clean))add(prefer,"setakeownershipprivilege","take ownership");
    if(/semanagevolumeprivilege/i.test(clean))add(prefer,"semanagevolumeprivilege");
    if(/seloaddriverprivilege/i.test(clean))add(prefer,"seloaddriverprivilege","driver");
    if(/secreatetokenprivilege/i.test(clean))add(prefer,"secreatetokenprivilege");
    if(/setcbprivilege/i.test(clean))add(prefer,"setcbprivilege");
    if(/semachineaccountprivilege/i.test(clean))add(prefer,"machine account quota","semachineaccountprivilege","maq");
  }

  // Generic fallback for anything else that appears in the User Details window.
  add(also,clean,clean.replace(/privilege$/i,""),clean.replace(/\s+group$/i,""));
  return {kind,term:clean,prefer,also};
}

function noteCueText(note){
  return [
    note.title,
    note.notePath,
    note.description,
    note.section,
    note.sectionTitle,
    note.sectionKey,
    ...(note.subsections||[]),
    ...(note.tags||[])
  ].filter(Boolean).join(" ").toLowerCase();
}

function noteCueScore(note,profile){
  const text=noteCueText(note);
  const title=String(note.title||"").toLowerCase();
  const path=String(note.notePath||"").toLowerCase();
  let score=0;

  profile.prefer.forEach((q,i)=>{
    if(!q)return;
    const weight=1000-(i*35);
    if(title===q)score+=weight+300;
    if(path.endsWith("/"+q+".md")||path.endsWith("\\"+q+".md"))score+=weight+260;
    if(title.includes(q))score+=weight;
    if(path.includes(q))score+=weight-80;
    if(text.includes(q))score+=weight-180;
  });

  profile.also.forEach((q,i)=>{
    if(!q)return;
    const weight=230-(i*10);
    if(title.includes(q))score+=weight;
    if(path.includes(q))score+=weight-35;
    if(text.includes(q))score+=weight-70;
  });

  return score;
}

function findBestNoteForEntityCue(kind,term){
  const profile=noteCueProfile(kind,term);
  const notes=allPlaybooks().filter(n=>n&&n.notePath);
  let best=null;
  let bestScore=0;
  notes.forEach(note=>{
    const score=noteCueScore(note,profile);
    if(score>bestScore){
      best=note;
      bestScore=score;
    }
  });
  return bestScore>0?best:null;
}

async function openNoteFromEntityCue(kind,term){
  if(!state.serverAvailable)return alert("Run the app/server first, then try opening a linked note again.");

  if((!state.dynamicNotes||!state.dynamicNotes.length) && state.serverAvailable){
    await refreshDynamicNotes(true).catch(()=>{});
  }

  const note=findBestNoteForEntityCue(kind,term);
  if(note)return viewNote(note,activeHost());

  alert(`No matching internal note found for: ${term}.`);
}

function bindEntityNoteLinks(scope){
  (scope||document).querySelectorAll("[data-entity-note-term]").forEach(el=>{
    const run=()=>openNoteFromEntityCue(el.dataset.entityNoteKind||"term",el.dataset.entityNoteTerm||el.textContent||"");
    el.onclick=run;
    el.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();run();}};
  });
}

function renderUserDetail(graph,ent){
  ensurePrivilegeChipStyles();
  const detail=$("entityDetail");if(!detail)return;
  if(!ent){detail.innerHTML='<div class="host-meta">Select a user.</div>';return;}

  const groups=[...ent.groups].sort();
  const privileges=[...(ent.privileges||[])].sort();
  const creds=ent.credentials||[];
  const mentions=ent.mentions||[];
  const sourceGroups={};

  mentions.forEach(m=>{
    const key=`${m.host} · ${m.source}`;
    if(!sourceGroups[key])sourceGroups[key]=[];
    sourceGroups[key].push(m);
  });

  const sourceBlocks=Object.entries(sourceGroups).map(([source,rows])=>{
    const fullTexts=[];
    rows.forEach(m=>{
      const full=String(m.fullText||m.context||"").trim();
      if(full && !fullTexts.includes(full))fullTexts.push(full);
    });
    const body=fullTexts.join("\n\n---\n\n");
    return `<details class="entity-mention-card">
      <summary>${escapeHtml(source)} <span>${rows.length}</span></summary>
      <div class="sys-note-block entity-full-text">${body?renderMatchedEntityGlow(body,ent.name):'<span class="host-meta">No text saved for this source.</span>'}</div>
    </details>`;
  }).join("");

  detail.innerHTML=`<div class="entity-detail-head">
      <div>
        <h4>${escapeHtml(ent.name)}</h4>
        <div class="host-meta">User · ${groups.length} group clues · ${privileges.length} enabled/interesting privileges · ${creds.length} matching credentials · ${mentions.length} source matches</div>
      </div>
      <div class="entity-chip-row">${[...(ent.hostIds||[])].map(id=>state.hosts[id]?hostNameIpLabel(state.hosts[id]):id).map(h=>`<span class="tag">${escapeHtml(h)}</span>`).join("")}</div>
    </div>

    ${groups.length?`<div class="entity-section"><strong>Groups / Membership Clues</strong><div class="entity-chip-row">${groups.map(g=>`<span class="tag entity-group-chip" data-entity-note-kind="group" data-entity-note-term="${escapeAttr(g)}" role="button" tabindex="0" title="Open matching note in app">${escapeHtml(g)}</span>`).join("")}</div></div>`:""}

    ${privileges.length?`<div class="entity-section"><strong>Enabled / Interesting Privileges</strong><div class="entity-chip-row">${privileges.map(p=>privilegeChipHtml(p)).join("")}</div></div>`:""}

    ${creds.length?`<div class="entity-section"><strong>Matching Credentials</strong><div class="entity-mini-list">${creds.map(c=>`<div class="entity-mini-card"><b>${renderBacktickGlow(credDisplayPair(c))}</b><span>${escapeHtml(c.sourceHost?hostLabel(c.sourceHost):(state.hosts[c.sourceHostId]?hostLabel(state.hosts[c.sourceHostId]):""))}</span>${c.services?`<span>Services: ${renderBacktickGlow(c.services)}</span>`:""}${c.sourcePath?`<span>Source: ${escapeHtml(c.sourcePath)}</span>`:""}${c.notes?`<details class="entity-cred-notes"><summary>Credential Notes</summary><div class="sys-note-block">${renderBacktickGlow(c.notes)}</div></details>`:""}</div>`).join("")}</div></div>`:""}

    <div class="entity-section"><strong>Source Text / Matching Boxes</strong>
      <div class="entity-mention-list">${sourceBlocks||'<div class="host-meta">No source matches recorded for this user.</div>'}</div>
    </div>`;
  bindEntityNoteLinks(detail);
}


