function ensureEngagementConfig(){
  const d=defaultEngagementConfig(),c=state.engagementConfig&&typeof state.engagementConfig==="object"?state.engagementConfig:{};
  const hasStructuredTargetStore=Array.isArray(c.scope?.targets);
  const legacyAssessment=(!c.assessment||(!c.assessment.category&&!c.assessment.type))&&state.engagementType==="oscp"?{category:"certification-lab",type:"oscp"}:{};
  state.engagementConfig={...d,...c,identity:{...d.identity,...(c.identity||{})},assessment:{...d.assessment,...legacyAssessment,...(c.assessment||{})},objectives:{...d.objectives,...(c.objectives||{})},startingAccess:{...d.startingAccess,...(c.startingAccess||{})},scope:{...d.scope,...(c.scope||{})},reporting:{...d.reporting,...(c.reporting||{})},workflow:{...d.workflow,...(c.workflow||{})},documents:Array.isArray(c.documents)?c.documents:[],commandPaths:{...(d.commandPaths||{}),...(c.commandPaths||{})}};
  if(oscpWorkflow()?.normalizeEngagementConfig)state.engagementConfig=oscpWorkflow().normalizeEngagementConfig(state.engagementConfig,{legacyEngagementType:state.engagementType,profileName:activeUserName?.()||"",dataRootFingerprint:window.aerosServerInstance?.dataRootFingerprint||""});
  const config=state.engagementConfig,legacyPaths=config.workflow?.localPaths||{},overrides=config.commandPaths||{};
  if(!config.commandPathsProvenance&&(
    (overrides.kaliOutputRoot&&overrides.kaliOutputRoot===legacyPaths.outputRoot)||
    (overrides.importStagingRoot&&overrides.importStagingRoot===legacyPaths.importStagingRoot)
  )){
    if(overrides.kaliOutputRoot===legacyPaths.outputRoot)delete overrides.kaliOutputRoot;
    if(overrides.importStagingRoot===legacyPaths.importStagingRoot)delete overrides.importStagingRoot;
    config.commandPathsProvenance={schemaVersion:1,migratedLegacyGlobalSnapshot:true};
  }
  if(!Array.isArray(state.engagementConfig.startingAccess.types))state.engagementConfig.startingAccess.types=[];
  if(!Array.isArray(state.engagementConfig.startingAccess.entries))state.engagementConfig.startingAccess.entries=[];
  ["inScope","outOfScope","restrictions","rules","targets"].forEach(k=>{if(!Array.isArray(state.engagementConfig.scope[k]))state.engagementConfig.scope[k]=[];});
  migrateLegacyScopeTargets(state.engagementConfig.scope,c.scope||{});
  if(hasStructuredTargetStore){
    if(state.engagementConfig.scope.targets.length&&!state.engagementConfig.scope.rules.length)syncScopeCompatibility(state.engagementConfig.scope);
  }else migrateLegacyScopeRules(state.engagementConfig.scope);
  if(!Array.isArray(state.engagementConfig.documents))state.engagementConfig.documents=[];
  if(window.AEROSExamControls?.ensureWorkflowState)window.AEROSExamControls.ensureWorkflowState(state,typeof activeProfile==="function"?activeProfile():{});
  return state.engagementConfig;
}
