function matchesReferenceNoteSearch(note,query){
  const renderer=referenceNoteRenderer();
  if(typeof renderer.matchesReferenceNoteSearch==="function")return renderer.matchesReferenceNoteSearch(note,query);
  const row=note&&typeof note==="object"?note:{},terms=String(query||"").trim().toLowerCase().split(/\s+/).filter(Boolean);
  if(!terms.length)return true;
  const haystack=[row.title,row.description,row.notePath,row.path,row.category,row.module,row.stage,row.executionContext,row.taskId,...(Array.isArray(row.tags)?row.tags:[]),...(Array.isArray(row.keywords)?row.keywords:[]),...(Array.isArray(row.serviceHints)?row.serviceHints:[])].filter(value=>value!==undefined&&value!==null).join(" ").toLowerCase();
  return terms.every(term=>haystack.includes(term));
}
