  state.assetGroups=state.assetGroups.filter(group=>group.id!==id);
  if(state.assetGroups.length===before)return false;
  syncLegacyHostReportGroups();ensureMethodologyContextState({ensureGroups:false});persist();render();
  if(state.serverAvailable&&activeLabName())await saveLabState(true).catch(error=>showToast(`Asset group removed locally, but file storage save failed: ${error.message}`,"error"));
