function isImportedReferenceNote(note){
  const source=String(note?.source||"").toLowerCase();
  return source==="aeros-reference-pack"||source==="aeros-library";
}

function renderNoteScanStatus(h=null, displayedNotes=null){
  const el=$("noteScanStatus");
  if(!el)return;
  const total=state.dynamicNoteCount||((state.dynamicNotes||[]).length);
  const root=state.dynamicNoteRoot||"Optional reference packs";
  const libraryMode=formValue("notesLibraryFilter")||"relevant";
  const shown=Array.isArray(displayedNotes)?displayedNotes.filter(isImportedReferenceNote).length:null;
  const relevant=h?recommendedNotes(h).filter(isImportedReferenceNote).length:0;
  if(state.dynamicNoteError){
    el.innerHTML=`<span class="bad-text">Reference pack error:</span> ${escapeHtml(state.dynamicNoteError)}<br><span>Source: ${escapeHtml(root)}</span>`;
    return;
  }
  if(total){
    const detail=shown!==null
      ?` · Shown after filters: ${shown} · Matching current host before filters: ${relevant}`
      :` · Matching current host: ${relevant}`;
    el.innerHTML=`<span class="ok-text">Reference notes loaded:</span> ${total}${detail}<br><span>Source: ${escapeHtml(root)}</span>`;
  }else{
    el.innerHTML=`<span class="muted-text">Reference notes loaded:</span> 0<br><span>Source: ${escapeHtml(root)}</span>`;
  }
}

function referencePackServerError(detail=""){
  const extra=detail?` ${detail}`:"";
  return new Error(`The running AEROS server does not support Optional Reference Packs.${extra} Close every AEROS window, run "Stop AEROS V1 Server.cmd", then reopen this build.`);
}
async function readReferencePackApiJson(response, action){
  const text=await response.text();
  let data;
  try{data=JSON.parse(text);}
  catch(parseError){
    const contentType=String(response.headers.get("Content-Type")||"").toLowerCase();
    const looksHtml=contentType.includes("text/html")||/^\s*<!doctype html/i.test(text)||/^\s*<html/i.test(text);
    if(looksHtml||response.status===404||response.status===501){
      throw referencePackServerError(`${action} reached an older or different server on port 8765 (HTTP ${response.status}).`);
    }
    throw new Error(`${action} returned an invalid server response (HTTP ${response.status}).`);
  }
  if(response.status===404||response.status===501){
    throw referencePackServerError(`${action} is unavailable on the running server.`);
  }
  return data;
}
let referenceNotesPayloadPromise=null,referenceNotesPayloadSnapshot=null;
async function loadReferenceNotesPayload({force=false}={}){
  if(force)referenceNotesPayloadSnapshot=null;
  if(referenceNotesPayloadSnapshot)return referenceNotesPayloadSnapshot;
  if(referenceNotesPayloadPromise)return referenceNotesPayloadPromise;
  referenceNotesPayloadPromise=(async()=>{
    const response=await fetch(`/api/reference-notes?_=${Date.now()}`,{cache:"no-store"});
    const data=await readReferencePackApiJson(response,"Loading reference notes");
    if(!response.ok||!data.ok)throw new Error(data.error||"Could not load reference notes");
    referenceNotesPayloadSnapshot=data;
    return data;
  })();
  try{return await referenceNotesPayloadPromise;}
  finally{referenceNotesPayloadPromise=null;}
}
async function refreshDynamicNotes(silent=true,{force=false}={}){
  if(!state.serverAvailable){
    renderNoteScanStatus(activeHost(),[]);
    return;
  }
  try{
    const d=await loadReferenceNotesPayload({force:force||silent===false});
    const raw=d.notes||{};
    state.dynamicNotes=Array.isArray(raw)?raw:Object.values(raw);
    state.dynamicNotes=state.dynamicNotes.map(note=>({...note,notePath:note.notePath||note.path||"",source:note.source||"aeros-reference-pack"}));
    state.dynamicNoteRoot=d.library||"No optional reference pack installed";
    state.dynamicNoteCount=Number(d.count||state.dynamicNotes.length||0);
    state.dynamicNoteError="";
    persist();
    if(activeWorkspacePanelName()==="notes")renderRecommended(activeHost());
    if(!silent)showToast(`Reloaded ${state.dynamicNoteCount} reference notes.`,"success");
  }catch(e){
    state.dynamicNotes=state.dynamicNotes||[];
    state.dynamicNoteError=e.message||String(e);
    persist();
    if(activeWorkspacePanelName()==="notes")renderNoteScanStatus(activeHost(),recommendedNotes(activeHost()));
    if(!silent)showToast(`Could not reload reference notes: ${e.message}`,"error");
  }
}
function renderReferencePackList(packs=[],invalidPacks=[]){
  const list=$("referencePackList");
  if(!list)return;
  const rows=[];
  (packs||[]).forEach(pack=>{
    const revision=String(pack.contentRevision||"").trim();
    const metadata=[escapeHtml(pack.version||"V1"),...(revision?[`revision ${escapeHtml(revision)}`]:[]),`${Number(pack.count||0)} notes`].join(" · ");
    rows.push(`<article class="reference-pack-row"><div><strong>${escapeHtml(pack.displayName||pack.packId||"Reference Pack")}</strong><div class="host-meta">${metadata}</div></div><button class="danger-btn small" type="button" data-delete-reference-pack="${escapeAttr(pack.packId||"")}">Remove</button></article>`);
  });
  (invalidPacks||[]).forEach(pack=>{
    rows.push(`<article class="reference-pack-row reference-pack-invalid"><div><strong>${escapeHtml(pack.displayName||pack.packId||"Invalid Pack")}</strong><div class="host-meta bad-text">${escapeHtml(pack.error||"Pack could not be loaded")}</div></div>${pack.packId?`<button class="danger-btn small" type="button" data-delete-reference-pack="${escapeAttr(pack.packId)}">Remove</button>`:""}</article>`);
  });
  list.innerHTML=rows.join("")||'<div class="host-meta">No optional reference packs installed.</div>';
}

async function refreshReferencePacks(silent=true,{force=false}={}){
  if(!state.serverAvailable){renderReferencePackList([],[]);return;}
  try{
    const d=await loadReferenceNotesPayload({force});
    renderReferencePackList(d.packs||[],d.invalidPacks||[]);
    if(!silent)showToast(`Found ${(d.packs||[]).length} installed reference pack(s).`,"success");
  }catch(error){
    renderReferencePackList([],[]);
    if(!silent)showToast(`Could not load reference packs: ${error.message}`,"error");
  }
}

async function importReferencePack(){
  const input=$("referencePackFile");
  const file=input?.files?.[0];
  if(!file)return showToast("Choose an AEROS reference pack first.","error");
  if(!state.serverAvailable)return showToast("Start the AEROS server before importing a reference pack.","error");
  if(window.aerosServerCapabilities?.referencePackImport!==true){
    return showToast(referencePackServerError().message,"error");
  }
  const form=new FormData();
  form.append("referencePack",file,file.name);
  const button=$("importReferencePackBtn");
  if(button){button.disabled=true;button.textContent="Importing...";}
  try{
    const r=await fetch("/api/import-reference-pack",{method:"POST",body:form});
    const d=await readReferencePackApiJson(r,"Importing the reference pack");
    if(!r.ok||!d.ok)throw new Error(d.error||"Could not import reference pack");
    if(input)input.value="";
    if($("referencePackFileName"))$("referencePackFileName").textContent="No pack selected.";
    await refreshDynamicNotes(true,{force:true});
    await refreshReferencePacks(true);
    showToast(`${d.displayName||"Reference pack"} imported (${Number(d.count||0)} notes).`,"success");
  }catch(error){
    showToast(`Could not import reference pack: ${error.message}`,"error");
  }finally{
    if(button){button.disabled=false;button.textContent="Import Notes Pack";}
  }
}

async function deleteReferencePack(packId){
  if(!packId)return;
  const accepted=await themedConfirm("Remove this installed reference pack from AEROS? The original pack file is not deleted.",{title:"Remove Reference Pack",confirmText:"Remove",danger:true});
  if(!accepted)return;
  try{
    const r=await fetch("/api/delete-reference-pack",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({packId})});
    const d=await readReferencePackApiJson(r,"Removing the reference pack");
    if(!r.ok||!d.ok)throw new Error(d.error||"Could not remove reference pack");
    await refreshDynamicNotes(true,{force:true});
    await refreshReferencePacks(true);
    showToast("Reference pack removed.","success");
  }catch(error){
    showToast(`Could not remove reference pack: ${error.message}`,"error");
  }
}

async function saveGlobalProfiles(){
  const profiles=state.profiles;
  if(!profiles||typeof profiles!=="object"||Array.isArray(profiles)||!Object.keys(profiles).length)throw new Error("Refusing to save an empty profile store");
  const r=await fetch("/api/save-profiles",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({profiles})});
  const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||"Could not save profiles");return d;
}
function activeUserName(){try{return localStorage.getItem("activeUserProfile")||"";}catch(e){return "";}}
function exactUserProfile(name,profiles=state.profiles){
  if(!name||!profiles||typeof profiles!=="object"||Array.isArray(profiles))return null;
  if(!Object.prototype.hasOwnProperty.call(profiles,name))return null;
  const profile=profiles[name];
  return profile&&typeof profile==="object"&&!Array.isArray(profile)?profile:null;
}
async function loadGlobalProfiles(){
  const r=await fetch("/api/profiles");const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||"Could not load profiles");
  if(!d.profiles||typeof d.profiles!=="object"||Array.isArray(d.profiles))throw new Error("Invalid profiles response");
  const serverProfiles=d.profiles,localProfiles=state.profiles||{};
  if(Object.keys(serverProfiles).length){state.profiles=serverProfiles;persist();}
  else if(Object.keys(localProfiles).length){await saveGlobalProfiles();}
  renderProfileSelect();
  const remembered=activeUserName();
  if(remembered){
    if(exactUserProfile(remembered)&&applyUserProfile(remembered)){
      await showEngagementStartupChooser();
      return;
    }
    showStartupProfileChooser(remembered);
    return;
  }
  showStartupProfileChooser();
}
