  state.testerName=p.testerName||name;state.studentEmail=p.studentEmail||"";state.osid=p.osid||"";state.reportTemplatePath=p.reportTemplatePath||state.reportTemplatePath;
  state.callbackHost=p.callbackHost||state.callbackHost||"";state.callbackPort=p.callbackPort||state.callbackPort||"4444";
