async function checkServer(){
  try{
    const res=await fetch("/api/health",{cache:"no-store"});
    const data=await res.json();
    if(!res.ok||!data.ok)throw new Error("Health check failed");
    state.serverAvailable=true;
    window.aerosServerCapabilities=data.capabilities||{};
    window.aerosServerInstance=data.instance||{};
    const reconReady=window.aerosServerCapabilities[RECON_IMPORT_API_CAPABILITY]===true;
    const commandNotesReady=window.aerosServerCapabilities.commandNotes===true;
    const referenceNotesReady=window.aerosServerCapabilities.referenceNotes===true;
    const referencePackImportReady=window.aerosServerCapabilities.referencePackImport===true;
    const referenceNoteEditingReady=window.aerosServerCapabilities.referenceNoteEditing===true;
    const currentServerReady=reconReady&&commandNotesReady&&referenceNotesReady&&referencePackImportReady&&referenceNoteEditingReady&&window.aerosServerCapabilities.oscpPreflight===true;
    $("serverStatus").textContent=currentServerReady
      ?"AEROS V1 connected. file storage saving, command notes, optional reference-pack import, report export, and recon ZIP import enabled."
      :"AEROS server connected, but it is an older build. Stop the old server and reopen this build.";
    $("serverStatus").className=currentServerReady?"server-status ok":"server-status bad";
    try{const dbRes=await fetch("/api/storage-status",{cache:"no-store"});const db=await dbRes.json();if(dbRes.ok&&db.ok)window.aerosStorageStatus=db;}catch(e){}
    await loadGlobalProfiles();syncCommandNoteSourceControl();await loadCommandNoteManifest(true).catch(e=>showToast(`Command notes unavailable: ${e.message}`,"error"));await refreshLabs();refreshDynamicNotes(true).catch(()=>{});refreshReferencePacks(true).catch(()=>{});loadBinaryContexts(true).catch(()=>{});
  }catch{
    state.serverAvailable=false;
    window.aerosServerCapabilities={};
    $("serverStatus").textContent="Server not connected. Run: python server.py";
    $("serverStatus").className="server-status bad";
    loadBinaryContexts(true).catch(()=>{});
  }
}
function activeHost(){return state.activeHost?state.hosts[state.activeHost]:null;}
function exactHostOwner(hostId,{allowInactive=false}={}){
  const value=String(hostId||"").trim();if(!value)return {ok:false,reason:"An exact host ID is required."};
  const matches=Object.entries(state.hosts||{}).filter(([key,host])=>
    host&&String(key)===value||host&&String(host.id||key)===value
  );
  const unique=[];
  matches.forEach(([key,host])=>{if(!unique.some(row=>row.host===host))unique.push({key,host,id:String(host.id||key)});});
  if(unique.length!==1)return {ok:false,reason:unique.length?"The exact host owner is ambiguous.":"The exact host owner is missing or stale."};
  if(!allowInactive&&unique[0].host.active===false)return {ok:false,reason:"The exact host owner is inactive."};
  return {ok:true,...unique[0]};
}
function syncCanonicalHostSelector(owner){
  const selector=$("hostSelect"),value=String(owner?.host?.id||owner?.id||"");
  if(!selector||!value)return;
  if([...selector.options].some(option=>option.value===value))selector.value=value;
}
function selectCanonicalHost(hostId,options={}){
  const owner=exactHostOwner(hostId);
  if(!owner.ok){
    if(options.visibleFailure!==false)showToast(`${owner.reason} No neighboring host was selected.`,"warning");
    return null;
  }
  state.activeHost=owner.key;
  syncCanonicalHostSelector(owner);
  if(isOscpEngagement()){
    const core=navigatorCore();
    state.navigation=state.navigation&&typeof state.navigation==="object"&&!Array.isArray(state.navigation)?state.navigation:{};
    if(core){
      const normalized=core.normalizeNavigationState(state.navigation.navigator||state.oscpNavigatorState||{},{
        validHostIds:navigatorHostIds()
      });
      const preserveContext=options.preserveContext===true;
      const navigatorRoute=core.normalizeRoute({destination:"navigator"}).route;
      const requestedRoute=options.route&&core.normalizeRoute(options.route).valid?core.normalizeRoute(options.route).route:null;
      const activeRoute=requestedRoute||(options.preserveRoute===true&&normalized.activeRoute?.hostId===owner.id?normalized.activeRoute:navigatorRoute);
      state.navigation.navigator={
        ...normalized,
        selectedHostId:owner.id,
        selectedEndpointId:preserveContext?normalized.selectedEndpointId:"",
        selectedOriginId:preserveContext?normalized.selectedOriginId:"",
        selectedAccessContextId:preserveContext?normalized.selectedAccessContextId:"",
        activeRoute,
        routeError:"",
        focusKey:options.focusKey||normalized.focusKey||""
      };
    }
    if(state.navigation.workbench){
      state.navigation.workbench={
        ...state.navigation.workbench,
        selectedHostId:owner.id,
        routeError:""
      };
    }
  }
  if(options.persistNow!==false)persist();
  if(options.renderNow===true)render();
  return owner.host;
}
function synchronizeCanonicalHostSelection({allowInitialFallback=false}={}){
  let owner=state.activeHost?exactHostOwner(state.activeHost):{ok:false};
  const selectedId=String(state.navigation?.navigator?.selectedHostId||state.oscpNavigatorState?.selectedHostId||"");
  if(!owner.ok&&selectedId)owner=exactHostOwner(selectedId);
  if(!owner.ok&&allowInitialFallback){
    const first=Object.entries(state.hosts||{}).find(([,host])=>host&&host.active!==false);
    if(first)owner={ok:true,key:first[0],host:first[1],id:String(first[1].id||first[0])};
  }
  if(!owner.ok){state.activeHost=null;return null;}
  state.activeHost=owner.key;
  if(isOscpEngagement()&&navigatorCore()){
    state.navigation=state.navigation&&typeof state.navigation==="object"&&!Array.isArray(state.navigation)?state.navigation:{};
    const normalized=navigatorCore().normalizeNavigationState(state.navigation.navigator||state.oscpNavigatorState||{},{
      validHostIds:navigatorHostIds()
    });
    const routeHostId=normalized.activeRoute?.hostId||"";
    const routeMismatch=normalized.activeRoute?.destination!=="navigator"&&routeHostId&&routeHostId!==owner.id;
    state.navigation.navigator={
      ...normalized,
      selectedHostId:owner.id,
      activeRoute:routeMismatch?navigatorCore().normalizeRoute({destination:"navigator"}).route:normalized.activeRoute,
      routeError:routeMismatch?"The saved workspace route named a different host than the canonical active host. The route was not opened.":normalized.routeError
    };
  }
  return owner.host;
}
