    const sd=evaluateScopeTarget({ip:h.ip,hostname:h.hostname});
    const scopePrefix=sd.status==="out-of-scope"?"[OUT] ":sd.status==="restricted"?"[RESTRICTED] ":sd.status==="needs-review"?"[REVIEW] ":"";
