  if(!Array.isArray(h.recon.autoReconArtifacts))h.recon.autoReconArtifacts=[];
  if(!h.recon.endpointReviews||typeof h.recon.endpointReviews!=="object"||Array.isArray(h.recon.endpointReviews))h.recon.endpointReviews={};
  if(!h.recon.lastWebImportSummary||typeof h.recon.lastWebImportSummary!=="object"||Array.isArray(h.recon.lastWebImportSummary))h.recon.lastWebImportSummary={};
  if(!h.recon.initialRecon||typeof h.recon.initialRecon!=="object"||Array.isArray(h.recon.initialRecon))h.recon.initialRecon={};
