  const byId=new Map((dimensions||[]).map(row=>[row.id,row]));
  root.querySelectorAll("[data-recon-meter-id]").forEach(meter=>{
    const row=byId.get(meter.dataset.reconMeterId),value=Math.max(0,Math.min(100,Math.round(Number(row?.value)||0)));
    meter.dataset.reconMeterState=row?.state||"not-run";
    const label=meter.querySelector("[data-recon-meter-label]"),numberNode=meter.querySelector("[data-recon-meter-value]"),summary=meter.querySelector("[data-recon-meter-summary]"),bar=meter.querySelector("[data-recon-meter-bar]"),track=meter.querySelector(".feature-meter-track");
    if(label&&row?.label)label.textContent=row.label;
    if(numberNode)numberNode.textContent=`${value}%`;
    if(summary)summary.textContent=row?.summary||"Awaiting host evidence";
    if(bar)bar.style.width=`${value}%`;
    if(track){track.setAttribute("role","progressbar");track.setAttribute("aria-label",row?.label||meter.dataset.reconMeterId);track.setAttribute("aria-valuemin","0");track.setAttribute("aria-valuemax","100");track.setAttribute("aria-valuenow",String(value));}
  });
