    if(endpoint)target=document.querySelector(`[data-endpoint-id="${CSS.escape(endpoint)}"]`);
    if(!target&&origin)target=document.querySelector(`[data-origin-id="${CSS.escape(origin)}"],[data-web-target-id="${CSS.escape(origin)}"]`);
    if(!target&&artifact)target=document.querySelector(`[data-review-scan-artifact="${CSS.escape(artifact)}"],[data-import-id="${CSS.escape(artifact)}"]`);
    if(!target&&record)target=document.querySelector(`[data-web-target-id="${CSS.escape(record)}"]`);
    if(!target&&selector){try{target=document.querySelector(selector);}catch(error){}}
