function renderHostOsResolution(h){
  const root=$("hostOsResolution"),model=hostProfileModel();if(!root||!h||!model)return;
  const resolution=osResolutionForHost(h),observations=(h.osObservations||[]).filter(row=>row?.active!==false&&model.osFamily?.(row.family)!=="unknown").sort((a,b)=>(Number(b.rank)||0)-(Number(a.rank)||0)||String(b.observedAt||"").localeCompare(String(a.observedAt||"")));
  const familyLabel=resolution.status==="conflict"?"OS conflict":resolution.family==="unknown"?"OS unknown":prettyChoice(resolution.family);
  const conflictIds=new Set(resolution.conflictObservationIds||[]),primaryIds=new Set(resolution.primaryObservationIds||[]);
  const sourceRows=observations.slice(0,12).map(row=>{
    const role=primaryIds.has(row.id)?"supporting":conflictIds.has(row.id)?"conflicting":row.family===resolution.family?"supporting":"superseded";
    return `<article class="host-os-observation ${escapeAttr(role)}">
      <div><span class="host-os-family">${escapeHtml(prettyChoice(row.family))}</span><span class="host-os-authority">${escapeHtml(model.OS_AUTHORITY?.[row.authority]?.label||prettyChoice(row.authority))}</span><span class="host-os-role">${escapeHtml(prettyChoice(role))}</span></div>
      <strong>${escapeHtml(row.sourceLabel||"OS evidence")}</strong>
      <p>${escapeHtml(row.evidence||"No evidence excerpt retained.")}</p>
      <small>${escapeHtml(row.observedAt||"Timestamp unavailable")}</small>
      <button class="host-profile-card-action" data-os-source="${escapeAttr(row.id)}" type="button">Open source</button>
    </article>`;
  }).join("");
  const manual=resolution.manualLock||{},review=model.osReviewDisposition?.(h)||{deferred:false},statusText=manual.active?`Locked ${prettyChoice(manual.family)}`:resolution.status==="conflict"?"Resolve the conflict or inspect its sources":review.deferred?"Automatic / unlocked · Unknown deferred until new evidence":resolution.family==="unknown"?"Automatic / unlocked · review open":"Automatic resolution active";
  root.className=`host-os-resolution status-${escapeAttr(resolution.status||"unknown")}`;
  root.innerHTML=`<div class="host-os-resolution-head"><div><span class="host-profile-card-kicker">Target operating system</span><h4>${escapeHtml(familyLabel)}</h4><p>${escapeHtml(resolution.confidence||"Unknown")} confidence · ${escapeHtml(statusText)}</p></div><div class="host-os-resolution-actions">${manual.active?'<button class="secondary-btn small" data-os-unlock type="button">Unlock manual OS</button>':""}${resolution.status==="conflict"?'<button class="secondary-btn small" data-os-lock="linux" type="button">Lock Linux</button><button class="secondary-btn small" data-os-lock="windows" type="button">Lock Windows</button>':""}${resolution.status==="unknown"&&!manual.active?(review.deferred?'<button class="secondary-btn small" data-os-resume-review type="button">Resume OS review</button>':'<button class="secondary-btn small" data-os-defer type="button">Keep Unknown for now</button>'):""}</div></div>
    ${resolution.status==="conflict"?'<div class="host-os-conflict-guidance"><strong>Conflicting strong OS evidence</strong><span>OS-specific routing is paused. Cross-platform identification work remains available until an operator lock or stronger verified evidence resolves the conflict.</span></div>':resolution.family==="unknown"?'<div class="host-os-conflict-guidance"><strong>OS identification required</strong><span>Weak or absent evidence cannot route this host permanently. Continue safe cross-platform identification.</span></div>':""}
    <div class="host-os-observation-list">${sourceRows||'<div class="host-meta">No OS observations recorded yet.</div>'}${observations.length>12?`<div class="host-meta">${observations.length-12} additional retained observation${observations.length-12===1?"":"s"}.</div>`:""}</div>`;
}
async function handleHostOsResolutionAction(event){
  const h=activeHost(),model=hostProfileModel();if(!h||!model)return;
  const lock=event.target.closest?.("[data-os-lock]");
  if(lock){model.setManualOsLock?.(h,lock.dataset.osLock);save();renderWorkspace();showToast(`Target OS locked to ${prettyChoice(lock.dataset.osLock)}.`,"success");return;}
  if(event.target.closest?.("[data-os-unlock]")){model.setManualOsLock?.(h,"unknown");save();renderWorkspace();showToast("Manual OS lock removed; sourced resolution is active.","success");return;}
  if(event.target.closest?.("[data-os-defer]")){
    model.deferUnknownOperatingSystem?.(h);save();
    try{if(activeLabName())await saveLabState(true);render();showToast("OS remains Automatic / Unlocked and Unknown. Navigator will revisit it when evidence changes.","success");}
    catch(error){render();showToast(`Unknown OS was deferred locally, but the engagement save failed: ${error.message}`,"error");}
    return;
  }
  if(event.target.closest?.("[data-os-resume-review]")){
    model.resumeOperatingSystemReview?.(h);save();
    try{if(activeLabName())await saveLabState(true);render();showToast("Unknown OS review returned to the active queue.","success");}
    catch(error){render();showToast(`OS review resumed locally, but the engagement save failed: ${error.message}`,"error");}
    return;
  }
  const sourceButton=event.target.closest?.("[data-os-source]");if(!sourceButton)return;
  const row=(h.osObservations||[]).find(item=>item.id===sourceButton.dataset.osSource);if(!row)return;
  const ref=row.ownerRef||{},tab=(ref.peasImportId||ref.importId)?"postexp-imports":ref.tab||((row.sourceType||"").includes("scan")?"recon":"profile");
  setWorkspaceTab(tab);
  const scanTarget={port:"scanPanelPort",tcp:"scanPanelTcp",udp:"scanPanelUdp"}[ref.scanSlot];
  const target=$(ref.fieldId||scanTarget||(ref.peasImportId?"peasImportList":"hostProfileEditor"));
  setTimeout(()=>target?.scrollIntoView({behavior:"smooth",block:"center"}),80);
}
function hostAddressReachabilityLabel(value){
  return ({
    direct:"Directly reachable from operator",
    "via-path":"Reachable through recorded path",
    unreachable:"Not currently reachable",
    unknown:"Reachability unknown"
  })[value]||"Reachability unknown";
}
function hostAddressTunnelLabel(tunnel){
  const pivot=Object.values(state.hosts||{}).find(host=>host?.id===tunnel?.pivotHostId);
  const context=(pivot?.accessContexts||[]).find(row=>row?.id===tunnel?.accessContextId);
  return [
    tunnel?.name||"Recorded path",
    pivot?hostLabel(pivot):tunnel?.pivotHostLabel||"Missing pivot",
    context?.principal||context?.label||"Missing access context",
    tunnel?.status||"unknown"
  ].join(" · ");
}
function populateHostAddressTunnelOptions(selectedId=""){
  const select=$("hostAddressTunnel");if(!select)return;
  const rows=(state.tunnels||[]).filter(row=>row?.id);
  select.innerHTML='<option value="">No exact path selected</option>'+rows.map(row=>`<option value="${escapeAttr(row.id)}">${escapeHtml(hostAddressTunnelLabel(row))}</option>`).join("");
  select.value=rows.some(row=>row.id===selectedId)?selectedId:"";
}
function clearHostAddressForm(){
  editingHostAddressId=null;
  ["hostAddressValue","hostAddressInterface","hostAddressNote"].forEach(id=>setFormValue(id,""));
  setFormValue("hostAddressZone","unknown");setFormValue("hostAddressReachability","unknown");
  populateHostAddressTunnelOptions("");
  if($("hostAddressValue"))$("hostAddressValue").readOnly=false;
  if($("saveHostAddressBtn"))$("saveHostAddressBtn").textContent="Add address";
  $("cancelHostAddressBtn")?.classList.add("hidden");
}
function renderHostNetworkAddresses(h){
  const root=$("hostNetworkAddressList"),count=$("hostNetworkAddressCount"),model=hostProfileModel();if(!root||!h||!model?.ensureNetworkAddressState)return;
  const rows=model.ensureNetworkAddressState(h),reachability=model.addressReachability?.(h,state),details=new Map((reachability?.addresses||[]).map(row=>[row.id,row]));
  if(count)count.textContent=`${rows.length} address${rows.length===1?"":"es"}`;
  root.innerHTML=rows.map(row=>{
    const detail=details.get(row.id)||row,tunnel=(state.tunnels||[]).find(item=>item?.id===row.tunnelId);
    const path=row.reachability==="via-path"?(tunnel?hostAddressTunnelLabel(tunnel):"No exact path selected"):"";
    return `<article class="host-network-address-row ${row.primary?"primary":""} ${detail.usable?"reachable":"blocked"}" data-host-address-id="${escapeAttr(row.id)}">
      <div><strong>${escapeHtml(row.address)}</strong><span>${escapeHtml(row.interfaceName||row.source||"Operator-owned address")}</span></div>
      <span class="host-address-zone">${escapeHtml(prettyChoice(row.zone))}</span>
      <div><strong>${escapeHtml(hostAddressReachabilityLabel(row.reachability))}</strong><span>${escapeHtml(detail.reason||row.note||"No route assessment recorded.")}</span>${path?`<small>${escapeHtml(path)}</small>`:""}</div>
      <div class="host-address-row-actions"><button class="secondary-btn small" data-host-address-edit="${escapeAttr(row.id)}" type="button">Edit</button>${row.primary?"":`<button class="danger-btn small" data-host-address-delete="${escapeAttr(row.id)}" type="button">Remove</button>`}</div>
    </article>`;
  }).join("")||'<div class="host-meta">No host address is recorded.</div>';
}
function editHostAddress(id){
  const h=activeHost(),model=hostProfileModel();if(!h||!model)return;
  const row=model.ensureNetworkAddressState(h).find(item=>item.id===id);if(!row)return;
  editingHostAddressId=id;
  setFormValue("hostAddressValue",row.address);setFormValue("hostAddressInterface",row.interfaceName);
  setFormValue("hostAddressZone",row.zone);setFormValue("hostAddressReachability",row.reachability);setFormValue("hostAddressNote",row.note);
  populateHostAddressTunnelOptions(row.tunnelId);
  if($("hostAddressValue"))$("hostAddressValue").readOnly=row.primary===true;
  if($("saveHostAddressBtn"))$("saveHostAddressBtn").textContent="Save address";
  $("cancelHostAddressBtn")?.classList.remove("hidden");
  $("hostAddressValue")?.focus();
}
function saveHostAddress(){
  const h=activeHost(),model=hostProfileModel();if(!h||!model)return;
  const rows=model.ensureNetworkAddressState(h),existing=rows.find(row=>row.id===editingHostAddressId),address=formValue("hostAddressValue").trim();
  if(!address){showToast("Enter an exact address.","warning");$("hostAddressValue")?.focus();return;}
  if(rows.some(row=>row.id!==editingHostAddressId&&row.address.toLowerCase()===address.toLowerCase())){showToast("That address already belongs to this host.","warning");return;}
  const reachability=formValue("hostAddressReachability")||"unknown",tunnelId=formValue("hostAddressTunnel");
  if(reachability==="via-path"&&!tunnelId){showToast("Select the exact recorded path for through-path reachability.","warning");$("hostAddressTunnel")?.focus();return;}
  const tunnel=(state.tunnels||[]).find(row=>row?.id===tunnelId),now=new Date().toISOString();
  const incoming={
    ...(existing||{}),
    id:existing?.id||model.stableAddressId(h.id,address),
    address:existing?.primary?h.ip:address,
    interfaceName:formValue("hostAddressInterface").trim(),
    zone:formValue("hostAddressZone")||"unknown",
    reachability,
    tunnelId:reachability==="via-path"?tunnelId:"",
    pivotHostId:reachability==="via-path"?(tunnel?.pivotHostId||""):"",
    accessContextId:reachability==="via-path"?(tunnel?.accessContextId||""):"",
    note:formValue("hostAddressNote").trim(),
    source:existing?.source||"Operator",
    primary:existing?.primary===true,
    active:true,
    firstObservedAt:existing?.firstObservedAt||now,
    lastObservedAt:now
  };
  if(existing)Object.assign(existing,incoming);else rows.push(incoming);
  h.networkAddresses=rows;model.ensureNetworkAddressState(h);
  save();clearHostAddressForm();renderHostNetworkAddresses(h);renderOscpNavigator();renderHostWorkbench();
  saveCanonicalWorkflowState("The host address").catch(()=>{});
  showToast(existing?"Address updated.":"Address added.","success");
}
async function removeHostAddress(id){
  const h=activeHost(),model=hostProfileModel();if(!h||!model)return;
  const row=model.ensureNetworkAddressState(h).find(item=>item.id===id);if(!row||row.primary)return;
  if(!(await themedConfirm(`Remove ${row.address} from this host? Retained endpoint and evidence records are not changed.`,{title:"Remove Host Address",confirmText:"Remove",danger:true})))return;
  h.networkAddresses=h.networkAddresses.filter(item=>item.id!==id);
  if(editingHostAddressId===id)clearHostAddressForm();
  save();renderHostNetworkAddresses(h);renderOscpNavigator();renderHostWorkbench();
  await saveCanonicalWorkflowState("The host address");
}
function handleHostNetworkAddressAction(event){
  const edit=event.target.closest?.("[data-host-address-edit]");if(edit){editHostAddress(edit.dataset.hostAddressEdit);return;}
  const remove=event.target.closest?.("[data-host-address-delete]");if(remove)removeHostAddress(remove.dataset.hostAddressDelete);
}
function syncPrimaryHostAddress(h,previousIp){
  const model=hostProfileModel();if(!h||!model?.ensureNetworkAddressState)return;
  const rows=model.ensureNetworkAddressState(h),primary=rows.find(row=>row.primary)||rows.find(row=>row.address.toLowerCase()===String(previousIp||"").toLowerCase());
  if(!h.ip){h.networkAddresses=rows.filter(row=>!row.primary);return;}
  if(primary){
    primary.address=h.ip;primary.id=model.stableAddressId(h.id,h.ip);primary.primary=true;primary.lastObservedAt=new Date().toISOString();
    rows.forEach(row=>{if(row!==primary)row.primary=false;});
    h.networkAddresses=rows;
  }
  model.ensureNetworkAddressState(h);
}
