function handleHostProfileSummaryAction(event){
  const button=event.target.closest?.("[data-profile-open]");if(!button)return;
  const destination=button.dataset.profileOpen,h=activeHost();
  if(destination==="notes"&&openOscpNavigatorFullCoverage("full-coverage"))return;
  if(destination==="groups"){if(h)openAssetGroupManagerForHost(h.id);return;}
  if(destination==="access"){
    if(h){h.notesContextSelection={type:"access",contextId:h.currentAccessContextId||""};persist();}
    if($("notesLibraryFilter"))$("notesLibraryFilter").value="relevant";
    setWorkspaceTab("notes");renderRecommended(h);setTimeout(()=>$("accessContextWorkspace")?.scrollIntoView({behavior:"smooth",block:"start"}),80);return;
  }
  if(["credentials","postexp","notes","evidence","review"].includes(destination))setWorkspaceTab(destination);
}
function activeWorkspacePanelName(){
  return document.querySelector(".tab-panel.active")?.dataset?.panel||"profile";
}
function prepareReconWorkspace(h=activeHost()){
  if(!h)return;
  if(!h.scans)h.scans={port:"",tcp:"",udp:"",vuln:""};
  if(!h.scanImages)h.scanImages={port:null,tcp:null,udp:null};
  ensureHostRecon(h);
  if($("scanPort"))$("scanPort").value=h.scans.port||"";
  if($("scanTcp"))$("scanTcp").value=h.scans.tcp||"";
  if($("scanUdp"))$("scanUdp").value=h.scans.udp||"";
  analyzeScanEvidenceForHost(h,{persist:false});updateScanCommands(h);
}
let exploitationSaveTimer=null;
function renderExploitationPath(h){
  const root=$("exploitationPathRoot"),projectId=state.projectId,labName=activeLabName();
  if(!root)return;
  root.dataset.epHostId=h?.id||"";root.dataset.epEngagementId=projectId||"";
  const isOwnerCurrent=()=>!!h&&state.projectId===projectId&&state.hosts[h.id]===h;
  const saveNow=()=>{if(!isOwnerCurrent())return Promise.reject(new Error("The engagement changed; reopen the original host before saving."));return saveCanonicalWorkflowState("Exploitation Path",{required:true});};
  window.AEROSExploitationPath.render(root,h,{
    newId:()=>crypto.randomUUID().replaceAll("-",""),isOwnerCurrent,
    markdown:value=>referenceNoteRenderer().renderMarkdownLite(value),bindCopies:()=>referenceNoteRenderer().bindCodeCopies(root),
    imageUrl:image=>image.storedPath?`/api/serve-file?path=${encodeURIComponent(image.storedPath)}`:"",
    confirm:themedConfirm,notify:showToast,saveNow,
    onChange:()=>{
      save();clearTimeout(exploitationSaveTimer);
      exploitationSaveTimer=setTimeout(async()=>{if(!isOwnerCurrent())return;try{await saveNow();if(root.dataset.epHostId===h.id&&root.dataset.epEngagementId===projectId){const status=root.querySelector('[data-ep-status]');if(status){status.textContent="Path saved to files.";status.classList.remove("ep-error");}}}catch(error){showToast("Exploitation Path remains in browser storage: "+error.message,"error");}},650);
    },
    upload:async(row,file)=>{
      await saveNow();
      if(!isOwnerCurrent())throw new Error("The engagement changed before the screenshot upload.");
      const form=new FormData();form.append("labName",labName);form.append("hostId",h.id);form.append("pathId",row.id);form.append("screenshot",file);
      const response=await fetch("/api/upload-exploitation-image",{method:"POST",body:form}),result=await response.json();
      if(!response.ok||!result.ok)throw new Error(result.error||"Screenshot could not be saved.");return result.image;
    },
    download:(filename,markdown)=>{const url=URL.createObjectURL(new Blob([markdown],{type:"text/markdown;charset=utf-8"})),link=document.createElement("a");link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  });
}
function renderWorkspacePanel(name,h=activeHost()){
  if(name==="oscp-navigator"){renderOscpNavigator();return;}
  if(name==="review"){if(typeof renderReview==="function")renderReview();return;}
  if(name==="exploitation-path"){renderExploitationPath(h);return;}
  if(!h)return;
  if(name==="profile"){
    renderHostAssetGroups(h);renderHostOsResolution(h);renderHostNetworkAddresses(h);renderHostProfileSummary(h);renderAdGroupSuggestion(h);
    return;
  }
  if(name==="systeminfo"){renderSystemInfo(h);return;}
  if(name==="entities"){renderEntities();return;}
  if(name==="postexp-imports"){renderPostexpImports();return;}
  if(name==="shell-writeup"){renderSuccessfulShellWriteUp(h);return;}
  if(name==="recon"){
    prepareReconWorkspace(h);renderReconWorkspace();return;
  }
  if(name==="notes"){renderRecommended(h);return;}
}
function renderWorkspace(){
  const h=activeHost(),empty=$("emptyState"),ws=$("hostWorkspace"),activePanel=activeWorkspacePanelName();
  if(!h){
    empty.classList.remove("hidden");ws.classList.add("hidden");$("currentHostTitle").textContent="No host selected";
    ["scopePill","osPill","shellPill","credPill"].forEach(id=>$(id).className="pill muted");
    $("osPill").textContent="OS unknown";$("shellPill").textContent="No access";$("credPill").textContent="No credentials";$("scopePill").textContent="Scope unknown";
    renderWorkspacePanel(activePanel,null);return;
  }
  ensureAssetGroups();ensureHostIntel(h);ensureHostMethodologyContextState(h);updateHostScopeUi(h);if(!h.evidence)h.evidence=[];
  empty.classList.add("hidden");ws.classList.remove("hidden");renderPillsOnly(h);
  [["hostIp","ip"],["hostname","hostname"],["hostAttention","attentionState"]].forEach(([id,key])=>{if($(id))$(id).value=h[key]||((id==="hostAttention")?"normal":"");});
  if($("hostOs"))$("hostOs").value=h.osResolution?.manualLock?.active?h.osResolution.manualLock.family:"unknown";
  if(editingHostAddressId&&!h.networkAddresses?.some(row=>row.id===editingHostAddressId))clearHostAddressForm();
  renderWorkspacePanel(activePanel,h);
}
function renderPillsOnly(h){
  const profile=hostProfileModel()?.deriveHostProfile?.(h,{assetGroups:state.assetGroups});
  const osResolution=osResolutionForHost(h);
  $("currentHostTitle").textContent=h.ip;$("osPill").textContent=osResolution.status==="conflict"?"OS conflict":osResolution.family==="unknown"?"OS unknown":`${osResolution.family.toUpperCase()} · ${osResolution.confidence}`;$("osPill").className=osResolution.status==="conflict"?"pill attention":osResolution.family==="unknown"?"pill muted":"pill";
  const accessCount=profile?.access?.contexts||0,working=profile?.credentials?.working||0,secrets=profile?.credentials?.secrets||0;
  $("shellPill").textContent=accessCount?`${accessCount} access context${accessCount===1?"":"s"}`:"No access";$("shellPill").className=accessCount?"pill":"pill muted";
  $("credPill").textContent=working?`${working} working credential${working===1?"":"s"}`:secrets?`${secrets} secret${secrets===1?"":"s"}`:"No credentials";$("credPill").className=(working||secrets)?"pill":"pill muted";
}
function scanTextForHost(h){
  const s=h?.scans||{};
  const serviceText=Object.entries(h?.services||{})
    .filter(([,value])=>value?.checked)
    .map(([key,value])=>`${key} ${value?.ports||""}`)
    .join("\n");
  return [s.port,s.tcp,s.udp,s.vuln,serviceText].filter(Boolean).join("\n").toLowerCase();
}

function hostPorts(h){
  const ports=new Set();
  try{selectedTcpPorts(h).forEach(port=>ports.add(Number(port)));}catch{}
  const text=scanTextForHost(h);
  [...text.matchAll(/(\d{1,5})\/(?:tcp|udp)\s+(?:open|open\|filtered)/gi)].forEach(match=>{
    const port=Number(match[1]);
    if(port>0&&port<=65535)ports.add(port);
  });
  Object.values(h?.services||{}).forEach(value=>{
    if(!value?.checked)return;
    String(value.ports||"").split(/[\s,;/]+/).forEach(raw=>{
      const port=Number(raw);
      if(port>0&&port<=65535)ports.add(port);
    });
  });
  return ports;
}

function hostHasAnyPort(h,ports){
  const open=hostPorts(h);
  return (ports||[]).some(port=>open.has(Number(port)));
}

function visibleCredentialRecordsForHost(h){
  if(!h)return [];
  const rows=[];
  (h.credentials||[]).forEach(credential=>rows.push({...credential,sourceHost:h}));
  allCredentialRecords()
    .filter(credential=>credential.sourceHostId!==h.id&&credentialVisibleToHost(credential,h,state.hosts[credential.sourceHostId]))
    .forEach(credential=>rows.push({...credential,sourceHost:state.hosts[credential.sourceHostId]}));
  return rows;
}

function credentialFactsForHost(h){
  const rows=visibleCredentialRecordsForHost(h);
  return {rows,hasAny:rows.length>0};
}

function normalizeReferenceServiceName(value){
  if(window.AerosReferenceMatcher?.normalizeServiceName)return window.AerosReferenceMatcher.normalizeServiceName(value);
  return String(value||"").trim().toLowerCase().replace(/[_\s]+/g,"-");
}

function detectedReferenceServices(h){
  const found=new Set();
  Object.entries(h?.services||{}).forEach(([key,value])=>{
    if(!value?.checked)return;
    const normalized=normalizeReferenceServiceName(key);
    if(normalized)found.add(normalized);
  });
  (h?.serviceInventory||[]).forEach(row=>{
    const service=normalizeReferenceServiceName(row?.service||row?.serviceRaw);
    const meaningful=value=>scanIntelligence()?.meaningfulEvidenceValue?scanIntelligence().meaningfulEvidenceValue(value,{assignedLabel:row?.serviceHint||row?.serviceRaw}):String(value||"").trim();
    const identified=row?.identified===true||row?.serviceConfirmed===true||row?.identificationState==="identified"||!![row?.product,row?.version,row?.details].map(meaningful).find(Boolean)||row?.scriptEvidence===true;
    if(identified&&service&&!["unknown","unidentified"].includes(service))found.add(service);
  });
  return found;
}

function referenceNoteMatchContext(h,facts){
  const hasCreds=!!(h?.hasCreds||facts?.hasAny);
  const activeEvents=[];
  if(h?.hasShell)activeEvents.push("foothold-acquired","new-access-context");
  if(h?.isRootAdmin)activeEvents.push("privilege-changed");
  if(hasCreds)activeEvents.push("credential-discovered");
  return {
    hostOs:h?.os||"unknown",
    detectedServices:[...detectedReferenceServices(h)],
    openPorts:[...hostPorts(h)],
    hasShell:!!h?.hasShell,
    hasCreds,
    hasDomain:hostHasAdContext(h),
    isRootAdmin:!!h?.isRootAdmin,
    assetGroupTypes:assetGroupsForHost(h).map(group=>group.type),
    activeEvents
  };
}
function contextualReferenceContext(h,objectiveId,route={}){
  const base=referenceNoteMatchContext(h,credentialFactsForHost(h));
  const access=(h?.accessContexts||[]).filter(row=>row&&row.active!==false);
  const current=access.find(row=>row.id===route.accessContextId)||access.find(row=>row.id===h?.currentAccessContextId)||access[0]||null;
  const elevated=["root-admin","root","administrator","admin","system"].includes(String(current?.privilege||"").toLowerCase());
  const capability=window.AerosMethodologyTasks?.webObjectiveCapability?.(objectiveId)||null;
  const requiresExactWebOrigin=!!(
    capability&&Array.isArray(capability.contextTypes)&&capability.contextTypes.includes("web-origin")&&
    (capability.requiresOrigin===true||route.originId)
  );
  const origin=route.originId?(h?.recon?.webTargets||[]).find(row=>navigatorCore()?.originIdentity?.(row)===route.originId):null;
  const originEndpointId=String(origin?.endpointId||origin?.serviceEndpointId||"");
  const exactEndpointId=String(route.endpointId||originEndpointId||"");
  const endpoint=exactEndpointId?serviceInventoryByIdentity(h,exactEndpointId):null;
  const meaningful=value=>scanIntelligence()?.meaningfulEvidenceValue
    ?scanIntelligence().meaningfulEvidenceValue(value,{assignedLabel:endpoint?.serviceHint||endpoint?.serviceRaw})
    :String(value||"").trim();
  const endpointIdentified=!!endpoint&&(endpoint.identified===true||endpoint.serviceConfirmed===true||String(endpoint.identificationState||"").toLowerCase()==="identified"||!![endpoint.product,endpoint.version,endpoint.details,endpoint.extraInfo].map(meaningful).find(Boolean)||endpoint.scriptEvidence===true);
  let originScheme="";
  try{originScheme=new URL(String(origin?.url||origin?.value||"")).protocol.replace(":","").toLowerCase();}catch(_error){}
  const endpointService=normalizeReferenceServiceName(endpoint?.service||endpoint?.serviceRaw);
  const exactWebConfirmed=!!(
    requiresExactWebOrigin&&origin&&endpointIdentified&&
    (!originEndpointId||!route.endpointId||originEndpointId===route.endpointId)&&
    ["http","https"].includes(originScheme)&&originScheme===endpointService
  );
  const exactConfirmedService=requiresExactWebOrigin
    ?(exactWebConfirmed?[originScheme]:[])
    :(endpointIdentified&&endpointService?[endpointService]:[...detectedReferenceServices(h)]);
  const exactPorts=endpoint&&Number(endpoint.port)>0?[Number(endpoint.port)]:base.openPorts;
  return {
    ...base,
    objectiveId:objectiveId,
    profileId:isOscpEngagement()?"oscp":"general",
    policyId:isOscpEngagement()?"offsec-oscp":"",
    detectedServices:exactConfirmedService,
    confirmedServices:exactConfirmedService,
    openPorts:exactPorts,
    hasShell:!!(current||h?.hasShell),
    hasElevatedAccess:elevated,
    hasTunnel:(state.tunnels||[]).some(row=>row&&row.active!==false&&(!row.hostId||row.hostId===h?.id)),
    endpointId:route.endpointId||"",
    originId:route.originId||"",
    accessContextId:route.accessContextId||"",
    requiresConfirmedWebOrigin:requiresExactWebOrigin,
    exactOriginConfirmed:exactWebConfirmed
  };
}
function contextualNotesForObjective(h,objectiveId,route={}){
  const matcher=window.AerosReferenceMatcher;
  if(!h||!objectiveId||!matcher?.selectContextualNotes)return {exact:[],strong:[]};
  return matcher.selectContextualNotes(
    allPlaybooks().filter(isImportedReferenceNote),
    contextualReferenceContext(h,objectiveId,route),
    12
  );
}

function importedReferenceNoteMatches(note,h,facts){
  if(!h)return false;
  const matcher=window.AerosReferenceMatcher;
  if(!matcher?.matchNormalizedNote)return false;
  const result=matcher.matchNormalizedNote(note,referenceNoteMatchContext(h,facts));
  return !!(result.metadataComplete&&result.matched);
}

function noteModuleMatches(note,moduleName){
  const matcher=window.AerosReferenceMatcher;
  if(matcher?.moduleMatches)return matcher.moduleMatches(note,moduleName);
  const selected=String(moduleName||"general").trim().toLowerCase();
  if(selected==="all")return true;
  const modules=Array.isArray(note?.modules)?note.modules.map(value=>String(value||"").trim().toLowerCase()):[];
  return modules.length?modules.includes(selected):selected==="general";
}

function normalizeReferenceNotePath(value){
  return String(value||"").trim().replace(/\\/g,"/").replace(/^\/+/,"").toLowerCase();
}
function installedReferenceNoteFor(note){
  if(!note)return null;
  const installed=Array.isArray(state.dynamicNotes)?state.dynamicNotes:[];
  const noteId=String(note.id||"").trim();
  if(noteId){
    const byId=installed.find(candidate=>String(candidate?.id||"").trim()===noteId);
    if(byId)return byId;
  }
  const notePath=normalizeReferenceNotePath(note.notePath||note.path||"");
  if(notePath){
    const byPath=installed.find(candidate=>normalizeReferenceNotePath(candidate?.notePath||candidate?.path||"")===notePath);
    if(byPath)return byPath;
  }
  return null;
}
function allPlaybooks(){
  const out=[];
  const seen=new Set();

  // Reference Notes are optional installed content. Only display records the
  // running reference-pack API can actually open. Recommendation behavior is
  // driven entirely by each installed note's normalized manifest metadata.
  (state.dynamicNotes||[]).forEach(note=>{
    if(!note)return;
    const key=String(note.id||normalizeReferenceNotePath(note.notePath||note.path)||note.title||"").toLowerCase();
    if(!key||seen.has(key))return;
    seen.add(key);
    out.push(note);
  });
  return out;
}
function recommendedNotes(h,installedPlaybooks=null){
  if(!h)return [];
  const facts=credentialFactsForHost(h);
  return (installedPlaybooks||allPlaybooks()).filter(note=>isImportedReferenceNote(note)&&importedReferenceNoteMatches(note,h,facts));
}
function notePathFor(note,h){return note.notePath||note.path||"";}
