// A loaded lab must never blank System Info we already hold locally. If the
// project JSON has no System Info for a host (older labs stored it only in
// the internal library), keep the copy already in state/localStorage instead of wiping it.
function sysInfoHasContent(si){
  if(!si||typeof si!=="object")return false;
  var found=false;
  (function scan(v){
    if(found)return;
    if(typeof v==="string"){if(v.trim())found=true;return;}
    if(Array.isArray(v)){if(v.length)found=true;return;}
    if(v&&typeof v==="object"){for(var k in v){if(k==="credentialFindingsMigrated")continue;scan(v[k]);}}
  })(si);
  return found;
}
function preserveSystemInfoOnLoad(loaded){
  if(!loaded||!loaded.hosts||!state.hosts)return;
  var byId={},byIp={};
  Object.keys(state.hosts).forEach(function(id){var h=state.hosts[id];if(!h)return;byId[id]=h;if(h.ip)byIp[String(h.ip)]=h;});
  Object.keys(loaded.hosts).forEach(function(id){
    var lh=loaded.hosts[id];if(!lh)return;
    if(sysInfoHasContent(lh.systemInfo))return;                 // loaded copy is real — keep it
    var cur=byId[id]||(lh.ip&&byIp[String(lh.ip)]);
    if(cur&&sysInfoHasContent(cur.systemInfo))lh.systemInfo=cur.systemInfo; // keep local copy
  });
}
