  const scopeSummary=resolved.length?[hostCount?`${hostCount} host${hostCount===1?"":"s"}`:"",scopeOnly?`${scopeOnly} scope-only`:"",outCount?`${outCount} out-of-scope`:"",removals?`${removals} removal${removals===1?"":"s"}`:""].filter(Boolean).join(" · "):"Scope not defined";
