const SCOPE_RULE_TYPE_LABELS={ip:"IP Address",cidr:"CIDR Range",hostname:"Hostname","wildcard-domain":"Wildcard Domain",url:"URL / Origin","url-path":"URL Path Prefix",port:"Port / Protocol","cloud-account":"Cloud Account / Tenant",repository:"Repository","mobile-app":"Mobile Application",custom:"Custom Asset"};
const SCOPE_RULE_STATUS_LABELS={"in-scope":"In Scope","out-of-scope":"Out of Scope",restricted:"Restricted",unknown:"Unknown","needs-review":"Needs Review"};
function migrateLegacyScopeRules(scope){
  if(!scope||!Array.isArray(scope.rules))return;
  if(scope.rules.length)return;
  const now=new Date().toISOString();
  (scope.inScope||[]).forEach(value=>scope.rules.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()+Math.random()),type:inferScopeRuleType(value),value,status:"in-scope",source:"manual",documentId:"",protocol:"",port:"",reason:"Migrated from legacy in-scope list",notes:"",confirmed:!!scope.confirmed,createdAt:now,updatedAt:now}));
  (scope.outOfScope||[]).forEach(value=>scope.rules.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()+Math.random()),type:inferScopeRuleType(value),value,status:"out-of-scope",source:"manual",documentId:"",protocol:"",port:"",reason:"Migrated from legacy out-of-scope list",notes:"",confirmed:!!scope.confirmed,createdAt:now,updatedAt:now}));
}
function inferScopeRuleType(value){const v=String(value||"").trim();if(/^\d{1,3}(?:\.\d{1,3}){3}\/\d{1,2}$/.test(v))return"cidr";if(/^\d{1,3}(?:\.\d{1,3}){3}$/.test(v))return"ip";if(/^https?:\/\//i.test(v))return v.replace(/^https?:\/\/[^/]+/i,"").startsWith("/")&&v.replace(/^https?:\/\/[^/]+/i,"")!=="/"?"url-path":"url";if(v.startsWith("*."))return"wildcard-domain";if(/^(tcp|udp)\/?\d/i.test(v))return"port";if(/^[a-z0-9.-]+\.[a-z]{2,}$/i.test(v))return"hostname";return"custom";}
function scopeRules(){return ensureEngagementConfig().scope.rules;}
function scopeStatusRank(status){return {"out-of-scope":50,restricted:40,"needs-review":30,unknown:20,"in-scope":10}[status]||0;}
function normalizeScopeHost(value){return String(value||"").trim().toLowerCase().replace(/^\[|\]$/g,"").replace(/\.$/,"");}
function ipv4ToInt(ip){const parts=String(ip||"").trim().split(".");if(parts.length!==4)return null;let n=0;for(const part of parts){if(!/^\d{1,3}$/.test(part))return null;const v=Number(part);if(v<0||v>255)return null;n=(n*256)+v;}return n>>>0;}
function ipInCidr(ip,cidr){const [base,bitsRaw]=String(cidr||"").split("/");const bits=Number(bitsRaw),ipn=ipv4ToInt(ip),basen=ipv4ToInt(base);if(ipn===null||basen===null||!Number.isInteger(bits)||bits<0||bits>32)return false;if(bits===0)return true;const mask=(0xffffffff << (32-bits))>>>0;return (ipn&mask)===(basen&mask);}
function parseScopeTarget(target={}){let raw=String(target.value||target.ip||target.hostname||target.url||"").trim(),url=null,host="",path="",port=String(target.port||"").trim(),protocol=String(target.protocol||"").trim().toLowerCase();try{if(/^https?:\/\//i.test(raw)){url=new URL(raw);host=normalizeScopeHost(url.hostname);path=url.pathname||"/";if(!port)port=url.port||((url.protocol==="https:")?"443":"80");if(!protocol)protocol="tcp";}}catch{}if(!host){host=normalizeScopeHost(target.hostname||target.ip||raw);if(host.includes(":" )&&ipv4ToInt(host)===null){const m=host.match(/^([^:]+):(\d+)$/);if(m){host=normalizeScopeHost(m[1]);if(!port)port=m[2];}}}return {raw,host,path,port,protocol,url};}
function scopeRuleMatches(rule,target){const t=parseScopeTarget(target),value=String(rule.value||"").trim(),rv=normalizeScopeHost(value);switch(rule.type){case"ip":return ipv4ToInt(t.host)!==null&&t.host===rv;case"cidr":return ipInCidr(t.host,value);case"hostname":return t.host===rv;case"wildcard-domain":{const suffix=rv.replace(/^\*\./,"");return !!suffix&&(t.host===suffix||t.host.endsWith(`.${suffix}`));}case"url":try{const u=new URL(value);return t.host===normalizeScopeHost(u.hostname)&&(!u.port||String(t.port)===u.port)&&(!u.pathname||u.pathname==="/"||t.path.startsWith(u.pathname));}catch{return false;}case"url-path":try{const u=new URL(value);return t.host===normalizeScopeHost(u.hostname)&&t.path.startsWith(u.pathname||"/");}catch{return t.path.startsWith(value);}case"port":{const ruleProto=String(rule.protocol||"").toLowerCase(),rulePort=String(rule.port||value).match(/\d{1,5}/)?.[0]||"";return (!ruleProto||!t.protocol||ruleProto===t.protocol)&&!!rulePort&&String(t.port)===rulePort;}case"custom":return !!value&&(t.raw.toLowerCase()===value.toLowerCase()||t.host===rv);default:return false;}}
function evaluateScopeTarget(target){const rules=scopeRules().filter(r=>r&&r.value);const matches=rules.filter(r=>scopeRuleMatches(r,target)).sort((a,b)=>scopeStatusRank(b.status)-scopeStatusRank(a.status)||(Number(b.confirmed)-Number(a.confirmed)));if(!matches.length)return {status:"unknown",label:"Unknown",reason:"No structured scope rule matched this asset.",rule:null,matches:[]};const rule=matches[0];return {status:rule.status||"unknown",label:SCOPE_RULE_STATUS_LABELS[rule.status]||"Unknown",reason:rule.reason||`Matched ${SCOPE_RULE_TYPE_LABELS[rule.type]||"scope"} rule: ${rule.value}`,rule,matches};}
function scopeDecisionTitle(decision){if(!decision)return"No scope decision";const source=decision.rule?.documentId?roeDocuments().find(d=>d.id===decision.rule.documentId):null;return [decision.label,decision.reason,decision.rule?.value?`Rule: ${decision.rule.value}`:"",source?`Source: ${source.displayName||source.originalFilename}`:""].filter(Boolean).join("\n");}
function updateHostScopeUi(h){const pill=$("scopePill");if(!pill)return;if(!h){pill.className="pill muted scope-pill";pill.textContent="Scope unknown";pill.title="No host selected";return;}const d=evaluateScopeTarget({ip:h.ip,hostname:h.hostname});pill.className=`pill scope-pill scope-${d.status}`;pill.textContent=d.label;pill.title=scopeDecisionTitle(d);h.scopeDecision={status:d.status,ruleId:d.rule?.id||"",evaluatedAt:new Date().toISOString()};}

function syncLegacyScopeListsFromRules(){const s=ensureEngagementConfig().scope;s.inScope=s.rules.filter(r=>r.status==="in-scope").map(r=>r.value).filter(Boolean);s.outOfScope=s.rules.filter(r=>r.status==="out-of-scope").map(r=>r.value).filter(Boolean);if($("optionInScope"))$("optionInScope").value=s.inScope.join("\n");if($("optionOutOfScope"))$("optionOutOfScope").value=s.outOfScope.join("\n");}
function populateScopeRuleDocuments(selected=""){const el=$("scopeRuleDocument");if(!el)return;el.innerHTML='<option value="">No linked document</option>';roeDocuments().forEach(d=>{const o=document.createElement("option");o.value=d.id;o.textContent=d.displayName||d.originalFilename;o.selected=d.id===selected;el.appendChild(o);});}
function setScopeRuleModalOpen(open,rule=null){const modal=$("scopeRuleModal");if(!modal)return;if(open){const r=rule||{};$("scopeRuleId").value=r.id||"";$("scopeRuleType").value=r.type||"ip";$("scopeRuleStatus").value=r.status||"in-scope";$("scopeRuleValue").value=r.value||"";$("scopeRuleSource").value=r.source||"manual";populateScopeRuleDocuments(r.documentId||"");$("scopeRuleProtocol").value=r.protocol||"";$("scopeRulePort").value=r.port||"";$("scopeRuleConfirmed").checked=!!r.confirmed;$("scopeRuleReason").value=r.reason||"";$("scopeRuleNotes").value=r.notes||"";$("scopeRuleError").classList.add("hidden");$("scopeRuleModalTitle").textContent=r.id?"Edit Scope Rule":"Add Scope Rule";$("saveScopeRuleBtn").textContent=r.id?"Save Changes":"Save Scope Rule";modal.classList.remove("hidden");document.body.classList.add("modal-open");setTimeout(()=>$("scopeRuleValue")?.focus(),40);}else{modal.classList.add("hidden");if(document.querySelectorAll('.host-modal-backdrop:not(.hidden),.app-modal-backdrop:not(.hidden)').length===0)document.body.classList.remove("modal-open");}}
function saveScopeRule(){const value=($("scopeRuleValue")?.value||"").trim(),error=$("scopeRuleError");if(!value){error.textContent="Enter an asset or rule value.";error.classList.remove("hidden");return;}const rules=scopeRules(),id=$("scopeRuleId").value||((crypto.randomUUID&&crypto.randomUUID())||String(Date.now()+Math.random())),existing=rules.find(r=>r.id===id),now=new Date().toISOString();const entry={id,type:$("scopeRuleType").value||"custom",status:$("scopeRuleStatus").value||"needs-review",value,source:$("scopeRuleSource").value||"manual",documentId:$("scopeRuleDocument").value||"",protocol:($("scopeRuleProtocol").value||"").trim(),port:($("scopeRulePort").value||"").trim(),confirmed:!!$("scopeRuleConfirmed").checked,reason:($("scopeRuleReason").value||"").trim(),notes:($("scopeRuleNotes").value||"").trim(),createdAt:existing?.createdAt||now,updatedAt:now};if(existing)Object.assign(existing,entry);else rules.push(entry);syncLegacyScopeListsFromRules();persist();saveLabState(true).catch(err=>showToast(`Could not save scope rule: ${err.message}`,"error"));renderScopeRules();setScopeRuleModalOpen(false);showToast(existing?"Scope rule updated.":"Scope rule added.","success");}
function renderScopeRules(){const list=$("scopeRuleList"),summary=$("scopeRuleSummary");if(!list)return;const rules=scopeRules(),status=$("scopeRuleStatusFilter")?.value||"all",query=($("scopeRuleSearch")?.value||"").trim().toLowerCase();const filtered=rules.filter(r=>(status==="all"||r.status===status)&&(!query||[r.value,r.reason,r.notes,SCOPE_RULE_TYPE_LABELS[r.type],SCOPE_RULE_STATUS_LABELS[r.status]].join(" ").toLowerCase().includes(query)));if(summary){const counts={};rules.forEach(r=>counts[r.status]=(counts[r.status]||0)+1);summary.innerHTML=['in-scope','out-of-scope','restricted','needs-review','unknown'].map(k=>`<span class="scope-summary-chip scope-${k}"><strong>${counts[k]||0}</strong>${SCOPE_RULE_STATUS_LABELS[k]}</span>`).join('');}if(!filtered.length){list.innerHTML=`<div class="scope-rule-empty"><strong>${rules.length?'No matching scope rules':'No structured scope rules yet'}</strong><p>${rules.length?'Adjust the filter or search.':'Add explicit scope boundaries that can later be evaluated automatically.'}</p></div>`;return;}const docs=roeDocuments();list.innerHTML=filtered.map(r=>{const doc=docs.find(d=>d.id===r.documentId);return `<article class="scope-rule-card status-${escapeAttr(r.status)}"><div class="scope-rule-status-mark" aria-hidden="true"></div><div class="scope-rule-main"><div class="scope-rule-badges"><span class="scope-status-badge">${escapeHtml(SCOPE_RULE_STATUS_LABELS[r.status]||prettyChoice(r.status))}</span><span class="scope-type-badge">${escapeHtml(SCOPE_RULE_TYPE_LABELS[r.type]||prettyChoice(r.type))}</span>${r.confirmed?'<span class="scope-confirmed-badge">Confirmed</span>':'<span class="scope-review-badge">Unconfirmed</span>'}</div><h4>${escapeHtml(r.value)}</h4><p>${escapeHtml(r.reason||'No reason recorded.')}</p><small>${escapeHtml(doc?`Source: ${doc.displayName||doc.originalFilename}`:`Source: ${prettyChoice(r.source||'manual')}`)}${r.protocol||r.port?` · ${escapeHtml([r.protocol,r.port].filter(Boolean).join('/'))}`:''}</small></div><div class="scope-rule-actions"><button class="ghost-btn" type="button" data-scope-action="edit" data-id="${escapeAttr(r.id)}">Edit</button><button class="danger-btn" type="button" data-scope-action="delete" data-id="${escapeAttr(r.id)}">Delete</button></div></article>`}).join('');}
async function handleScopeRuleAction(e){const btn=e.target.closest('[data-scope-action]');if(!btn)return;const rule=scopeRules().find(r=>r.id===btn.dataset.id);if(!rule)return;if(btn.dataset.scopeAction==='edit'){setScopeRuleModalOpen(true,rule);return;}if(btn.dataset.scopeAction==='delete'){const ok=await themedConfirm(`Delete the scope rule "${rule.value}"?`,{title:"Delete Scope Rule",confirmText:"Delete",danger:true});if(!ok)return;ensureEngagementConfig().scope.rules=scopeRules().filter(r=>r.id!==rule.id);syncLegacyScopeListsFromRules();persist();await saveLabState(true).catch(err=>showToast(`Could not save scope changes: ${err.message}`,"error"));renderScopeRules();showToast("Scope rule deleted.","success");}}

const ROE_KIND_LABELS={roe:"Rules of Engagement","program-policy":"Program Policy",authorization:"Authorization Letter","scope-document":"Scope Document"};
function roeDocuments(){return ensureEngagementConfig().documents.filter(d=>d&&d.category==="scope-authorization");}
function humanFileSize(bytes){const n=Number(bytes)||0;if(n<1024)return `${n} B`;if(n<1024*1024)return `${(n/1024).toFixed(1)} KB`;return `${(n/1024/1024).toFixed(1)} MB`;}
function renderRoeDocuments(){
  const list=$("roeDocumentList"),status=$("roeDocumentStatus"),docs=roeDocuments(),lab=activeLabName();if(status)status.textContent=lab?`Stored internally for ${lab}.`:'Select an engagement before uploading authorization documents.';if(!list)return;
  if(!docs.length){list.innerHTML='<div class="roe-document-empty"><strong>No authorization documents uploaded</strong><p>Upload a Rules of Engagement, program policy, authorization letter, or scope document.</p></div>';return;}
  const selected=ensureEngagementConfig().scope.selectedDocumentId||docs[0]?.id||"";
  list.innerHTML=docs.map(d=>`<article class="roe-document-card ${d.id===selected?'selected':''}" data-roe-document-id="${escapeAttr(d.id)}"><div class="roe-document-icon"><svg viewBox="0 0 24 24"><path d="M6 2h8l4 4v16H6z"/><path d="M14 2v5h5M9 12h6M9 16h6"/></svg></div><div class="roe-document-main"><div><span class="roe-kind-badge">${escapeHtml(ROE_KIND_LABELS[d.kind]||prettyChoice(d.kind))}</span>${versionedRecordBadge(d)}${d.extractionWarning?'<span class="roe-warning-badge">Extraction Warning</span>':''}</div><h4>${escapeHtml(d.displayName||d.originalFilename)}</h4><p>${escapeHtml(d.originalFilename||'Document')} · ${humanFileSize(d.size)} · ${escapeHtml(new Date(d.lastSeenAt||d.uploadedAt||Date.now()).toLocaleString())}</p>${d.sha256?`<code title="${escapeAttr(d.sha256)}">SHA-256 ${escapeHtml(String(d.sha256).slice(0,16))}…</code>`:""}${d.extractionWarning?`<small>${escapeHtml(d.extractionWarning)}</small>`:''}</div><div class="roe-document-actions"><button class="ghost-btn" type="button" data-roe-action="review" data-id="${escapeAttr(d.id)}">Review Text</button><button class="ghost-btn" type="button" data-roe-action="download" data-id="${escapeAttr(d.id)}">Download</button><button class="danger-btn" type="button" data-roe-action="delete" data-id="${escapeAttr(d.id)}">Delete</button></div></article>`).join('');
}
function loadSelectedRoeText(id){const c=ensureEngagementConfig(),doc=roeDocuments().find(d=>d.id===id);if(!doc)return;c.scope.selectedDocumentId=id;c.scope.extractedText=doc.extractedText||c.scope.extractedText||"";if($("optionRoeExtractedText"))$("optionRoeExtractedText").value=c.scope.extractedText;if(c.scope.roeStatus==="not-provided")c.scope.roeStatus="imported-needs-review";if($("optionRoeStatus"))$("optionRoeStatus").value=c.scope.roeStatus;persist();renderRoeDocuments();}
function engagementDocuments(){return (ensureEngagementConfig().documents||[]).filter(d=>d&&d.category!=="scope-authorization");}
function documentCategoryLabel(v){return ({architecture:"Architecture Diagram","asset-inventory":"Asset Inventory","vpn-instructions":"VPN / Access","client-reference":"Client Reference",authorization:"Authorization Material","scope-document":"Scope Document",supporting:"Supporting File",other:"Other"})[v]||String(v||"Document").replaceAll("-"," ");}
function formatDocumentBytes(n){n=Number(n||0);if(n<1024)return `${n} B`;if(n<1048576)return `${(n/1024).toFixed(1)} KB`;return `${(n/1048576).toFixed(1)} MB`;}

function upsertVersionedRecord(records,item){
  const rows=Array.isArray(records)?records:[];if(!item||typeof item!=="object")return item;
  let index=rows.findIndex(row=>row?.id===item.id);
  if(index<0&&item.sha256)index=rows.findIndex(row=>row?.sha256===item.sha256||(row?.revisions||[]).some(revision=>revision?.sha256===item.sha256));
  if(index>=0)rows.splice(index,1,item);else rows.push(item);return item;
}
function importOutcomeLabel(item){return ({new:"New artifact",updated:"Updated revision",unchanged:"Unchanged duplicate",conflict:"Conflict",skipped:"Skipped"})[String(item?.importOutcome||item?.lastImportStatus||"").toLowerCase()]||"Retained";}
function versionedRecordBadge(item){const revision=Math.max(1,Number(item?.currentRevision)||1),count=Math.max(revision,Number(item?.revisionCount)||item?.revisions?.length||1);return `<span class="document-import-status">${escapeHtml(importOutcomeLabel(item))}</span><span class="document-revision-badge">Revision ${revision} of ${count}</span>`;}
async function cleanupUncommittedDocument(lab,documentRecord,endpoint){
  if(!["new","updated"].includes(String(documentRecord?.importOutcome||"").toLowerCase()))return;
  try{
    await fetch(endpoint,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({
      labName:lab,storedFilename:documentRecord.storedFilename||"",extractedFilename:documentRecord.extractedFilename||"",storedFilenames:[]
    })});
  }catch(error){}
}

function renderEngagementDocuments(){
  const list=$("engagementDocumentList"),status=$("engagementDocumentStatus");if(!list)return;const lab=activeLabName();if(status)status.textContent=lab?`Stored internally for ${lab}. Maximum file size: 50 MB.`:"Select an engagement before uploading documents.";
  const filter=$("engagementDocumentFilter")?.value||"all",q=($("engagementDocumentSearch")?.value||"").trim().toLowerCase();let docs=engagementDocuments();if(filter!=="all")docs=docs.filter(d=>d.category===filter);if(q)docs=docs.filter(d=>[d.displayName,d.originalFilename,d.notes,documentCategoryLabel(d.category)].some(v=>String(v||"").toLowerCase().includes(q)));
  if(!docs.length){list.innerHTML='<div class="roe-document-empty"><strong>No matching engagement documents</strong><span>Upload a file or adjust the current filters.</span></div>';return;}
  list.innerHTML=docs.map(d=>`<article class="engagement-document-card"><div class="engagement-document-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3h7l4 4v14H7z"/><path d="M14 3v5h5"/><path d="M10 13h5M10 17h5"/></svg></div><div class="engagement-document-main"><div class="document-card-badges"><span>${escapeHtml(documentCategoryLabel(d.category))}</span>${versionedRecordBadge(d)}${d.extractionWarning?'<span class="roe-warning-badge">Text warning</span>':''}</div><h4>${escapeHtml(d.displayName||d.originalFilename||"Document")}</h4><p>${escapeHtml(d.originalFilename||"")} · ${formatDocumentBytes(d.size)}</p>${d.sha256?`<code title="${escapeAttr(d.sha256)}">SHA-256 ${escapeHtml(String(d.sha256).slice(0,16))}…</code>`:""}${d.notes?`<small>${escapeHtml(d.notes)}</small>`:""}</div><div class="engagement-document-actions">${d.extractedText?`<button class="secondary-btn" type="button" data-document-action="review" data-id="${escapeAttr(d.id)}">Review Text</button>`:""}<button class="secondary-btn" type="button" data-document-action="download" data-id="${escapeAttr(d.id)}">Download</button><button class="danger-btn" type="button" data-document-action="delete" data-id="${escapeAttr(d.id)}">Delete</button></div></article>`).join("");
}
async function uploadEngagementDocument(){
  const lab=activeLabName(),file=$("engagementDocumentFile")?.files?.[0];if(!lab)return showToast("Select and load an engagement first.","error");if(!file)return showToast("Choose a file to upload.","error");
  const c=ensureEngagementConfig(),fd=new FormData();fd.append("labName",lab);fd.append("category",$("engagementDocumentCategory")?.value||"supporting");fd.append("displayName",($("engagementDocumentDisplayName")?.value||"").trim());fd.append("notes",($("engagementDocumentNotes")?.value||"").trim());fd.append("knownDocuments",JSON.stringify(engagementDocuments()));fd.append("document",file);
  const btn=$("uploadEngagementDocumentBtn");if(btn)btn.disabled=true;
  const previousDocuments=c.documents.slice();let uploaded=null;
  try{
    const r=await fetch("/api/upload-engagement-document",{method:"POST",body:fd}),d=await r.json();
    if(!r.ok||!d.ok)throw new Error(d.error||"Upload failed");
    uploaded=d.document;upsertVersionedRecord(c.documents,uploaded);persist();
    try{await saveLabState(true);}
    catch(error){c.documents=previousDocuments;persist();await cleanupUncommittedDocument(lab,uploaded,"/api/delete-engagement-document");throw error;}
    $("engagementDocumentFile").value="";$("engagementDocumentDisplayName").value="";$("engagementDocumentNotes").value="";$("engagementDocumentFileName").textContent="No file selected.";renderEngagementDocuments();showToast(`${importOutcomeLabel(uploaded)} · ${uploaded.originalFilename}`,"success");
  }catch(e){showToast(`Document upload failed: ${e.message}`,"error");}
  finally{if(btn)btn.disabled=false;}
}
async function importEngagementDocumentFiles(fileList,options={}){
  const lab=activeLabName(),host=options.host||exactHostOwner(options.hostId)?.host||activeHost(),files=Array.from(fileList||[]).filter(Boolean);
  if(!lab)throw new Error("Save the current engagement before importing documents.");
  if(!host)throw new Error("The intended document host is missing or stale.");
  const engagementId=String(options.engagementId||state.projectId||state.projectName||""),hostId=String(host.id||""),targetAddress=String(options.targetAddress||host.ip||""),records=[],c=ensureEngagementConfig(),previousDocuments=c.documents.slice();
  try{
    for(const file of files){
      if(exactHostOwner(hostId)?.host!==host)throw new Error("The intended document host is missing or stale.");
      const fd=new FormData();fd.append("labName",lab);fd.append("category",options.category||"supporting");fd.append("displayName","");fd.append("notes",`Imported from ${options.objectiveId||options.taskId||"Import Results"}.`);fd.append("knownDocuments",JSON.stringify(engagementDocuments()));fd.append("document",file);
      const response=await fetch("/api/upload-engagement-document",{method:"POST",body:fd}),data=await response.json();
      if(!response.ok||!data.ok)throw new Error(`${file.name}: ${data.error||"Document upload failed"}`);
      const documentRecord={...data.document,engagementId,hostId,targetAddress,observedTargetAddress:targetAddress,parserType:"engagement-document",sourceArtifactId:String(data.document?.id||""),sourceRevision:Number(data.document?.currentRevision||data.document?.revisionCount)||1,objective:String(options.objectiveId||options.taskId||""),updatedAt:new Date().toISOString()};
      upsertVersionedRecord(c.documents,documentRecord);records.push(documentRecord);
    }
    persist();await saveLabState(true);if(activeHost()===host)renderEngagementDocuments();
    return {ok:true,records,hostId};
  }catch(error){
    c.documents=previousDocuments;persist();
    await Promise.all(records.map(record=>cleanupUncommittedDocument(lab,record,"/api/delete-engagement-document")));
    throw error;
  }
}
async function handleEngagementDocumentAction(e){
  const btn=e.target.closest("[data-document-action]");if(!btn)return;
  const doc=engagementDocuments().find(d=>d.id===btn.dataset.id);if(!doc)return;
  const action=btn.dataset.documentAction;
  if(action==="review"){showToast("Extracted text is available in the stored document metadata; a dedicated document preview is planned.","info");return;}
  if(action==="download"){
    try{
      const r=await fetch(`/api/download-engagement-document?labName=${encodeURIComponent(activeLabName())}&storedFilename=${encodeURIComponent(doc.storedFilename)}&downloadName=${encodeURIComponent(doc.originalFilename||doc.displayName||"document")}`);
      if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(d.error||"Download failed");}
      const blob=await r.blob(),link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download=doc.originalFilename||doc.displayName||"document";link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);
    }catch(err){showToast(`Could not download document: ${err.message}`,"error");}
    return;
  }
  if(action!=="delete")return;
  const ok=await themedConfirm(`Delete "${doc.displayName||doc.originalFilename}" from this engagement?`,{title:"Delete Engagement Document",confirmText:"Delete",danger:true});if(!ok)return;
  const config=ensureEngagementConfig(),previousDocuments=config.documents.slice();
  config.documents=config.documents.filter(x=>x.id!==doc.id);persist();
  try{await saveLabState(true);}
  catch(error){config.documents=previousDocuments;persist();renderEngagementDocuments();showToast(`Could not delete document: ${error.message}`,"error");return;}
  try{
    const r=await fetch("/api/delete-engagement-document",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({labName:activeLabName(),storedFilename:doc.storedFilename,extractedFilename:doc.extractedFilename||"",storedFilenames:(doc.revisions||[]).map(row=>row.storedFilename).filter(Boolean)})}),d=await r.json();
    if(!r.ok||!d.ok)throw new Error(d.error||"File cleanup failed");
    showToast("Document deleted.","success");
  }catch(error){showToast(`Document record was deleted, but internal file cleanup must be retried: ${error.message}`,"error");}
  renderEngagementDocuments();
}

async function uploadRoeDocument(){
  const lab=activeLabName(),file=$("roeDocumentFile")?.files?.[0];if(!lab)return showToast("Select and load an engagement first.","error");if(!file)return showToast("Choose a PDF, DOCX, TXT, or Markdown file.","error");
  const c=ensureEngagementConfig(),fd=new FormData();fd.append("labName",lab);fd.append("documentKind",$("roeDocumentKind")?.value||"roe");fd.append("displayName",($("roeDocumentDisplayName")?.value||"").trim());fd.append("knownDocuments",JSON.stringify(roeDocuments()));fd.append("document",file);const btn=$("uploadRoeDocumentBtn");if(btn)btn.disabled=true;
  const previousDocuments=c.documents.slice(),previousScope={selectedDocumentId:c.scope.selectedDocumentId,extractedText:c.scope.extractedText,roeStatus:c.scope.roeStatus};let uploaded=null;
  try{
    const r=await fetch("/api/upload-roe-document",{method:"POST",body:fd});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||"Upload failed");
    uploaded=d.document;upsertVersionedRecord(c.documents,uploaded);c.scope.selectedDocumentId=uploaded.id;c.scope.extractedText=uploaded.extractedText||c.scope.extractedText||"";c.scope.roeStatus="imported-needs-review";persist();
    try{await saveLabState(true);}
    catch(error){c.documents=previousDocuments;Object.assign(c.scope,previousScope);persist();await cleanupUncommittedDocument(lab,uploaded,"/api/delete-roe-document");throw error;}
    $("roeDocumentFile").value="";$("roeDocumentDisplayName").value="";$("roeDocumentFileName").textContent="No file selected.";loadEngagementOptions();renderRoeDocuments();showToast(`${importOutcomeLabel(uploaded)} · ${uploaded.originalFilename}`,"success");
  }catch(e){showToast(`Document upload failed: ${e.message}`,"error");}
  finally{if(btn)btn.disabled=false;}
}
async function handleRoeDocumentAction(e){
  const btn=e.target.closest("[data-roe-action]");if(!btn)return;
  const id=btn.dataset.id,action=btn.dataset.roeAction,doc=roeDocuments().find(d=>d.id===id);if(!doc)return;
  if(action==="review")return loadSelectedRoeText(id);
  if(action==="download"){
    try{
      const url=`/api/download-roe-document?labName=${encodeURIComponent(activeLabName())}&storedFilename=${encodeURIComponent(doc.storedFilename)}&downloadName=${encodeURIComponent(doc.originalFilename||doc.displayName||'engagement-document')}`;
      const r=await fetch(url);if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(d.error||"Download failed");}
      const blob=await r.blob(),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=doc.originalFilename||doc.displayName||"engagement-document";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);
    }catch(err){showToast(`Could not download document: ${err.message}`,"error");}
    return;
  }
  if(action!=="delete")return;
  const ok=await themedConfirm(`Delete "${doc.displayName||doc.originalFilename}" from this engagement?`,{title:"Delete Authorization Document",confirmText:"Delete",danger:true});if(!ok)return;
  const config=ensureEngagementConfig(),previousDocuments=config.documents.slice(),previousScope={selectedDocumentId:config.scope.selectedDocumentId,extractedText:config.scope.extractedText};
  config.documents=config.documents.filter(x=>x.id!==id);if(config.scope.selectedDocumentId===id){config.scope.selectedDocumentId="";config.scope.extractedText="";}persist();
  try{await saveLabState(true);}
  catch(error){config.documents=previousDocuments;Object.assign(config.scope,previousScope);persist();loadEngagementOptions();renderRoeDocuments();showToast(`Could not delete document: ${error.message}`,"error");return;}
  try{
    const r=await fetch("/api/delete-roe-document",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({labName:activeLabName(),storedFilename:doc.storedFilename,extractedFilename:doc.extractedFilename||"",storedFilenames:(doc.revisions||[]).map(row=>row.storedFilename).filter(Boolean)})});const d=await r.json();
    if(!r.ok||!d.ok)throw new Error(d.error||"File cleanup failed");
    showToast("Document deleted.","success");
  }catch(error){showToast(`Authorization record was deleted, but internal file cleanup must be retried: ${error.message}`,"error");}
  loadEngagementOptions();renderRoeDocuments();
}

const STARTING_ACCESS_LABELS={vpn:"VPN / Network","standard-credentials":"Standard Credentials","privileged-credentials":"Privileged Credentials",ssh:"SSH",rdp:"RDP","web-account":"Web Account","domain-account":"Domain Account","local-account":"Local Account","privileged-account":"Privileged Account","internal-foothold":"Internal Foothold","source-code":"Source Code",architecture:"Architecture", "asset-inventory":"Asset Inventory","api-access":"API Access","cloud-access":"Cloud / Tenant",other:"Other"};
const ALL_STARTING_ACCESS_ENTRY_TYPES=["vpn","standard-credentials","privileged-credentials","ssh","rdp","web-account","domain-account","local-account","privileged-account","internal-foothold","source-code","architecture","asset-inventory","api-access","cloud-access","other"];
function startingAccessEntries(){return ensureEngagementConfig().startingAccess.entries;}
function startingAccessLabel(type){return STARTING_ACCESS_LABELS[type]||prettyChoice(type||"other");}
function startingAccessSourceLabel(source){return ({client:"Client Provided",program:"Program Provided",lab:"Lab Provided","internal-team":"Internal Team Provided",other:"Other"})[source]||"Provided";}
function startingAccessEntryMatchesHost(entry,h){
  if(!entry||!h)return false;
  if(entry.hostId)return entry.hostId===h.id;
  const target=String(entry.target||"").trim().toLowerCase();
  if(!target)return true;
  return [h.id,h.ip,h.hostname].filter(Boolean).some(value=>target.includes(String(value).trim().toLowerCase()));
}
function startingAccessMethod(entry){
  const type=String(entry?.type||"").toLowerCase();
  if(type==="ssh")return "SSH";if(type==="rdp")return "RDP";if(type==="internal-foothold")return "Shell";
  return contextFoundation()?.directAccessMethod?.(`${entry?.type||""} ${entry?.name||""} ${entry?.notes||""}`)||"";
}
function startingAccessPrivilege(entry){
  const value=`${entry?.type||""} ${entry?.privilege||""}`;
  return /root|system|administrator|admin|privileged/i.test(value)?"root-admin":"user";
}
function populateStartingAccessHosts(selected=""){
  const el=$("startingAccessHost");if(!el)return;el.innerHTML='<option value="">Not linked to a host</option>';
  Object.entries(state.hosts||{}).forEach(([id,h])=>{const o=document.createElement("option");o.value=id;o.textContent=h.ip||h.hostname||id;el.appendChild(o);});el.value=selected||"";
}
function populateStartingAccessTypes(selected=""){
  const select=$("startingAccessType");if(!select)return;
  const config=ensureEngagementConfig(),oscp=isOscpEngagement();
  const allowed=oscp
    ?(oscpWorkflow()?.startingAccessTypesForAssessment?.(config.assessment)||[])
    :ALL_STARTING_ACCESS_ENTRY_TYPES;
  const values=[...allowed];
  if(selected&&!values.includes(selected))values.push(selected);
  select.innerHTML="";
  values.forEach(value=>{
    const option=document.createElement("option");
    option.value=value;
    option.textContent=`${startingAccessLabel(value)}${selected===value&&!allowed.includes(value)?" (preserved; review)":""}`;
    select.appendChild(option);
  });
  select.value=selected&&values.includes(selected)?selected:(values[0]||"other");
}
function renderStartingAccess(){
  const entries=startingAccessEntries(),list=$("startingAccessList"),summary=$("startingAccessSummary");
  if(summary){const withCreds=entries.filter(x=>x.username||x.secret).length,linked=entries.filter(x=>x.hostId).length;summary.innerHTML=`<div><strong>${entries.length}</strong><span>Provided Items</span></div><div><strong>${withCreds}</strong><span>With Accounts</span></div><div><strong>${linked}</strong><span>Linked Hosts</span></div>`;}
  if(!list)return;
  if(!entries.length){list.innerHTML='<div class="starting-access-empty"><div class="starting-access-empty-icon"><svg viewBox="0 0 24 24"><rect x="5" y="10" width="14" height="10" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v2"/></svg></div><strong>No starting access recorded</strong><p>Add VPN access, supplied credentials, starting footholds, source access, or client-provided materials.</p><button class="primary-btn" type="button" data-starting-access-action="add">Add Starting Access</button></div>';return;}
  list.innerHTML=entries.map(e=>{const host=e.hostId&&state.hosts?.[e.hostId];const detail=[e.target,e.username,e.privilege].filter(Boolean).map(escapeHtml).join(" · ");return `<article class="starting-access-card"><div class="starting-access-card-icon"><svg viewBox="0 0 24 24"><rect x="5" y="10" width="14" height="10" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v2"/></svg></div><div class="starting-access-card-main"><div class="starting-access-card-title"><span class="starting-access-type">${escapeHtml(startingAccessLabel(e.type))}</span><span class="starting-access-provided">${escapeHtml(startingAccessSourceLabel(e.source))}</span></div><h4>${escapeHtml(e.name||startingAccessLabel(e.type))}</h4>${detail?`<p>${detail}</p>`:""}<div class="starting-access-meta">${host?`<span>Host: ${escapeHtml(host.ip||host.hostname||e.hostId)}</span>`:""}${e.secret?'<span>Secret stored</span>':''}${e.notes?'<span>Notes included</span>':''}</div></div><div class="starting-access-actions"><button class="ghost-btn" type="button" data-starting-access-action="edit" data-id="${escapeAttr(e.id)}">Edit</button><button class="danger-btn" type="button" data-starting-access-action="delete" data-id="${escapeAttr(e.id)}">Delete</button></div></article>`;}).join("");
}
function setStartingAccessModalOpen(open,entry=null){
  const modal=$("startingAccessModal");if(!modal)return;modal.classList.toggle("hidden",!open);document.body.classList.toggle("host-modal-open",open||!$("addHostModal")?.classList.contains("hidden"));
  if(!open)return;
  const e=entry||{};$("startingAccessId").value=e.id||"";populateStartingAccessTypes(e.type||"");$("startingAccessName").value=e.name||"";$("startingAccessTarget").value=e.target||"";$("startingAccessUsername").value=e.username||"";$("startingAccessSecret").value=e.secret||"";$("startingAccessPrivilege").value=e.privilege||"";$("startingAccessSource").value=e.source||"client";$("startingAccessEntryNotes").value=e.notes||"";$("startingAccessShowSecret").checked=false;$("startingAccessSecret").type="password";populateStartingAccessHosts(e.hostId||"");$("startingAccessError")?.classList.add("hidden");$("startingAccessModalTitle").textContent=e.id?"Edit Starting Access":"Add Starting Access";setTimeout(()=>$("startingAccessType")?.focus(),30);
}
function saveStartingAccessEntry(){
  const err=$("startingAccessError"),type=$("startingAccessType")?.value||"other",name=($("startingAccessName")?.value||"").trim(),target=($("startingAccessTarget")?.value||"").trim(),username=($("startingAccessUsername")?.value||"").trim();
  if(!name&&!target&&!username){if(err){err.textContent="Enter a display name, target, or username.";err.classList.remove("hidden");}return;}
  const entries=startingAccessEntries(),id=$("startingAccessId")?.value||`access-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,old=entries.find(x=>x.id===id)||{};
  const value={...old,id,type,name:name||startingAccessLabel(type),target,username,secret:$("startingAccessSecret")?.value||"",privilege:($("startingAccessPrivilege")?.value||"").trim(),hostId:$("startingAccessHost")?.value||"",source:$("startingAccessSource")?.value||"client",notes:($("startingAccessEntryNotes")?.value||"").trim(),createdAt:old.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};
  const idx=entries.findIndex(x=>x.id===id);if(idx>=0)entries[idx]=value;else entries.push(value);
  const t=ensureEngagementConfig().startingAccess.types;if(!t.includes(type))t.push(type);
  Object.values(state.hosts||{}).forEach(host=>ensureHostMethodologyContextState(host));persist();renderStartingAccess();renderPeasOrganizer();setStartingAccessModalOpen(false);
}
async function handleStartingAccessAction(e){const btn=e.target.closest("[data-starting-access-action]");if(!btn)return;const action=btn.dataset.startingAccessAction,id=btn.dataset.id;if(action==="add")return setStartingAccessModalOpen(true);const entry=startingAccessEntries().find(x=>x.id===id);if(!entry)return;if(action==="edit")return setStartingAccessModalOpen(true,entry);if(action==="delete"&&(await themedConfirm(`Delete starting access entry "${entry.name||startingAccessLabel(entry.type)}"?`,{title:"Delete Starting Access",confirmText:"Delete",danger:true}))){ensureEngagementConfig().startingAccess.entries=startingAccessEntries().filter(x=>x.id!==id);Object.values(state.hosts||{}).forEach(host=>ensureHostMethodologyContextState(host));persist();renderStartingAccess();renderPeasOrganizer();}}


function reportingFeature(){
  if(reportingController)return reportingController;
  if(!window.AEROSReporting?.create)throw new Error("AEROS reporting module is unavailable.");
  reportingController=window.AEROSReporting.create({
    getState:()=>state,byId:$,createOption:()=>document.createElement("option"),
    ensureEngagementConfig,persistState:persist,saveState:save,ensureLabName:ensureLabNameFromSelect,
    activeLabName,safeFile,escapeHtml,escapeAttr,nl2br,reportCss:REPORT_CSS,
    versionedRecordBadge,importOutcomeLabel,showToast,confirmDelete:themedConfirm,
    alertUser:message=>alert(message),fetch:(...args)=>fetch(...args),
    findingsApi:window.AEROSFindings,
    requiredPrimaryPlacements:value=>window.AEROSFindings.requiredPrimaryPlacements(value),
    validateReportPlacements:value=>window.AEROSFindings.validateCanonicalFindings(value),
    openPlacementIssue:issue=>{
      const asset=window.AEROSFindings.hostForAsset(state,issue?.assetId);
      if(asset?.id)selectCanonicalHost(asset.id,{persistNow:false,renderNow:false,visibleFailure:false});
      setWorkspaceTab("evidence");
      render();
      $("reportFindingsSection")?.scrollIntoView({behavior:"smooth",block:"start"});
    },
    createFormData:()=>new FormData(),createBlob:(parts,options)=>new Blob(parts,options),
    downloadBlob:(blob,filename,revokeDelay=0)=>{
      const anchor=document.createElement("a"),url=URL.createObjectURL(blob);
      anchor.href=url;anchor.download=filename;anchor.click();
      if(revokeDelay>0)setTimeout(()=>URL.revokeObjectURL(url),revokeDelay);else URL.revokeObjectURL(url);
    },
    renderStartingAccess
  });
  return reportingController;
}
