function formatArchiveBytes(bytes){
  const value=Number(bytes)||0;if(value<1024)return `${value} B`;if(value<1024*1024)return `${(value/1024).toFixed(1)} KB`;return `${(value/(1024*1024)).toFixed(1)} MB`;
}
function formatArchiveDate(value){
  if(!value)return "Unknown date";const d=new Date(value);return Number.isNaN(d.getTime())?value:d.toLocaleString();
}
async function refreshEngagementArchives(){
  const list=$("archiveList"),status=$("archiveStatus");if(!list)return;
  list.innerHTML='<div class="archive-empty">Loading archives...</div>';
  try{
    const r=await fetch("/api/list-archives"),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||"Could not list archives");
    const rows=d.archives||[];
    if(!rows.length){list.innerHTML='<div class="archive-empty">No engagement archives found.</div>';return;}
    list.innerHTML=rows.map(a=>`<article class="archive-card${a.invalid?" invalid":""}" data-archive-id="${escapeHtml(a.archiveId)}"><div class="archive-card-main"><span class="archive-card-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 7h16v13H4zM3 4h18v3H3zM9 11h6"/></svg></span><div><strong>${escapeHtml(a.engagementName||a.archiveId)}</strong><small>${escapeHtml(a.clientName||"No client recorded")} · ${escapeHtml(formatArchiveDate(a.archivedAt))}</small><span>${formatArchiveBytes(a.size)}${a.invalid?" · Archive needs review":""}</span></div></div><div class="archive-card-actions"><button class="ghost-btn" data-archive-action="download" type="button">Export ZIP</button><button class="secondary-btn" data-archive-action="restore" type="button"${a.invalid?" disabled":""}>Restore</button><button class="danger-ghost-btn" data-archive-action="delete" type="button">Delete</button></div></article>`).join("");
    list.querySelectorAll("[data-archive-action]").forEach(btn=>btn.onclick=()=>handleArchiveAction(btn.closest("[data-archive-id]")?.dataset.archiveId,btn.dataset.archiveAction));
    if(status)status.textContent=`${rows.length} verified archive${rows.length===1?"":"s"} available.`;
  }catch(e){list.innerHTML=`<div class="archive-empty error">${escapeHtml(e.message)}</div>`;if(status)status.textContent=`Could not load archives: ${e.message}`;}
}
async function createEngagementArchive(removeWorkingCopy){
  const lab=activeLabName();if(!lab)return alert("Select and load an engagement before archiving it.");
  const wording=removeWorkingCopy?"create a verified ZIP and remove the active working copy":"create a verified ZIP and keep the working files in an archived, hidden state";
  if(!(await themedConfirm(`Archive engagement "${lab}"?\n\nThis will ${wording}.`,{title:"Archive Engagement",confirmText:"Create Archive"})))return;
  const status=$("archiveStatus");
  try{
    if(status)status.textContent="Saving and verifying the engagement archive...";
    await saveLabState(true);
    const r=await fetch("/api/archive-project",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({labName:lab,removeWorkingCopy:!!removeWorkingCopy})});
    const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||"Archive failed");
    clearLoadedEngagementView();render();await refreshLabs();await refreshEngagementArchives();
    if(status)status.textContent=`Archived ${lab}: ${formatArchiveBytes(d.size)} ZIP created and verified.`;
    alert(`Archived engagement: ${lab}\n\nArchive created:\n${d.path}`);
  }catch(e){if(status)status.textContent=`Archive failed: ${e.message}`;alert(`Could not archive engagement: ${e.message}`);}
}
async function handleArchiveAction(archiveId,action){
  if(!archiveId)return;
  if(action==="download"){
    try{const r=await fetch(`/api/download-archive?archiveId=${encodeURIComponent(archiveId)}`);if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(d.error||"Download failed");}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`${archiveId}.zip`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){alert(`Could not export archive: ${e.message}`);}return;
  }
  if(action==="restore"){
    const suggested=(archiveId.replace(/_\d{8}-\d{6}_[a-f0-9]{8}$/i,""));const newName=await themedConfirm("Restore this archive as engagement name:",{title:"Restore Engagement",confirmText:"Restore",input:true,inputValue:suggested});if(newName===null)return;if(!newName.trim())return alert("Enter a name for the restored engagement.");
    try{const r=await fetch("/api/restore-archive",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({archiveId,newName:newName.trim()})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||"Restore failed");await refreshLabs();await refreshEngagementArchives();alert(`Restored engagement: ${d.labName}`);}catch(e){alert(`Could not restore archive: ${e.message}`);}return;
  }
  if(action==="delete"){
    if(!(await themedConfirm("Permanently delete this archive ZIP? The working engagement, if one exists, will not be changed.",{title:"Delete Archive",confirmText:"Delete Permanently",danger:true})))return;
    try{const r=await fetch("/api/delete-archive",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({archiveId})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||"Delete failed");await refreshEngagementArchives();}catch(e){alert(`Could not delete archive: ${e.message}`);}
  }
}

