let canonicalWorkflowSaveQueue=Promise.resolve();
function saveCanonicalWorkflowState(subject="The OSCP workflow state",{required=false}={}){
  flushPendingInteractiveEdits({visual:false});
  persist();
  saveActiveProfilePreferences();
  if(!state.serverAvailable||!activeLabName()){
    const error=new Error(`${subject} could not be saved because no exact loaded engagement is available.`);
    if(required)return Promise.reject(error);
    showToast(error.message,"error");
    return Promise.resolve(false);
  }
  const attempt=canonicalWorkflowSaveQueue
    .catch(()=>{})
    .then(()=>saveLabState(true));
  canonicalWorkflowSaveQueue=attempt.catch(()=>{});
  if(required)return attempt;
  return attempt.catch(error=>{
    showToast(`${subject} is retained in this browser, but file storage save failed: ${error.message}`,"error");
    return false;
  });
}

function noteSectionFor(note,h){
  const selected=Object.keys(h.services||{}).filter(k=>h.services[k]?.checked);

  if(note.id==="port-scanning") return {key:"00-scanning",title:"SCANNING",subtitle:"List of Scanning Notes"};
  if(note.id==="report") return {key:"99-report",title:"REPORT EVIDENCE",subtitle:"List of Report Notes"};

  const layoutSection=noteLibraryLayoutSection(note);
  if(layoutSection)return layoutSection;

  if(note.sectionKey&&note.sectionTitle) return {key:note.sectionKey,title:note.sectionTitle,subtitle:note.sectionSubtitle||`List of ${note.sectionTitle} Notes`};
  if(note.requiresDomain || note.tags?.includes("ad")) return {key:"80-ad",title:"ACTIVE DIRECTORY",subtitle:"List of Active Directory Notes"};

  if(note.os==="windows" && note.requiresShell && (!note.services || !note.services.length)){
    return {key:"70-win-99-other",title:"WINDOWS - OTHER",subtitle:"List of Windows Notes"};
  }

  if(note.os==="linux" && note.requiresShell && (!note.services || !note.services.length)){
    return {key:"71-linux-99-other",title:"LINUX - OTHER",subtitle:"List of Linux Notes"};
  }

  const serviceOrder=[
    "http","https","smb","ftp","ssh","smtp","dns","snmp","rdp","winrm",
    "ldap","kerberos","mssql","mysql","postgresql","vnc"
  ];

  const serviceTitles={
    http:"HTTP",
    https:"HTTPS",
    smb:"SMB",
    ftp:"FTP",
    ssh:"SSH",
    smtp:"SMTP",
    dns:"DNS",
    snmp:"SNMP",
    rdp:"RDP",
    winrm:"WINRM",
    ldap:"LDAP",
    kerberos:"KERBEROS",
    mssql:"MSSQL",
    mysql:"MYSQL",
    postgresql:"POSTGRESQL",
    vnc:"VNC"
  };

  const match=(note.services||[]).find(s=>selected.includes(s)) || (note.services||[])[0];

  if(match){
    const idx=serviceOrder.includes(match)?String(serviceOrder.indexOf(match)+10).padStart(2,"0"):"60";
    const title=serviceTitles[match] || match.toUpperCase();
    return {
      key:`${idx}-${match}`,
      title:title,
      subtitle:`List of ${title} Notes`
    };
  }

  return {key:"90-other",title:"OTHER",subtitle:"List of Other Notes"};
}



let currentViewedNoteContent="";

