function toggleNoteViewerSnapped(){
  const overlay=$("noteViewerOverlay");
  if(!overlay)return;
  setNoteViewerSnapped(!overlay.classList.contains("note-viewer-snapped"));
}

function wireDetachedNoteViewerDrag(overlay){
  const modal=overlay?.querySelector(".note-viewer-modal");
  const head=overlay?.querySelector(".note-viewer-head");
  if(!modal||!head||modal.dataset.dragWired==="true")return;
  modal.dataset.dragWired="true";

  let dragging=false;
  let offsetX=0;
  let offsetY=0;

  const stopDrag=(e)=>{
    if(!dragging)return;
    dragging=false;
    if(overlay.classList.contains("note-viewer-minimized"))modal._aerosMinimizedRect=noteWindowRect(modal);
    else modal._aerosNormalRect=noteWindowRect(modal);
    try{head.releasePointerCapture(e.pointerId);}catch{}
  };

  head.addEventListener("pointerdown",e=>{
    if(e.target.closest("button,a,input,textarea,select"))return;
    if(overlay.classList.contains("note-viewer-snapped"))return;

    const rect=modal.getBoundingClientRect();
    dragging=true;
    offsetX=e.clientX-rect.left;
    offsetY=e.clientY-rect.top;

    modal.style.left=`${rect.left}px`;
    modal.style.top=`${rect.top}px`;
    modal.style.right="auto";
    modal.style.bottom="auto";
    modal.style.transform="none";
    modal.style.width=`${rect.width}px`;
    modal.style.height=overlay.classList.contains("note-viewer-minimized")?"auto":`${rect.height}px`;

    try{head.setPointerCapture(e.pointerId);}catch{}
    e.preventDefault();
  });

  head.addEventListener("pointermove",e=>{
    if(!dragging)return;
    const rect=modal.getBoundingClientRect();
    const maxLeft=Math.max(8,window.innerWidth-rect.width-8);
    const maxTop=Math.max(8,window.innerHeight-rect.height-8);
    modal.style.left=`${Math.max(8,Math.min(maxLeft,e.clientX-offsetX))}px`;
    modal.style.top=`${Math.max(8,Math.min(maxTop,e.clientY-offsetY))}px`;
  });

  head.addEventListener("pointerup",stopDrag);
  head.addEventListener("pointercancel",stopDrag);
  modal.addEventListener("pointerdown",()=>{modal.style.zIndex=10000;});
}

