function captureNavigatorView(){
  const current=ensureNavigatorState();if(!current)return null;
  const scroller=workspaceScroller(),focused=document.activeElement?.closest?.("[data-navigator-focus]");
  const next=navigatorCore().normalizeViewState({
    ...current,
    filters:{query:$("navigatorHostSearch")?.value||"",status:$("navigatorHostStatusFilter")?.value||"all"},
    selectedAccessContextId:$("navigatorAccessContextFilter")?.value||current.selectedAccessContextId,
    expandedCardIds:current.expandedCardIds,
    expandedGroupIds:[...document.querySelectorAll("[data-navigator-group][open]")].map(node=>node.dataset.navigatorGroup),
    scrollTop:scroller?.scrollTop||window.scrollY||0,
    focusKey:focused?.dataset.navigatorFocus||current.focusKey||""
  },{validHostIds:navigatorHostIds()});
  state.navigation.navigator={...current,...next};
  persist();return next;
}
function commitNavigatorSkippedActions(records,subject){
  const core=navigatorCore(),navigation=ensureNavigatorState();if(!core||!navigation)return false;
  state.navigation.navigator=core.normalizeNavigationState({...navigation,skippedActions:records},{validHostIds:navigatorHostIds()});
  persist();renderOscpNavigator();
  saveCanonicalWorkflowState(subject).catch(()=>{});
  return true;
}
function skipNavigatorRecommendation(skipKey,evidenceSignature){
  const navigation=ensureNavigatorState(),projection=navigatorProjection();if(!navigation||!projection)return;
  const action=(projection.allActions||[]).find(row=>row.skipKey===skipKey&&row.evidenceSignature===evidenceSignature);
  if(!action){showToast("This recommendation changed before it could be skipped. Review the current action and try again.","warning");renderOscpNavigator();return;}
  const record={skipKey:action.skipKey,evidenceSignature:action.evidenceSignature,hostId:action.owner.hostId,title:action.title,skippedAt:new Date().toISOString()};
  const records=[record,...(navigation.skippedActions||[]).filter(row=>row.skipKey!==record.skipKey)];
  if(commitNavigatorSkippedActions(records,"The skipped Navigator recommendation"))showToast(`${action.title} skipped for now. Its methodology status and imported evidence were not changed.`,"success");
}
function restoreNavigatorRecommendations(skipKey=""){
  const navigation=ensureNavigatorState(),projection=navigatorProjection();if(!navigation||!projection)return;
  const records=navigation.skippedActions||[],focusHostId=projection.focusHostId||navigation.selectedHostId||activeHost()?.id||"";
  const restored=skipKey
    ?records.filter(row=>row.skipKey===skipKey)
    :records.filter(row=>row.hostId===focusHostId);
  if(!restored.length){showToast("That skipped recommendation is no longer retained in the current Navigator state.","warning");renderOscpNavigator();return;}
  const next=skipKey?records.filter(row=>row.skipKey!==skipKey):records.filter(row=>row.hostId!==focusHostId);
  if(commitNavigatorSkippedActions(next,"The restored Navigator recommendation"))showToast(`${restored.length} Navigator recommendation${restored.length===1?"":"s"} restored.`,"success");
}
function navigatorReportBlockers(){return (navigatorReadiness().issues||[]).filter(row=>row?.id);}
