  const unresolved=intake.items.filter(item=>!item.container&&["ambiguous","invalid","target-mismatch","mapping-required","unsupported","failed"].includes(navigatorImportEffectiveDetection(item).status));
  const pending=intake.items.filter(item=>!item.container&&["detecting","inspecting","detected"].includes(navigatorImportEffectiveDetection(item).status));
  if(status){
    status.className=`navigator-import-status${unresolved.length?" is-warning":""}${!host?" is-error":""}`;
    status.textContent=intake.busy?"Importing accepted results through their current workspace owners…":!intake.items.length?"No inputs selected. Detection does not change engagement data.":`${actionable.length} ready · ${pending.length} still validating · ${unresolved.length} excluded until resolved or removed. No engagement records have been written.`;
  }
  if(commit){commit.disabled=intake.busy||!host||!actionable.length||pending.length>0;commit.textContent=intake.busy?"Importing…":`Import accepted results${actionable.length?` (${actionable.length})`:""}`;}
