async function navigatorImportResolvedFile(item){
  if(item.file)return item.file;
  if(!item.archiveToken||!item.path)throw new Error(`${item.name}: staged bytes are unavailable.`);
  const response=await fetch(`/api/read-import-result-member?token=${encodeURIComponent(item.archiveToken)}&member=${encodeURIComponent(item.path)}`);
  if(!response.ok){const detail=await response.json().catch(()=>({}));throw new Error(`${item.name}: ${detail.error||"could not read staged archive member"}`);}
  const blob=await response.blob(),file=new File([blob],item.name,{type:blob.type||"application/octet-stream",lastModified:Date.now()});
  try{Object.defineProperty(file,"webkitRelativePath",{value:item.path,configurable:true});}catch(_error){}
  return file;
}
function navigatorImportMark(items,status,reason=""){
  items.forEach(item=>{item.detection={...navigatorImportEffectiveDetection(item),status,reason:reason||item.detection?.reason||""};});
}
