        const result=await window.AerosScanImportTestHooks?.processFiles?.([file],{host:mappedHost,hostId:mappedHost.id,engagementId:context.engagementId,targetAddress:mapping.target,taskId:objectiveId,mode:"file"});
        if(result?.ok)succeeded++;else errors.push(`${item.name}: no usable Nmap evidence was applied for ${mapping.target}.`);
