        if(capability?.importCapability!=="web-discovery")throw new Error("This canonical objective does not accept web-discovery output.");
        if(!context.originId||!context.endpointId||!context.originUrl)throw new Error("The exact endpoint and origin context is missing or stale.");
        const result=await commitWebDiscoveryFile(loaded.get(item.id),host,context,navigatorImportEffectiveDetection(item));
        if(result?.ok)navigatorImportMark([item],"committed",`Imported through Recon for ${context.originUrl}.`);
