  if(restored.selectedHostId&&!selectCanonicalHost(restored.selectedHostId,{persistNow:false,renderNow:false,visibleFailure:false})){
    return navigatorRouteFailure("The originating Navigator host is missing or stale. No neighboring host was selected.");
  }
  state.navigation.navigator={...navigation,...restored,activeRoute:navigatorCore().normalizeRoute({destination:"navigator"}).route,routeError:""};
  if(state.navigation.workbench)state.navigation.workbench={...state.navigation.workbench,deepReturnActive:false,returnHostId:"",returnRoute:null};
  persist();
