function parseOpenTcpPortsFromText(text){const ports=new Set();[...String(text||"").matchAll(/(\d{1,5})\/tcp\s+open\s+/gi)].forEach(m=>ports.add(Number(m[1])));return [...ports].filter(p=>p>0&&p<=65535).sort((a,b)=>a-b);} 
function selectedTcpPorts(h){const ports=new Set(parseOpenTcpPortsFromText((h?.scans||{}).port||""));parseOpenTcpPortsFromText((h?.scans||{}).tcp||"").forEach(p=>ports.add(p));(h?.scanEvidence?.port?.ports||[]).forEach(p=>{const n=Number(p);if(n>0&&n<=65535)ports.add(n);});(h?.serviceInventory||[]).filter(row=>String(row?.protocol||"tcp").toLowerCase()==="tcp").forEach(row=>{const n=Number(row?.port);if(n>0&&n<=65535)ports.add(n);});Object.values(h?.services||{}).forEach(v=>{if(v&&v.checked){String(v.ports||"").split(/[\s,;/]+/).forEach(p=>{const n=Number(p);if(n>0&&n<=65535)ports.add(n);});}});return [...ports].sort((a,b)=>a-b);}
function selectedUdpPorts(h){const ports=new Set();(h?.scanEvidence?.udp?.ports||[]).forEach(p=>{const n=Number(p);if(n>0&&n<=65535)ports.add(n);});(h?.serviceInventory||[]).filter(row=>String(row?.protocol||"").toLowerCase()==="udp").forEach(row=>{const n=Number(row?.port);if(n>0&&n<=65535)ports.add(n);});return [...ports].sort((a,b)=>a-b);}
