    active:true,source:existing?.source||"exploit-attempt",sourceExploitAttemptId:existing?.sourceExploitAttemptId||attempt.id,sourceExploitAttemptIds:sourceIds,
    accessType:success.resultType,interactiveConfirmed:success.interactiveShell===true,shellStability:success.shellStability,ttyUpgraded:success.ttyUpgraded===true,
    identityConfirmed:!!String(success.principal||"").trim(),acquiredAt:success.obtainedAt||attempt.updatedAt||new Date().toISOString(),
