function findingsFeature(){
  if(findingsController)return findingsController;
  if(!window.AEROSFindings?.create)throw new Error("AEROS findings module is unavailable.");
  findingsController=window.AEROSFindings.create({
    getState:()=>state,byId:$,activeHost,saveState:save,saveLabState,render,
    alertUser:message=>alert(message),confirmDelete:themedConfirm,
    openAttempt:id=>{setWorkspaceTab("evidence");editExploitAttempt(id);},
    escapeHtml,escapeAttr,newId,formValue,setFormValue,clearFormValue
  });
  return findingsController;
}
function renderReportFindings(host){return findingsFeature().render(host);}
function openFindingForExploitAttempt(id){
  const h=activeHost(),attempt=(h?.exploitAttempts||[]).find(row=>row.id===id);
  if(attempt)findingsFeature().openForResult(attempt);
}

