async function importPostexpReconFiles(fileList,options={}){
  const h=options.host||exactHostOwner(options.hostId)?.host||activeHost();if(!h){const error=new Error("Select a host before importing recon data.");if(options.throwOnError)throw error;alert(error.message);return {ok:false,error:error.message};}
  const lockedHostId=String(h.id||""),engagementId=String(options.engagementId||state.projectId||state.projectName||"");
  const files=Array.from(fileList||[]).filter(Boolean);if(!files.length)return;
  const lifecycle=window.AEROSImportLifecycle;
  if(!lifecycle){const error=new Error("The shared AEROS import lifecycle module is unavailable. Reopen the current build.");if(options.throwOnError)throw error;alert(error.message);return {ok:false,error:error.message};}
  setPostexpImportBusy(true);
  try{
    const parsedUploads=[];
    for(const file of files){
      try{parsedUploads.push({file,result:await readPostexpReconUpload(file)});}
      catch(error){throw new Error(`${file.name}: ${String(error.message||error).replace(`${file.name}: `,"")}`);}
    }
    const payloadEntries=[];
    parsedUploads.forEach(({file,result})=>result.payloads.forEach(payload=>{validateAerosReconJson(payload.data);payloadEntries.push({...payload,sourceType:result.sourceType,sourceName:result.sourceName||file.name,uploadName:file.name});}));
    const target=normalizedReconTarget(payloadEntries);
    if(reconTargetMismatch(h,target)){
      throw new Error(`Target mismatch: this collection identifies ${target.hostname||"unknown host"} (${target.primaryAddress||"no address"}), not ${hostLabel(h)}.`);
    }
    if(exactHostOwner(lockedHostId)?.host!==h)throw new Error("The intended host is missing or stale. Nothing was imported.");

    ensureHostIntel(h);
    const importedAt=new Date().toISOString(),results=[];
    for(let index=0;index<h.postExploitation.imports.length;index++){
      const existing=h.postExploitation.imports[index];
      if(existing?.sha256)continue;
      const digest=await lifecycle.sha256Text(lifecycle.stableStringify(existing?.data||{}));
      h.postExploitation.imports[index]=lifecycle.hydrateImportRecord(existing,digest,{observedAt:existing?.importedAt||importedAt});
    }
    for(const entry of payloadEntries){
      const sha256=await lifecycle.sha256Text(lifecycle.stableStringify(entry.data));
      const id=newId("recon-import"),targetAddress=String(target.primaryAddress||options.targetAddress||h.ip||"");
      const incoming={id,engagementId,hostId:lockedHostId,targetAddress,observedTargetAddress:targetAddress,parserType:"aeros-recon",sourceArtifactId:id,sourceRevision:1,objective:String(options.taskId||options.objectiveId||""),filename:entry.filename,sourceArchive:entry.sourceType==="zip"?entry.sourceName:"",sourceType:entry.sourceType,importedAt,firstSeenAt:importedAt,lastSeenAt:importedAt,createdAt:importedAt,updatedAt:importedAt,data:entry.data,sha256,logicalKey:lifecycle.reconLogicalKey(entry.data)};
      results.push(lifecycle.upsertImportRecord(h.postExploitation.imports,incoming,{observedAt:importedAt}));
    }
    const summary=lifecycle.importSummary(results),changed=results.filter(row=>row.outcome==="new"||row.outcome==="updated").map(row=>row.record);
    h.postExploitation.lastImportSummary={...summary,completedAt:importedAt,source:"Imported Recon"};
    save();if(activeHost()===h)renderPostexpImports();
    if(activeLabName())await saveLabState(true).catch(error=>alert(`Recon was attached locally, but disk save failed: ${error.message}`));
    showToast(lifecycle.formatImportSummary(summary,"recon payload"),summary.conflicts?"warning":"success");
    if(changed.length)await applyImportedReconItems(changed,{automatic:true,host:h});
    return {ok:true,summary,hostId:lockedHostId};
  }catch(error){
    if(options.throwOnError)throw error;
    alert(`Recon import failed: ${error.message}`);return {ok:false,error:error.message,hostId:lockedHostId};
  }finally{
    setPostexpImportBusy(false);
  }
}
function renderPostexpImports(){
  const list=$("postexpImportList"),summary=$("postexpImportSummary");if(!list||!summary)return;
  try{renderPeasOrganizer();}catch(error){
    console.error("Could not render PEAS organizer",error);
    setPeasImportStatus(`PEAS organizer could not render: ${error?.message||error}`,"error",false);
    const findings=$("peasFindingList"),meta=$("peasFindingRenderMeta"),more=$("peasLoadMoreFindingsBtn");
    if(findings)findings.innerHTML='<div class="empty-state">The PEAS review list could not be drawn. The retained artifact is still stored. Reload after applying the latest correction.</div>';
    if(meta)meta.textContent="PEAS rendering stopped safely instead of clearing the workspace.";
    if(more)more.hidden=true;
  }
  const h=activeHost();if(!h){summary.innerHTML='<div class="empty-state">Select a host to manage Host Enumeration imports.</div>';list.innerHTML="";return;}
  ensureHostIntel(h);const lifecycle=window.AEROSImportLifecycle;
  const imports=postexpImportsForHost().map(item=>lifecycle?.normalizeImportRecord?lifecycle.normalizeImportRecord(item):item);
  h.postExploitation.imports=imports;
  const revisions=imports.reduce((total,item)=>total+Math.max(1,Number(item.revisionCount)||item.revisions?.length||1),0);
  const observations=imports.reduce((total,item)=>total+Math.max(1,item.importHistory?.length||1),0);
  const last=h.postExploitation.lastImportSummary||{};
  summary.innerHTML=`<div class="postexp-summary-grid"><div><strong>${imports.length}</strong><span>Logical imports</span></div><div><strong>${revisions}</strong><span>Revisions</span></div><div><strong>${observations}</strong><span>Observations</span></div><div><strong>${imports.filter(x=>x.data?.collection?.executedAs?.elevated).length}</strong><span>Elevated</span></div></div>${last.completedAt?`<div class="postexp-last-import-summary"><strong>Last import</strong><span>New: ${Number(last.new)||0}</span><span>Updated: ${Number(last.updated)||0}</span><span>Unchanged: ${Number(last.unchanged)||0}</span><span>Skipped: ${Number(last.skipped)||0}</span><span>Conflicts: ${Number(last.conflicts)||0}</span></div>`:""}`;
  if(!imports.length){list.innerHTML='<div class="empty-state">No AEROS recon ZIP or JSON collection has been imported for this host yet.</div>';return;}
  list.innerHTML=imports.map(item=>{const d=item.data||{},c=d.collection||{},t=d.target||{},sections=Object.keys(d.sections||{}),failed=sections.filter(k=>d.sections[k]?.status==="failed").length,partial=sections.filter(k=>d.sections[k]?.status==="partial").length,schema=d.schema||{},status=item.lastImportStatus||"retained",statusLabel=status==="updated"?"Updated revision":status==="unchanged"?"Unchanged duplicate":status==="new"?"New import":"Retained",sha=String(item.sha256||"");const history=(item.importHistory||[]).slice().reverse().slice(0,10).map(event=>`<li><strong>${escapeHtml(event.outcome||"observed")}</strong><span>Revision ${Number(event.revision)||1} · ${escapeHtml(event.filename||item.filename||"Recon import")}</span><code>${escapeHtml(String(event.sha256||"").slice(0,20))}${event.sha256?"…":""}</code><small>${escapeHtml(event.observedAt||"")}</small></li>`).join("");return `<article class="postexp-import-card" data-import-id="${escapeAttr(item.id)}"><div class="postexp-import-card-head"><div><h4>${escapeHtml(item.filename||"Recon import")}</h4><p>${escapeHtml(t.hostname||"Unknown host")} · ${escapeHtml(t.primaryAddress||"No primary address")}</p></div><div class="postexp-import-badges"><span class="scan-artifact-status">${escapeHtml(statusLabel)}</span><span class="scan-artifact-revision">Revision ${Number(item.currentRevision)||1} of ${Math.max(Number(item.revisionCount)||1,item.revisions?.length||1)}</span><span class="scope-status-badge scope-${c.executedAs?.elevated?"in":"review"}">${c.executedAs?.elevated?"Elevated":"Non-elevated"}</span></div></div><div class="postexp-import-meta"><span>Scope: ${escapeHtml(c.scope||"unknown")}</span><span>Ran as: ${escapeHtml(c.executedAs?.username||"unknown")}</span><span>Collected: ${escapeHtml(c.collectedAt||"")}</span><span>Schema: ${escapeHtml(schema.name||"unknown")} ${escapeHtml(schema.version||"")}</span>${item.sourceArchive?`<span>Archive: ${escapeHtml(item.sourceArchive)}</span>`:""}<span>${sections.length} sections · ${partial} partial · ${failed} failed</span><code title="${escapeAttr(sha)}">SHA-256 ${escapeHtml(sha?sha.slice(0,16)+"…":"unavailable")}</code></div><details class="postexp-import-history"><summary>Identity and revision history</summary><div class="scan-artifact-facts"><span><b>Logical identity</b>${escapeHtml(item.logicalKey||reconCollectionIdentity(item.data))}</span><span><b>First imported</b>${escapeHtml(item.firstSeenAt||item.importedAt||"")}</span><span><b>Last observed</b>${escapeHtml(item.lastSeenAt||"")}</span><span><b>Observations</b>${Math.max(1,item.importHistory?.length||1)}</span></div><ol>${history||"<li>No observation history recorded.</li>"}</ol></details><div class="postexp-import-actions"><button class="primary-btn small" data-import-action="apply" type="button">Apply Imported Recon</button><button class="secondary-btn small" data-import-action="pull" type="button">Review One Field</button><button class="secondary-btn small" data-import-action="download" type="button">Download Current JSON</button><button class="danger-btn small" data-import-action="delete" type="button">Delete</button></div></article>`}).join("");
}
function handlePostexpImportListClick(e){const btn=e.target.closest("[data-import-action]");if(!btn)return;const card=btn.closest("[data-import-id]");const item=postexpImportsForHost().find(x=>x.id===card?.dataset.importId);if(!item)return;const action=btn.dataset.importAction;if(action==="apply")applyImportedRecon(item.id);if(action==="pull")openPostexpPullModal(item.id);if(action==="download"){const blob=new Blob([JSON.stringify(item.data,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=item.filename||"aeros-recon.json";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);}if(action==="delete")deletePostexpImport(item.id);}
