const peasOutputViewerState={importId:"",filename:"",rawText:"",cleanText:"",structured:null,query:"",view:"prioritized",limit:PEAS_OUTPUT_PAGE_SIZE,loading:false,error:""};
function resetPeasOutputViewer(){Object.assign(peasOutputViewerState,{importId:"",filename:"",rawText:"",cleanText:"",structured:null,query:"",view:"prioritized",limit:PEAS_OUTPUT_PAGE_SIZE,loading:false,error:""});renderPeasOutputViewer();}
function peasOutputRecord(){const h=activeHost();return h?ensurePeasOrganizerState(h).imports.find(row=>row.id===peasOutputViewerState.importId):null;}
function peasEmphasisLabel(value){return peasOrganizer()?.EMPHASIS_LABELS?.[value]||({"red-yellow":"High-confidence privilege-escalation lead",red:"Operator review required","light-cyan":"Console-enabled account",blue:"Non-interactive account or mounted device",green:"Baseline or expected system item","light-magenta":"Executing account"})[value]||"No LinPEAS signal";}
