function peasCategoryLabel(value){return ({sudo:"Sudo",suid:"SUID",sgid:"SGID",capabilities:"Capabilities","cron-timers":"Cron / Timers",services:"Services","scheduled-tasks":"Scheduled Tasks",registry:"Registry","token-privileges":"Token Privileges","credentials-secrets":"Credentials / Secrets","writable-paths":"Writable Paths","kernel-os":"Kernel / OS",network:"Network",containers:"Containers",identity:"Users / Identity",software:"Software","av-edr":"AV / EDR","powershell-history":"PowerShell History","interesting-files":"Interesting Files",other:"Other"})[value]||String(value||"Other").replace(/-/g," ");}
