  const cve=source.match(/\b(CVE-\d{4}-\d+)(?:\s*\|\s*Name:\s*([^|]+))?/i);if(cve)return cve[2]?`${cve[1].toUpperCase()} · ${cve[2].trim()}`:cve[1].toUpperCase();
