async function deletePeasImport(id){
  const h=activeHost(),peasState=ensurePeasOrganizerState(h),item=peasState.imports.find(row=>row.id===id);if(!item)return;
  if(!(await themedConfirm(`Delete ${item.filename}? Parsed findings that were manually promoted remain as historical records.`,{title:"Delete PEAS Import",confirmText:"Delete",danger:true})))return;
  const otherPaths=new Set(peasState.imports.filter(row=>row.id!==id).flatMap(row=>peasArtifactRevisionPaths(row.sourceArtifact))),deletePaths=peasArtifactRevisionPaths(item.sourceArtifact).filter(path=>!otherPaths.has(path));
  if(deletePaths.length&&state.serverAvailable){await fetch("/api/delete-peas-artifact",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({storedPaths:deletePaths})}).catch(()=>{});}
  peasState.imports=peasState.imports.filter(row=>row.id!==id);peasState.findings=peasState.findings.filter(finding=>{finding.sources=(finding.sources||[]).filter(source=>source.importId!==id);finding.currentImportIds=(finding.currentImportIds||[]).filter(importId=>importId!==id);if(finding.sources.length)return true;if(["observed","potential-lead"].includes(finding.state))return false;finding.historical=true;finding.sourceDeleted=true;return true;});
  if(peasOutputViewerState.importId===id)resetPeasOutputViewer();
  save();renderPeasOrganizer();renderRecommended(h);if(activeLabName())await saveLabState(true).catch(()=>{});
}
function createPeasEvidenceDraft(finding){
  if(!finding)return;
  const references=peasFindingReferenceLinks(finding);
  setWorkspaceTab("systeminfo");setSysTab("findings");clearSysFindingForm();
  setFormValue("sysFindingTitle",`PEAS ${peasCategoryLabel(finding.category)} — ${finding.path||finding.sectionTitle||"review"}`);
  setFormValue("sysFindingPath",finding.path||"");
  setFormValue("sysFindingContent",`Access context: ${peasAccessContexts(activeHost()).find(row=>row.id===finding.accessContextId)?.principal||"Unknown"}
PEAS section: ${peasDisplayText(finding.sectionTitle||"Unknown")}
Source line ${finding.lineNumber||"?"}:
${peasFindingEvidenceText(finding)}${references.length?`
References:
${references.join("\n")}`:""}`);
  showSysFindingForm(true);$("sysFindingForm")?.scrollIntoView({block:"start"});
}

function handlePeasImportListClick(event){const button=event.target.closest("[data-peas-import-action]");if(!button)return;const card=button.closest("[data-peas-import-id]"),id=card?.dataset.peasImportId;if(button.dataset.peasImportAction==="delete")deletePeasImport(id);if(button.dataset.peasImportAction==="view")openPeasOutput(id,"structured");}
