  fieldSelect.innerHTML=POSTEXP_IMPORT_MAPPINGS.map(x=>`<option value="${escapeAttr(x.section)}">${escapeHtml(x.label)}</option>`).join("");
  activePostexpPull={importId:importSelect.value,section:fieldSelect.value};
  $("postexpPullModal").classList.remove("hidden");refreshPostexpPullModal();
