function exportJson(){save();const blob=new Blob([JSON.stringify(state,null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`${safeFile(state.projectName||"aeros-engagement")}.json`;a.click();URL.revokeObjectURL(a.href);}
function importedEngagementName(name){
  const base=String(name||"Imported Engagement").trim()||"Imported Engagement";
  const existing=new Set((state.labs||[]).map(value=>String(value||"").trim().toLocaleLowerCase()));
  if(!existing.has(base.toLocaleLowerCase()))return base;
  let index=1,candidate="";
  do{candidate=`${base} (Imported${index===1?"":` ${index}`})`;index++;}while(existing.has(candidate.toLocaleLowerCase()));
  return candidate;
}
function importJson(file){
  if(!file)return;
  if(file.size<=0||file.size>50*1024*1024)return alert("JSON backup must be non-empty and no larger than 50 MB.");
  const reader=new FileReader();
  reader.onload=()=>{
    try{
      const imported=window.AEROSPersistence.validateImportedState(JSON.parse(String(reader.result||"")));
      const originalName=imported.projectName;
      imported.projectName=importedEngagementName(originalName);
      persistenceFeature().replaceEngagementState(imported);
      normalizePersistedState();
      setLoadedLabName(imported.projectName);
      persist();render();checkServer();
      if($("labSelect"))$("labSelect").value="__new__";
      $("newEngagementFields")?.classList.remove("hidden");
      showToast(imported.projectName===originalName
        ?`Imported ${imported.projectName} as a new unsaved engagement.`
        :`Imported as ${imported.projectName} so the existing engagement is not overwritten.`,"success");
    }catch(error){alert(`Could not import JSON: ${error.message}`);}
  };
  reader.onerror=()=>alert("Could not read the selected JSON backup.");
  reader.readAsText(file);
}
