function openKernelExploitSearch(){
  const helper=window.AerosKernelExploitHelper;
  if(!helper?.buildSearchPlan){
    showToast("Kernel Exploit Search helper is unavailable.","error");
    return;
  }
  const field=$("sysLinuxOsKernel");
  const source=field?.value||activeHost()?.systemInfo?.linux?.osKernel||"";
  const plan=helper.buildSearchPlan(source);
  if($("kernelSearchDistro"))$("kernelSearchDistro").textContent=plan.distro||"Not detected";
  if($("kernelSearchKernel"))$("kernelSearchKernel").textContent=plan.kernel||"Not detected";
  if($("kernelSearchArchitecture"))$("kernelSearchArchitecture").textContent=plan.architecture||"Not detected";
  if($("kernelSearchCommands"))$("kernelSearchCommands").innerHTML=reviewedCommandGroupsHtml([{label:"Copy-only search strings",commands:plan.commands||[]}]);
  setKernelExploitSearchOpen(true);
}

