function escapeHtml(v){return String(v??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;");}
function escapeAttr(v){return escapeHtml(v).replaceAll("\n"," ")}function nl2br(v){return String(v).replace(/\n/g,"<br>")}function capitalize(v){return v.charAt(0).toUpperCase()+v.slice(1)}function safeFile(v){return String(v||"report").replace(/[^a-z0-9_-]+/gi,"-")}
